import type { Prompt } from "../prompt-types";

export const PRODUCTIVITY_PROMPTS: Prompt[] = [
  // ---- Productivity & Habits (1025) ----
  { id: "productivity-1", title: "Plan a busy office day task by task", category: "productivity", text: "Help me plan a busy office day from [9 am] to [6 pm]. I have these tasks: [list your tasks]. Put the hardest task first, fit in a lunch break, and leave one hour free for urgent work. Show the plan as a simple timetable I can follow." },
  { id: "productivity-2", title: "Time-block a workday around meetings and deadlines", category: "productivity", text: "Make a time-blocked plan for my workday. My meetings are at [times], and I must finish [task] by [deadline]. Block [90 minutes] for focused work, add short breaks between blocks, and show what to do if a meeting runs over time." },
  { id: "productivity-3", title: "Sort this week's tasks by deadline and importance", category: "productivity", text: "Here are my tasks for this week: [list your tasks with dates]. Sort them into four groups: urgent and important, important but not urgent, urgent but not important, and neither. Then tell me which group to start with and what to do first each morning." },
  { id: "productivity-4", title: "Plan a work week with school holidays in mind", category: "productivity", text: "Plan my work week while the children are on school holiday. I work from [time] to [time] and the children are at home. Suggest work blocks, lunch together, and one simple activity for them each day so I can finish my work without constant interruptions." },
  { id: "productivity-5", title: "Plan a field salesman's day across three towns", category: "productivity", text: "Plan one working day for a field salesman visiting [town 1], [town 2] and [town 3]. He starts at [9 am] from [home city]. List the visits in the best order, allow travel time between towns, and add a lunch stop and time to write up orders before going home." },
  { id: "productivity-6", title: "Set up a Pomodoro session for report writing", category: "productivity", text: "Set up a Pomodoro plan to help me write a [10 page] report. Break the work into [25 minute] writing sessions with [5 minute] breaks, and a longer break after four sessions. Tell me what to do in each session so the report is finished by [date]." },
  { id: "productivity-7", title: "Make a do-not-disturb plan for work hours", category: "productivity", text: "Help me make a do-not-disturb plan for my work hours from [time] to [time]. List what to tell family members, which calls to ignore, and what to do if someone interrupts me. Add a simple sign for my door and a plan for checking messages only at set times." },
  { id: "productivity-8", title: "Single-task through a pile of pending bills", category: "productivity", text: "I have a pile of [number] pending bills to check and file. Make a single-task plan so I finish one bill at a time without jumping between them. Give me a simple order to follow, a time limit for each bill, and a way to mark each one done." },
  { id: "productivity-9", title: "Set up a quiet corner for deep work at home", category: "productivity", text: "Help me set up a quiet corner at home for deep work. My space is [describe the room or corner]. Suggest where to put the desk, what light to use, how to cut noise, and what to keep within reach so I can work for [two hours] without moving around." },
  { id: "productivity-10", title: "Break a big report into focused work sessions", category: "productivity", text: "I must write a big report on [topic] by [date]. Break it into small focused work sessions of [45 minutes] each. Give each session one clear job, such as research, writing one part, or checking figures, and show the order to do them in." },
  { id: "productivity-11", title: "Organise work notes in a note-taking app", category: "productivity", text: "Help me organise my work notes in a note-taking app. I have notes about [meetings, ideas and phone numbers]. Suggest a simple folder system, clear names for each note, and a quick way to find any note later. Keep it easy enough to use every day." },
  { id: "productivity-12", title: "Organise digital files into clear work folders", category: "productivity", text: "My computer files are a mess. Help me organise them into clear work folders for [your work areas]. Suggest folder names, what goes in each folder, and a simple rule for naming new files so I can find any document in under a minute." },
  { id: "productivity-13", title: "Clear a crowded email inbox in one hour", category: "productivity", text: "My email inbox has [number] unread messages. Make a one-hour plan to clear it. Tell me which emails to answer first, which to file away, which to delete, and how to set up three simple folders so the inbox stays tidy from tomorrow." },
  { id: "productivity-14", title: "Create a reusable checklist for monthly office tasks", category: "productivity", text: "Make a reusable monthly checklist for my office tasks, such as [paying rent, sending invoices and checking stock]. Put the tasks in order, add a tick box for each one, and leave space for the date done so I can print it and use it every month." },
  { id: "productivity-15", title: "Set up a simple filing system for bills and receipts", category: "productivity", text: "Help me set up a simple filing system for bills and receipts at my [shop / office]. Suggest folders for electricity, rent, suppliers and tax, and a rule for filing each paper on the day it arrives so nothing gets lost before the month ends." },
  { id: "productivity-16", title: "Plan a short team meeting with a clear agenda", category: "productivity", text: "Plan a [30 minute] team meeting about [topic]. Write a short agenda with three points, give each point a time limit, and list what each person should bring. Add one line to end the meeting with clear next steps and who does what." },
  { id: "productivity-17", title: "Draft a polite work email to a client", category: "productivity", text: "Draft a polite work email to a client about [subject]. The email should thank them, explain [the main point] in two short lines, and ask for a reply by [date]. Keep the tone friendly and professional, and suggest a short subject line for the email." },
  { id: "productivity-18", title: "Write a short weekly work report for your manager", category: "productivity", text: "Help me write a short weekly work report for my manager. I worked on [list your main tasks] this week. Show what I finished, what is still pending, and what I plan next week, all in simple bullet points that take less than five minutes to read." },
  { id: "productivity-19", title: "Prepare slides for a small team presentation", category: "productivity", text: "Help me prepare slides for a [10 minute] team presentation on [topic]. Plan [6 slides]: a title slide, three main points, one example, and a closing slide. Give a heading and two short bullet points for each slide in simple words." },
  { id: "productivity-20", title: "Set up a home office in a small room", category: "productivity", text: "Help me set up a home office in a small room of [size]. I need space for a laptop, files and a printer. Suggest where to place the desk, how to store papers, what light to use, and three low-cost items that make the room comfortable to work in." },
  { id: "productivity-21", title: "Plan work around your most energetic hours", category: "productivity", text: "Help me plan my work around my most energetic hours. I feel sharpest at [morning / afternoon / evening] and tired at [time]. Put hard tasks in my sharp hours, easy tasks in my tired hours, and add a short rest in between so I stay fresh all day." },
  { id: "productivity-22", title: "Break a delayed project into small next steps", category: "productivity", text: "My project on [topic] is delayed and feels too big to start. Break it into small next steps I can do in [30 minutes] each. List the steps in order, mark the first step clearly, and tell me how to track progress after each step is done." },
  { id: "productivity-23", title: "Plan short breaks into a long workday", category: "productivity", text: "Plan short breaks into my long workday from [9 am] to [7 pm]. Suggest a [5 minute] break every hour, a proper lunch break, and one short walk in the afternoon. Explain what to do in each break so I return to work feeling fresh." },
  { id: "productivity-24", title: "Track progress on a month-long work project", category: "productivity", text: "Help me track progress on a month-long work project about [topic]. Make a simple weekly tracker with four rows, one for each week. For each week, list the target, the work done, and what is left, so I can see at a glance if I am on time." },
  { id: "productivity-25", title: "Finish a half-done project before a deadline", category: "productivity", text: "I have a half-done project on [topic] due on [date]. Make a finish plan that lists what is already done, what is still left, and how many hours each remaining part needs. Then give me a day-by-day schedule so the project is finished two days early." },
  { id: "productivity-26", title: "A paper task list for a busy shop day", category: "productivity", text: "Make a simple paper task list for my small shop in [your town] for tomorrow. Include opening the shop, checking stock, calling two suppliers, collecting pending payments, and closing tasks. Keep it to ten items, in the order I should do them, with a tick box beside each one." },
  { id: "productivity-27", title: "A phone task list for a working mother", category: "productivity", text: "Help me make a phone task list for tomorrow as a working mother in [your city]. I leave home at [time], pick up my child at [time], and need time for cooking, office work, and homework help. Sort the tasks by time of day and keep the list short and clear." },
  { id: "productivity-28", title: "Three must-do tasks before anything else", category: "productivity", text: "Help me pick just three must-do tasks for tomorrow from my long list: [list your tasks]. Tell me which three matter most, why each one comes first, and what I can safely leave for another day. Keep the answer short, honest, and easy to follow." },
  { id: "productivity-29", title: "A daily list that fits on one page", category: "productivity", text: "Make a one-page daily task list for [describe your day] that fits on a single sheet of paper. Use short lines, leave space to tick each task off, and add a small box at the bottom for notes. Keep the total under twelve tasks so the day feels doable." },
  { id: "productivity-30", title: "Split a long task list into morning and evening", category: "productivity", text: "Split my task list for tomorrow into morning and evening parts: [list your tasks]. Put the hard or outdoor jobs in the morning and the easy or home jobs in the evening. Give each part a clear heading and keep both parts short enough to finish." },
  { id: "productivity-31", title: "A task list for a student before exams", category: "productivity", text: "Make a task list for a school student in [class] who has exams in [number] weeks. Include revision, sample papers, and rest breaks, spread across the day. Keep the list simple, with no more than eight tasks, and add a tick box beside each one." },
  { id: "productivity-32", title: "A list for a homemaker's full day at home", category: "productivity", text: "Make a task list for a homemaker in [your city] for a full day at home. Cover cooking, cleaning, children's school work, and one hour of rest. Put the tasks in time order, keep them short, and leave one free hour in the afternoon." },
  { id: "productivity-33", title: "A task list for a farmer's market day", category: "productivity", text: "Make a task list for a farmer going to the mandi in [your town] tomorrow. Include loading the produce, checking prices, carrying cash and bags, selling, and buying seeds on the way back. Order the tasks by time and keep the list short and clear." },
  { id: "productivity-34", title: "Turn a messy list into a clean ordered list", category: "productivity", text: "Turn my messy task list into a clean, ordered list: [paste your list]. Remove repeated items, group similar jobs together, and put the most urgent ones first. Give me the final list in simple numbered lines that I can copy and tick off." },
  { id: "productivity-35", title: "A task list with timings for each job", category: "productivity", text: "Add a time to each task on my list for tomorrow: [list your tasks]. I start at [time] and finish at [time]. Give each job a start time and a rough length, leave a lunch break, and make sure the total fits inside my working hours." },
  { id: "productivity-36", title: "A weekend task list for pending home jobs", category: "productivity", text: "Make a weekend task list for pending home jobs: [list the jobs]. Sort them into Saturday and Sunday, put the quick jobs first, and keep each day under five tasks. Add a note for any job that needs a shop visit or a worker." },
  { id: "productivity-37", title: "A task list for day one at a new job", category: "productivity", text: "Make a task list for my first day at a new job as a [job role] in [your city]. Include what to carry, whom to meet, questions to ask, and things to note down. Keep it short, calm, and in the order I will need it through the day." },
  { id: "productivity-38", title: "A daily list for a worker with a long commute", category: "productivity", text: "Make a daily task list for an office worker in [your city] who travels [number] hours to work. Fit the tasks around the commute, add jobs I can do on the train or bus, and keep the evening list short so I still get rest." },
  { id: "productivity-39", title: "A list that separates work jobs from home jobs", category: "productivity", text: "Split my tasks for tomorrow into two clear lists, work jobs and home jobs: [list your tasks]. Keep each list under eight items, put the urgent jobs at the top of each list, and add one small easy job to each list so I can start quickly." },
  { id: "productivity-40", title: "A task list for a shopkeeper on a festival day", category: "productivity", text: "Make a task list for a shopkeeper in [your town] on a festival day like [festival]. Include opening early, extra stock, cash change, staff duties, and closing late. Keep it to ten tasks in time order, with the busiest hours clearly marked." },
  { id: "productivity-41", title: "A simple list for a day with many small errands", category: "productivity", text: "Make a simple list for a day full of small errands in [your city]: [list the errands]. Group the errands by area so I do not travel back and forth, and put them in the best order to save time and fuel." },
  { id: "productivity-42", title: "A short task list for a new mother", category: "productivity", text: "Make a short task list for a new mother at home with a [number]-month-old baby. Include feeding, naps, washing, and one rest break for the mother. Keep it to six tasks, in a gentle order, with no fixed times — just a simple flow for the day." },
  { id: "productivity-43", title: "A revision task list for each exam day", category: "productivity", text: "Make a revision task list for a student with exams on [dates]. Give a short list for each day before the exam, with one subject per day, a sample paper, and a break. Keep each day's list under six tasks so it stays doable." },
  { id: "productivity-44", title: "A list for preparing a small family function", category: "productivity", text: "Make a task list for preparing a small family function at home in [your city] for [number] guests. Include cleaning, food, seating, and welcoming guests, spread over two days. Keep each day's list short, in time order, with tick boxes." },
  { id: "productivity-45", title: "A task list that starts with the hardest job", category: "productivity", text: "Arrange my task list for tomorrow so the hardest job comes first: [list your tasks]. Put the tough jobs early, the easy jobs later, and add a short break after each hard job. Keep the list simple and in the order I should follow." },
  { id: "productivity-46", title: "A daily list for a delivery driver", category: "productivity", text: "Make a daily task list for a delivery driver in [your city] with [number] deliveries. Include checking the vehicle, sorting parcels by area, fuel, and end-of-day cash counting. Order the tasks by time and keep the list short and clear." },
  { id: "productivity-47", title: "A task list for a tailor with many orders", category: "productivity", text: "Make a task list for a tailor in [your town] with [number] pending orders. Sort the orders by delivery date, add time for cutting, stitching, and trying on, and leave one hour for new customers. Keep the list in clear date order." },
  { id: "productivity-48", title: "A task list for a day with guests", category: "productivity", text: "Make a task list for a day when guests are visiting my home in [your city]. Include cleaning, cooking, snacks, and setting up a room for them. Put the tasks in time order from morning to evening, and keep the list short so the day stays relaxed." },
  { id: "productivity-49", title: "A task list for a student on a school holiday", category: "productivity", text: "Make a task list for a school student on a holiday in [your city]. Mix homework, reading, play, and helping at home, with breaks in between. Keep it to eight tasks, in a simple order, and add one fun job so the day feels good." },
  { id: "productivity-50", title: "A list for the day before a train journey", category: "productivity", text: "Make a task list for the day before a train journey from [city] to [city]. Include packing, tickets, food, charging the phone, and reaching the station early. Put the tasks in the order I should do them and keep the list short." },
  { id: "productivity-51", title: "A task list for a street vendor's morning", category: "productivity", text: "Make a task list for a street vendor in [your city] for the morning. Include buying fresh stock, setting up the stall, arranging change, and serving the first customers. Order the tasks by time from [time] to [time] and keep it short." },
  { id: "productivity-52", title: "A list that keeps only six tasks a day", category: "productivity", text: "Help me cut my long task list down to only six tasks for tomorrow: [paste your list]. Pick the six that matter most, tell me why each one stays, and move the rest to another day. Give me the final six in the order I should do them." },
  { id: "productivity-53", title: "A task list for a teacher's school day", category: "productivity", text: "Make a task list for a school teacher in [your city] for a full school day. Include lesson preparation, classes, correcting notebooks, and talking to parents. Put the tasks in time order from morning assembly to home time, and keep it short." },
  { id: "productivity-54", title: "A list for sorting tasks by place: home, shop, market", category: "productivity", text: "Sort my tasks for tomorrow by place — home, shop, and market: [list your tasks]. Put each task under the right place, order the places to save travel, and keep each group short so I can finish one place before moving on." },
  { id: "productivity-55", title: "A task list for a retired person", category: "productivity", text: "Make a task list for a retired person in [your city] for a full day. Include a morning walk, reading, a visit to the bank or market, rest, and an evening chat with family. Keep it to seven gentle tasks, in time order, with plenty of rest." },
  { id: "productivity-56", title: "Set out tomorrow's jobs before sleeping", category: "productivity", text: "Help me set out tomorrow's jobs before I sleep tonight. My jobs are: [list them]. Put them in the order I should start, note anything I must carry, and tell me the one job to begin with at [time] so the morning starts smoothly." },
  { id: "productivity-57", title: "A ten-minute night plan for a busy parent", category: "productivity", text: "Make a ten-minute night plan for a busy parent in [your city]. Help me choose tomorrow's top three jobs, lay out the children's school things, and set the morning alarm. Keep the plan to five quick steps I can finish before bed." },
  { id: "productivity-58", title: "Prepare tomorrow's tiffin and bag tonight", category: "productivity", text: "Help me prepare for tomorrow night: pack my child's tiffin, lay out school clothes, charge my phone, and keep my work bag ready. Give me a short checklist in the order I should do these jobs, so the morning is calm and quick." },
  { id: "productivity-59", title: "Check tomorrow's calendar before bed", category: "productivity", text: "Help me check tomorrow's calendar before bed. My events are: [list them]. Tell me what needs preparation tonight, what time I must leave home, and anything that clashes. Give me a short list of things to get ready now." },
  { id: "productivity-60", title: "A night-before plan for a shop opening", category: "productivity", text: "Make a night-before plan for opening my shop in [your town] tomorrow. Include checking stock, keeping change ready, noting pending orders, and setting the opening time. Keep it to six steps in the order I should do them tonight." },
  { id: "productivity-61", title: "Pick tomorrow's first job tonight", category: "productivity", text: "Help me pick the first job I should do tomorrow morning from this list: [list your jobs]. Tell me which one to start with, why it comes first, and what I should keep ready tonight so I can begin at [time] without delay." },
  { id: "productivity-62", title: "A night plan for a student with a test tomorrow", category: "productivity", text: "Make a night-before plan for a student who has a test tomorrow in [subject]. Include a short revision, packing the school bag, keeping pens ready, and an early bedtime. Keep the plan to five calm steps and add a morning reminder." },
  { id: "productivity-63", title: "Set tomorrow's meeting notes ready tonight", category: "productivity", text: "Help me get ready tonight for my meetings tomorrow: [list the meetings]. For each meeting, note what I must carry, the key point to raise, and the time. Give me a short checklist I can tick off before I sleep." },
  { id: "productivity-64", title: "A night plan for a farmer's early morning", category: "productivity", text: "Make a night-before plan for a farmer who must start work at [time] tomorrow in [your village]. Include keeping tools ready, checking the water pump, and preparing food for the field. Keep it to six steps in the order to do them tonight." },
  { id: "productivity-65", title: "Write tomorrow's plan in five lines", category: "productivity", text: "Help me write tomorrow's plan in just five lines. My day includes: [describe your day]. Put the most important job first, then the rest in time order, and keep each line short so I can read it in one glance in the morning." },
  { id: "productivity-66", title: "A night plan for a homemaker's busy morning", category: "productivity", text: "Make a night-before plan for a homemaker in [your city] with a busy morning ahead. Include soaking dal or rice, laying out clothes, and keeping the children's bags ready. Keep it to five steps I can finish in fifteen minutes." },
  { id: "productivity-67", title: "Plan tomorrow around a doctor's appointment", category: "productivity", text: "Help me plan tomorrow around a doctor's appointment at [time] in [your city]. Fit my work, cooking, and travel around the visit, and tell me what to carry. Keep the plan in time order, from morning to evening, with the visit clearly marked." },
  { id: "productivity-68", title: "A night plan for a long train journey tomorrow", category: "productivity", text: "Make a night-before plan for a train journey tomorrow from [city] to [city] at [time]. Include tickets, ID proof, food, water, and charging the phone. Keep it to seven steps in the order I should finish them tonight." },
  { id: "productivity-69", title: "Decide tomorrow's work clothes and tools tonight", category: "productivity", text: "Help me decide tonight what I need for tomorrow's work as a [job role]. List the clothes, tools, papers, and food to keep ready, in a short checklist. Add one reminder for the morning so nothing important is left behind." },
  { id: "productivity-70", title: "A night plan for a festival morning at home", category: "productivity", text: "Make a night-before plan for a festival morning at home for [festival]. Include cleaning the puja place, keeping flowers and fruits ready, and laying out clothes. Keep it to six steps in the order to do them tonight." },
  { id: "productivity-71", title: "Set a wake-up time that fits tomorrow's jobs", category: "productivity", text: "Help me choose a wake-up time for tomorrow. My first job starts at [time] and I need [number] minutes to get ready, plus travel of [number] minutes. Tell me what time to wake up, what time to leave, and what to keep ready tonight." },
  { id: "productivity-72", title: "A night plan for an early school function", category: "productivity", text: "Make a night-before plan for a school function tomorrow at [time] in [your city]. Include the child's dress, food, water bottle, and the parent's timing. Keep it to six steps in order, with one reminder for the morning." },
  { id: "productivity-73", title: "Plan tomorrow's cooking before you sleep", category: "productivity", text: "Help me plan tomorrow's cooking tonight. The meals are [breakfast, lunch, dinner], and I have [ingredients at home]. Tell me what to soak or chop tonight, and give a short morning cooking order so the food is ready on time." },
  { id: "productivity-74", title: "A night plan for a job interview tomorrow", category: "productivity", text: "Make a night-before plan for a job interview tomorrow at [time] in [your city] for a [job role]. Include documents, clothes, the route, and three questions to ask. Keep it to six calm steps in the order to finish them tonight." },
  { id: "productivity-75", title: "End the day by writing tomorrow's first three jobs", category: "productivity", text: "Help me end today by writing tomorrow's first three jobs. My pending jobs are: [list them]. Pick the three that matter most, put them in order, and tell me what to keep ready tonight for the first one." },
  { id: "productivity-76", title: "Block two morning hours for uninterrupted work", category: "productivity", text: "Help me block two hours in the morning for uninterrupted work on [task]. I start at [time]. Tell me how to protect that time, what to switch off, and what to do in the hour before and after so the block really happens." },
  { id: "productivity-77", title: "A simple weekly calendar for a small shop", category: "productivity", text: "Make a simple weekly calendar for my small shop in [your town]. Mark the opening hours, the weekly market day, the supplier visit, and the day I count cash. Keep it in a clear table I can pin on the wall." },
  { id: "productivity-78", title: "Split a work day into morning, noon and evening blocks", category: "productivity", text: "Help me split my work day into three blocks — morning, noon, and evening — for [describe your work]. Put the hardest jobs in the morning block, meetings at noon, and small jobs in the evening. Give each block a start and end time." },
  { id: "productivity-79", title: "Use a wall calendar to track a full month", category: "productivity", text: "Help me use a wall calendar to track a full month of [work or study]. Mark the important dates — [list them] — and add a small note for each one. Tell me how to check the calendar each morning in under two minutes." },
  { id: "productivity-80", title: "Block time for cooking, work and rest each day", category: "productivity", text: "Help me block time each day for cooking, work, and rest. I wake at [time] and sleep at [time]. Give each part a clear time slot, leave gaps between them, and make sure there is at least one hour of rest in the day." },
  { id: "productivity-81", title: "A calendar routine for a family with two school children", category: "productivity", text: "Make a calendar routine for a family with two school children in [your city]. Mark school timings, homework hours, meal times, and one family hour. Keep it simple enough to follow on a busy weekday and show it as a clear daily timetable." },
  { id: "productivity-82", title: "Block thirty minutes for phone calls and messages", category: "productivity", text: "Help me block thirty minutes each day for phone calls and messages about [work or family]. I am free at [time]. Tell me how to collect all the calls into that one block, what to say if someone calls outside it, and how to finish on time." },
  { id: "productivity-83", title: "A time-block plan for a tailor's working day", category: "productivity", text: "Make a time-block plan for a tailor in [your town] who works from [time] to [time]. Block time for cutting, stitching, trying on, and new orders. Leave a lunch break and one free hour, and show the plan as a simple timetable." },
  { id: "productivity-84", title: "Keep a shared family calendar on the fridge", category: "productivity", text: "Help me keep a shared family calendar on the fridge for [number] people in [your city]. List what each person must add — school events, work timings, doctor visits — and tell me how we check it together every Sunday evening in five minutes." },
  { id: "productivity-85", title: "Block one hour for accounts and bills every week", category: "productivity", text: "Help me block one hour every week for accounts and bills for my [shop / home]. Pick the best day and time, list the jobs — checking cash, paying bills, noting dues — and tell me how to finish them all inside that single hour." },
  { id: "productivity-86", title: "A time-block plan for a student during holidays", category: "productivity", text: "Make a time-block plan for a school student during the holidays in [your city]. Block time for study, play, reading, and helping at home, with a long lunch break. Keep the blocks simple, with free time every evening." },
  { id: "productivity-87", title: "Colour-code a calendar by work, family and money", category: "productivity", text: "Help me colour-code my calendar by work, family, and money jobs. My events this week are: [list them]. Give each group a colour, tell me how to mark them on paper or on a phone, and show me how to spot a crowded day at a glance." },
  { id: "productivity-88", title: "Block time for a weekly market visit and stock check", category: "productivity", text: "Help me block time each week for a market visit and a stock check for my shop in [your town]. Pick the best day, list what to check — stock, prices, and pending orders — and tell me how to finish both jobs in one trip." },
  { id: "productivity-89", title: "A calendar plan for a month of school exams", category: "productivity", text: "Make a calendar plan for a month of school exams for a student in [class]. Mark each exam date, add revision days before it, and leave one rest day each week. Show it as a simple month table I can stick on the wall." },
  { id: "productivity-90", title: "Block the first hour for the hardest job", category: "productivity", text: "Help me block the first hour of my work day for the hardest job: [describe the job]. I start at [time]. Tell me how to keep that hour free, what to prepare the night before, and what to do if someone interrupts me." },
  { id: "productivity-91", title: "A time-block plan for a homemaker with a part-time job", category: "productivity", text: "Make a time-block plan for a homemaker in [your city] with a part-time job from [time] to [time]. Block time for cooking, the job, children's homework, and rest. Keep the plan simple, with one free hour in the evening." },
  { id: "productivity-92", title: "Plan each day in a small diary", category: "productivity", text: "Help me plan each day in a small diary. I wake at [time]. Show me a simple diary layout — date, three main jobs, and timings — and tell me how to fill it in five minutes each morning and check it once in the evening." },
  { id: "productivity-93", title: "Block time for travel between two jobs", category: "productivity", text: "Help me block time for travel between my two jobs in [your city]. I finish the first at [time] and start the second at [time], and the trip takes [number] minutes. Tell me what to carry, what to do on the way, and how to avoid being late." },
  { id: "productivity-94", title: "A calendar for a small business with weekly deliveries", category: "productivity", text: "Make a calendar for a small business in [your town] with deliveries on [days]. Mark delivery days, order days, payment days, and one closed day. Show it as a clear weekly table that my staff and I can both follow." },
  { id: "productivity-95", title: "Block a quiet hour before the shop opens", category: "productivity", text: "Help me block a quiet hour before my shop opens at [time] in [your town]. Tell me what to do in that hour — checking stock, cleaning, and noting the day's orders — so the shop is fully ready when the first customer walks in." },
  { id: "productivity-96", title: "A time-block plan for a farmer's irrigation day", category: "productivity", text: "Make a time-block plan for a farmer's irrigation day in [your village]. Block time for starting the pump, checking the channels, moving water between fields, and resting at noon. Keep it simple, with timings for each block." },
  { id: "productivity-97", title: "A day with two shifts and a break", category: "productivity", text: "Help me plan a day with two work shifts — morning from [time] to [time] and evening from [time] to [time] — in [your city]. Tell me how to use the break between shifts for food, rest, and one small home job, without feeling rushed." },
  { id: "productivity-98", title: "Block Sunday morning for the whole week's planning", category: "productivity", text: "Help me block Sunday morning from [time] to [time] for planning the whole week. List what to do in that time — check the calendar, make the task list, and note shopping needs — and tell me how to keep it under one hour." },
  { id: "productivity-99", title: "A calendar that shows school holidays and work days", category: "productivity", text: "Help me make a calendar that shows school holidays and work days together for [month] in [your city]. Mark the holidays, my work days, and the days I must arrange childcare. Keep it clear enough for the whole family to read." },
  { id: "productivity-100", title: "Block time for a weekly family meeting at home", category: "productivity", text: "Help me block thirty minutes each week for a family meeting at home in [your city]. Tell me the best time, what to talk about — the week's jobs, money, and school — and how to keep the meeting short and useful for everyone." },
  { id: "productivity-101", title: "A time-block plan for a delivery driver's route day", category: "productivity", text: "Make a time-block plan for a delivery driver in [your city] with deliveries from [time] to [time]. Block time for loading, the morning route, lunch, and the evening route. Leave time for fuel and a short rest in between." },
  { id: "productivity-102", title: "Use a phone calendar with alerts for every job", category: "productivity", text: "Help me use a phone calendar with alerts for every job this week: [list the jobs]. Tell me how to add each job, set an alert thirty minutes before it, and check the calendar each night so nothing is missed." },
  { id: "productivity-103", title: "Block time for studying after school every day", category: "productivity", text: "Help me block time for studying after school every day for a student in [class]. School ends at [time]. Give a study block, a break, and a homework block, and tell me how to keep the same timings every weekday." },
  { id: "productivity-104", title: "A calendar plan for a shop's festival season", category: "productivity", text: "Make a calendar plan for my shop in [your town] for the festival season around [festival]. Mark the busy days, stock-order days, staff holidays, and the closing day. Show it as a clear month table I can pin behind the counter." },
  { id: "productivity-105", title: "Block one evening a week for pending paperwork", category: "productivity", text: "Help me block one evening a week for pending paperwork — bills, forms, and school papers. Pick the best evening, list the papers to finish, and tell me how to clear the pile in one hour without leaving it for next week." },
  { id: "productivity-106", title: "Sort today's jobs into urgent and important", category: "productivity", text: "Help me sort today's jobs into urgent and important: [list your jobs]. Put each job in the right group, tell me which group to do first, and which jobs I can leave for tomorrow. Keep the answer in four clear groups." },
  { id: "productivity-107", title: "Pick the one job that matters most today", category: "productivity", text: "Help me pick the one job that matters most today from this list: [list your jobs]. Tell me why it matters more than the others, what happens if I delay it, and how much time to give it first thing in the morning." },
  { id: "productivity-108", title: "A simple four-box chart for sorting work tasks", category: "productivity", text: "Make a simple four-box chart for sorting my work tasks: urgent and important, important but not urgent, urgent but not important, and neither. Place my tasks — [list them] — in the right boxes and tell me what to do with each box." },
  { id: "productivity-109", title: "Decide what to do first on a crowded Monday", category: "productivity", text: "Help me decide what to do first on a crowded Monday. My jobs are: [list them]. Rank them by what is due first and what matters most, tell me the top three, and show me what to move to Tuesday without harm." },
  { id: "productivity-110", title: "Sort shop jobs by what earns money first", category: "productivity", text: "Help me sort my shop jobs today by what earns money first: [list the jobs]. Put the money-earning jobs at the top, the must-do jobs next, and the nice-to-have jobs last. Tell me which jobs I can safely skip today." },
  { id: "productivity-111", title: "A priority list for a student with too much homework", category: "productivity", text: "Make a priority list for a student in [class] with too much homework tonight: [list the subjects]. Put the work due tomorrow first, then the long tasks, and tell me how to split the work into short sittings with breaks." },
  { id: "productivity-112", title: "Pick one of two urgent jobs due today", category: "productivity", text: "Help me choose between two urgent jobs that are both due today: [describe job one] and [describe job two]. Compare what happens if each one is late, tell me which to do first, and show me how to finish the second one later today." },
  { id: "productivity-113", title: "A priority plan for a homemaker with a full day", category: "productivity", text: "Make a priority plan for a homemaker in [your city] with a full day ahead. Sort the jobs — cooking, cleaning, children, and rest — by what must happen first, and tell me what to leave for tomorrow if the day gets too full." },
  { id: "productivity-114", title: "Rank a farmer's jobs by season and urgency", category: "productivity", text: "Help me rank a farmer's jobs this week by season and urgency: [list the jobs]. Put the time-sensitive jobs first — sowing, watering, and selling — and tell me which jobs can wait a few days without harm to the crop." },
  { id: "productivity-115", title: "A priority list for the week before a wedding", category: "productivity", text: "Make a priority list for the week before a wedding in the family in [your city]. Sort the jobs — venue, food, guests, and outfits — by what must be fixed first, and tell me what to check each day so nothing is missed." },
  { id: "productivity-116", title: "Sort tasks by deadline, not by how easy they are", category: "productivity", text: "Help me sort my tasks by deadline, not by how easy they are: [list your tasks with due dates]. Put the nearest deadline first, tell me how much time each one needs, and show me which easy jobs I should stop doing first." },
  { id: "productivity-117", title: "A priority list for a new shop's opening week", category: "productivity", text: "Make a priority list for the opening week of my new shop in [your town]. Sort the jobs — stock, signboard, licence, and first customers — by what must be ready first, and give me a short list for each day of the week." },
  { id: "productivity-118", title: "Decide what to drop when the day is overfull", category: "productivity", text: "Help me decide what to drop when my day is overfull. My jobs are: [list them]. Tell me which ones to move to tomorrow, which ones to ask someone else to do, and which ones to skip this week without any harm." },
  { id: "productivity-119", title: "A priority list for a teacher before term exams", category: "productivity", text: "Make a priority list for a teacher in [your city] before term exams. Sort the jobs — question papers, revision, marks, and parent calls — by what is due first, and tell me how to fit them into the days before the exams start." },
  { id: "productivity-120", title: "Sort family jobs by who must do them", category: "productivity", text: "Help me sort this week's family jobs by who must do them: [list the jobs]. Put each job under the right person — me, my spouse, or the children — and tell me which jobs need two people and which ones I can do alone." },
  { id: "productivity-121", title: "A priority list for a small business owner on Monday", category: "productivity", text: "Make a priority list for a small business owner in [your town] on a Monday morning. Sort the jobs — cash, orders, staff, and suppliers — by what keeps the business running, and tell me the three jobs to finish before noon." },
  { id: "productivity-122", title: "Rank jobs by money, time and effort needed", category: "productivity", text: "Help me rank my jobs by money, time, and effort needed: [list your jobs]. Give each job a simple score for each one, then tell me which jobs to do first and which ones to leave for a quieter day." },
  { id: "productivity-123", title: "A priority plan for moving house in one week", category: "productivity", text: "Make a priority plan for moving house in one week from [area] to [area] in [your city]. Sort the jobs — packing, transport, cleaning, and address change — by what must happen first, and give me a short list for each day." },
  { id: "productivity-124", title: "Sort a long list into now, later and drop", category: "productivity", text: "Help me sort my long task list into three groups — do now, do later, and drop: [paste your list]. Put each task in one group, tell me why it belongs there, and give me the final do-now list in the order I should follow." },
  { id: "productivity-125", title: "A priority list for a doctor's visit with an elder", category: "productivity", text: "Make a priority list for a doctor's visit with an elderly parent in [your city]. List the questions to ask, the medicines to carry, and the reports to show, in the order that matters most, and add one note for the journey home." },
  { id: "productivity-126", title: "A week plan for a vegetable seller", category: "productivity", text: "Make a weekly plan for a vegetable seller in [your town]. Mark the market days, the days to buy fresh stock, and the quiet days for accounts. Keep it as a clear table for the week, with one main job per day." },
  { id: "productivity-127", title: "Plan a work week around two school holidays", category: "productivity", text: "Help me plan a work week around two school holidays on [dates] in [your city]. Fit my office work, the children's care, and cooking around the holidays, and tell me which work I can do from home on those days." },
  { id: "productivity-128", title: "A week plan for a tuition teacher", category: "productivity", text: "Make a weekly plan for a tuition teacher in [your city] with five batches. Give each batch a day and time, add time for preparing lessons, and leave one free evening. Show it as a simple timetable for the whole week." },
  { id: "productivity-129", title: "A week plan that covers meals and work", category: "productivity", text: "Help me plan a week that covers meals and work together for my family in [your city]. Give a simple meal plan for each day, fit it around my work hours, and add a shopping list for the week so nothing is missed." },
  { id: "productivity-130", title: "A week plan for a tailor before Diwali", category: "productivity", text: "Make a weekly plan for a tailor in [your town] before the Diwali rush. Sort the pending orders by delivery date, block stitching time each day, and leave one day for new customers. Keep it as a clear table for the week." },
  { id: "productivity-131", title: "Plan a week with a different main job each day", category: "productivity", text: "Help me plan a week with a different main job each day: [list the jobs]. Give each day one main job, add two small jobs beside it, and leave Sunday free. Show the plan as a simple day-by-day table I can pin up." },
  { id: "productivity-132", title: "Weekly planning for a farmer in sowing season", category: "productivity", text: "Make a weekly plan for a farmer during sowing season in [your village]. Mark the days for ploughing, sowing, watering, and buying seeds, and leave one day for rest. Keep it simple, with one main job per day." },
  { id: "productivity-133", title: "Plan a week for a family shifting house", category: "productivity", text: "Help me plan a week for a family shifting to a new house in [your city]. Give each day a main job — packing, cleaning, transport, and settling in — and tell me what to finish first so the move stays calm and on time." },
  { id: "productivity-134", title: "A week plan for a student with coaching", category: "productivity", text: "Make a weekly plan for a student in [class] with coaching classes on [days]. Fit school, coaching, homework, and play into each day, and leave one evening free. Show it as a simple timetable for the whole week." },
  { id: "productivity-135", title: "Plan a week for a small catering order", category: "productivity", text: "Help me plan a week for a small catering order of [number] people in [your city]. Give each day a job — buying, cooking, packing, and delivery — and tell me what to prepare in advance so the order is ready on time." },
  { id: "productivity-136", title: "A week plan for a delivery agent", category: "productivity", text: "Make a weekly plan for a delivery agent in [your city] with routes on [days]. Mark the busy days, the light days, and the day for vehicle service. Keep it as a clear table, with one main job per day." },
  { id: "productivity-137", title: "Plan a week around a relative's visit", category: "productivity", text: "Help me plan a week around a relative's visit to my home in [your city]. Fit cleaning, cooking, outings, and my work around the visit, and tell me which days to keep free so the visit stays relaxed and happy." },
  { id: "productivity-138", title: "A week plan for a shop during a sale", category: "productivity", text: "Make a weekly plan for my shop in [your town] during a sale week. Mark the days for extra stock, staff duties, and counting cash, and tell me how to handle the busiest day. Keep it as a simple day-by-day table." },
  { id: "productivity-139", title: "Plan a week of study before a unit test", category: "productivity", text: "Help me plan a week of study before a unit test in [subject] for a student in [class]. Give each day one topic, add a short revision, and leave the last day for a sample paper. Keep the plan simple, with breaks every day." },
  { id: "productivity-140", title: "Weekly planning for a homemaker with a job", category: "productivity", text: "Make a weekly plan for a homemaker in [your city] with a part-time job on [days]. Fit cooking, cleaning, the job, and children's homework into each day, and leave Sunday mostly free. Show it as a clear weekly table." },
  { id: "productivity-141", title: "Plan a week for a new employee's first week", category: "productivity", text: "Help me plan the first week for a new employee as a [job role] in [your city]. Give each day a main task — learning, meeting the team, and starting small jobs — and tell me what to note down each evening." },
  { id: "productivity-142", title: "A week plan for a street food stall", category: "productivity", text: "Make a weekly plan for a street food stall in [your city]. Mark the days to buy fresh ingredients, the busy evening hours, and the day to clean the stall and count cash. Keep it as a simple table for the week." },
  { id: "productivity-143", title: "Plan a week with one big task and small tasks", category: "productivity", text: "Help me plan a week with one big task — [describe it] — and small tasks around it. Give the big task two days, spread the small tasks across the other days, and leave one day free for anything that slips." },
  { id: "productivity-144", title: "A week plan for a family with a newborn", category: "productivity", text: "Make a weekly plan for a family with a newborn baby at home in [your city]. Give each day a light main job, add time for feeding and rest, and keep one day completely free. Keep the plan gentle, with no fixed hours." },
  { id: "productivity-145", title: "Plan a week for repairing and painting a room", category: "productivity", text: "Help me plan a week for repairing and painting a room at home in [your city]. Give each day a job — cleaning, filling cracks, painting, and drying — and tell me what to buy first so the work does not stop midway." },
  { id: "productivity-146", title: "A week plan for a gym trainer", category: "productivity", text: "Make a weekly plan for a gym trainer in [your city] with [number] clients. Give each client a day and time, add time for planning workouts, and leave one morning free. Show it as a simple timetable for the week." },
  { id: "productivity-147", title: "Plan a week for a school's annual day function", category: "productivity", text: "Help me plan a week for a school's annual day function in [your city]. Give each day a job — practice, costumes, stage, and invitations — and tell me what to check the day before the function so nothing is missed." },
  { id: "productivity-148", title: "A week plan for a small office team", category: "productivity", text: "Make a weekly plan for a small office in [your city] with three staff members. Give each person a main job per day, mark the shared jobs, and add one hour for the week's accounts. Keep it as a clear table for the team." },
  { id: "productivity-149", title: "Plan a week for a farmer's harvest and selling", category: "productivity", text: "Help me plan a week for a farmer's harvest and selling in [your village]. Give each day a job — cutting, drying, packing, and taking the crop to the mandi — and tell me what to check before the selling day." },
  { id: "productivity-150", title: "A week plan that leaves Friday free", category: "productivity", text: "Make a weekly plan for my work in [your city] that leaves Friday evening free. Fit all the week's jobs into Monday to Friday afternoon, tell me what to finish by Thursday, and keep Friday evening clear for family time." },
  { id: "productivity-151", title: "A deadline list for a school project", category: "productivity", text: "Make a deadline list for a school project on [topic] due on [date]. Break the project into small steps, give each step its own date, and tell me what to finish first so the last day is only for checking and packing." },
  { id: "productivity-152", title: "Track five work deadlines on one page", category: "productivity", text: "Help me track five work deadlines on one page: [list the jobs with dates]. Show each job, its due date, and how much is done, in a simple table. Tell me which one to work on first and how to update the page each morning." },
  { id: "productivity-153", title: "A due-date list for monthly bills and fees", category: "productivity", text: "Make a due-date list for my monthly bills and fees in [your city]: [list them]. Put them in date order, add the amount for each one, and tell me which ones to pay first so I never miss a date or pay a fine." },
  { id: "productivity-154", title: "Plan backwards from a wedding date", category: "productivity", text: "Help me plan backwards from a wedding date on [date] in [your city]. List the big jobs — venue, food, cards, and outfits — and give each one a finish-by date, working back from the wedding day so nothing is left to the last minute." },
  { id: "productivity-155", title: "A deadline plan for a shop's GST filing", category: "productivity", text: "Make a deadline plan for my shop's GST filing due on [date] in [your town]. Break it into steps — collecting bills, checking sales, and filing — give each step a date, and tell me what to keep ready so the filing is done on time." },
  { id: "productivity-156", title: "A countdown list for a train ticket booking date", category: "productivity", text: "Make a countdown list for booking train tickets on [date] for a journey from [city] to [city]. List what to check before the booking opens — dates, berth choice, and payment — and tell me the exact time to be ready." },
  { id: "productivity-157", title: "A deadline list for a tailor's festival orders", category: "productivity", text: "Make a deadline list for a tailor in [your town] with festival orders due before [date]. Sort the orders by due date, tell me how many to finish each day, and add one buffer day for last-minute fixes." },
  { id: "productivity-158", title: "Track school fee and exam dates for two children", category: "productivity", text: "Help me track school fee and exam dates for two children in [your city]. List each date, the amount or subject, and what to prepare, in date order. Tell me how to check this list every Sunday so nothing is missed." },
  { id: "productivity-159", title: "A deadline plan for a home loan application", category: "productivity", text: "Make a deadline plan for a home loan application in [your city] due by [date]. List the documents needed, give each one a date to collect, and tell me what to check before submitting the file to the bank." },
  { id: "productivity-160", title: "A due-date list for a small business's payments", category: "productivity", text: "Make a due-date list for my small business's payments in [your town]: [list the payments]. Put them in date order with the amount for each, and tell me which ones to pay early and which ones to pay on the last day." },
  { id: "productivity-161", title: "Plan backwards from a school admission last date", category: "productivity", text: "Help me plan backwards from a school admission last date on [date] in [your city]. List the steps — form, documents, and fee — give each one a finish-by date, and tell me what to keep ready the day before the last date." },
  { id: "productivity-162", title: "A deadline list for a student's three assignments", category: "productivity", text: "Make a deadline list for a student in [class] with three assignments due on [dates]. Break each assignment into small steps, give each step a date, and tell me which assignment to start first and why." },
  { id: "productivity-163", title: "Count down to a shop's opening day", category: "productivity", text: "Make a countdown plan for my shop's opening day on [date] in [your town]. List the jobs for the last seven days — stock, cleaning, signboard, and staff — and give each day one main job so the opening is ready on time." },
  { id: "productivity-164", title: "Track medicine refill dates for an elderly parent", category: "productivity", text: "Help me track medicine refill dates for my elderly parent in [your city]. List each medicine, the date it runs out, and the shop to buy it from. Tell me how to set a reminder three days before each date so we never run out." },
  { id: "productivity-165", title: "A deadline plan for a passport renewal", category: "productivity", text: "Make a deadline plan for a passport renewal before a trip on [date]. List the steps — form, documents, photo, and appointment — give each one a date, and tell me what to carry to the appointment so nothing is delayed." },
  { id: "productivity-166", title: "A due-date list for a farmer's loan and subsidy forms", category: "productivity", text: "Make a due-date list for a farmer's loan and subsidy forms in [your village]. List each form, its last date, and the documents needed, in date order. Tell me which one to finish first and what to keep ready for the bank visit." },
  { id: "productivity-167", title: "Plan backwards from a job interview date", category: "productivity", text: "Help me plan backwards from a job interview on [date] in [your city] for a [job role]. List the steps — documents, clothes, route check, and practice — give each one a date, and tell me what to do the night before the interview." },
  { id: "productivity-168", title: "A deadline list for a catering order with many dishes", category: "productivity", text: "Make a deadline list for a catering order of [number] people on [date] in [your city]. Break the cooking into steps, give each dish a finish time, and tell me what to prepare the day before so the order is ready on time." },
  { id: "productivity-169", title: "Track renewal dates for licences and insurance", category: "productivity", text: "Help me track renewal dates for licences and insurance: [list them with dates]. Put them in date order, add the amount for each, and tell me how to set a reminder two weeks before each date so nothing expires." },
  { id: "productivity-170", title: "A deadline plan for a college application", category: "productivity", text: "Make a deadline plan for a college application due on [date] in [your city]. List the steps — form, marksheets, photos, and fee — give each one a date, and tell me what to check before submitting the form." },
  { id: "productivity-171", title: "Set phone reminders for a day of errands", category: "productivity", text: "Help me set phone reminders for a day of errands in [your city]: [list the errands]. Tell me what time to set each reminder, what words to write in it, and how to check them off as I finish each errand." },
  { id: "productivity-172", title: "A reminder system for a shopkeeper's daily jobs", category: "productivity", text: "Make a reminder system for a shopkeeper in [your town] for daily jobs — opening, supplier calls, and closing cash. Tell me what time to set each reminder, what it should say, and how to check it each evening." },
  { id: "productivity-173", title: "Set alarms for a student's study and sleep times", category: "productivity", text: "Help me set alarms for a student in [class] for study and sleep times. School ends at [time] and bedtime is [time]. Tell me which alarms to set, what each one is for, and how to keep the same timings every weekday." },
  { id: "productivity-174", title: "A reminder list for a homemaker's weekly chores", category: "productivity", text: "Make a reminder list for a homemaker's weekly chores in [your city]: [list the chores]. Tell me which day to set a reminder for each chore, what the reminder should say, and how to tick it off when it is done." },
  { id: "productivity-175", title: "Set reminders for water, meals and rest at work", category: "productivity", text: "Help me set reminders for water, meals, and rest at work. I work from [time] to [time] in [your city]. Tell me what times to set the reminders, what each one should say, and how to follow them without disturbing my work." },
  { id: "productivity-176", title: "A reminder system for a farmer's watering days", category: "productivity", text: "Make a reminder system for a farmer's watering days in [your village]. Tell me how to note which field was watered on which day, when to set the next reminder, and how to check the list each morning before going to the field." },
  { id: "productivity-177", title: "Set a reminder for a monthly bill", category: "productivity", text: "Help me set a reminder for a bill that is due every month — [bill name] of ₹[amount], due on the [date] in [your city]. Tell me when to set the reminder, what it should say, and how to mark it paid so I never miss it." },
  { id: "productivity-178", title: "A reminder list for a parent's school meetings", category: "productivity", text: "Make a reminder list for a parent's school meetings in [your city]: [list the meetings with dates]. Tell me when to set each reminder, what to carry to each meeting, and how to note down what the teacher says." },
  { id: "productivity-179", title: "Set alarms for a delivery driver's pickup times", category: "productivity", text: "Help me set alarms for a delivery driver's pickup times in [your city]. The pickups are at [times]. Tell me which alarm to set for each pickup, what it should say, and how to plan the route so no pickup is missed." },
  { id: "productivity-180", title: "A reminder system for a tailor's order delivery dates", category: "productivity", text: "Make a reminder system for a tailor's order delivery dates in [your town]. Tell me how to list each order with its date, when to set a reminder two days before, and how to check the list each morning before starting work." },
  { id: "productivity-181", title: "Set reminders for a week's medicine doses", category: "productivity", text: "Help me set reminders for a week's medicine doses for [person] in [your city]. The doses are at [times]. Tell me what each reminder should say, how to mark a dose taken, and what to do if a dose is missed." },
  { id: "productivity-182", title: "A reminder list for a small business's weekly payments", category: "productivity", text: "Make a reminder list for my small business's weekly payments in [your town]: [list the payments]. Tell me which day to set each reminder, what it should say, and how to mark each payment done so nothing is paid twice." },
  { id: "productivity-183", title: "Set a wake-up alarm that fits a 5 am start", category: "productivity", text: "Help me set a wake-up alarm for a 5 am start in [your village]. Tell me what time to sleep, how many alarms to set, and what to keep ready the night before so I can start work on time without rushing." },
  { id: "productivity-184", title: "A reminder system for a teacher's class timings", category: "productivity", text: "Make a reminder system for a teacher's class timings in [your city]. The classes are at [times]. Tell me which reminder to set before each class, what to carry, and how to use the gap between classes for correcting notebooks." },
  { id: "productivity-185", title: "Set reminders for a family's festival preparations", category: "productivity", text: "Help me set reminders for a family's festival preparations for [festival] in [your city]. List the jobs — cleaning, shopping, and cooking — tell me when to set each reminder, and how to check them off as the festival nears." },
  { id: "productivity-186", title: "Plan a work day around two school drops", category: "productivity", text: "Help me plan a work day around two school drops in [your city]. School starts at [time] and [time], and my work starts at [time]. Tell me what time to leave home, what to keep ready the night before, and how to fit cooking around the drops." },
  { id: "productivity-187", title: "Fit school pickup and cooking into a day", category: "productivity", text: "Make a daily plan that fits school pickup at [time] and cooking dinner in [your city]. Tell me what to cook, what to prepare before the pickup, and how to finish dinner by [time] without rushing." },
  { id: "productivity-188", title: "Plan a shop day around children's school hours", category: "productivity", text: "Help me plan a shop day around my children's school hours in [your town]. School runs from [time] to [time]. Tell me when to open, when to close for the pickup, and how to handle customers during the school run." },
  { id: "productivity-189", title: "A week plan that shares school runs", category: "productivity", text: "Make a weekly plan that shares school runs between two parents in [your city]. Give each parent their days, add the pickup times, and tell me how to swap days when one parent is busy or travelling." },
  { id: "productivity-190", title: "Plan a work week with a sick child at home", category: "productivity", text: "Help me plan a work week with a sick child at home in [your city]. Tell me which work I can do from home, how to share care with my spouse, and what to keep ready for the doctor if the child does not get better." },
  { id: "productivity-191", title: "A day plan for a parent with a baby", category: "productivity", text: "Make a daily plan for a parent with a baby and a schoolchild in [your city]. Fit feeding, school drop, cooking, and rest into the day, and tell me what to prepare the night before so the morning is calm." },
  { id: "productivity-192", title: "A day built around a hospital visit", category: "productivity", text: "Help me plan a day around an elderly parent's hospital visit at [time] in [your city]. Fit my work, travel, and cooking around the visit, and tell me what papers and medicines to carry for the appointment." },
  { id: "productivity-193", title: "A plan for a day when school closes early", category: "productivity", text: "Make a plan for a day when school closes early at [time] in [your city]. Tell me how to adjust my work, what to keep ready for the early pickup, and how to use the extra hours at home for homework and play." },
  { id: "productivity-194", title: "Plan a week with school exams and office work", category: "productivity", text: "Help me plan a week with school exams for my child and office work for me in [your city]. Fit revision help, office hours, and cooking into each day, and tell me which evenings to keep free for the child's revision." },
  { id: "productivity-195", title: "A plan that fits a school run and market trip", category: "productivity", text: "Make a daily plan that fits a school run at [time] and a market trip in [your town]. Tell me the best order — school first or market first — what to buy, and how to finish both jobs before [time] without rushing." },
  { id: "productivity-196", title: "A work schedule for a shopkeeper in a busy market", category: "productivity", text: "Make a work schedule for a shopkeeper in a busy market in [your town]. Cover opening at [time], the busy hours, lunch, and closing at [time]. Add time for stock checks and cash counting, and keep the schedule simple to follow." },
  { id: "productivity-197", title: "A work schedule for office staff, 9 to 6", category: "productivity", text: "Make a work schedule for office staff with a 9 to 6 day in [your city]. Include the morning start, lunch, meetings, and the last hour for finishing pending work. Keep it simple, with timings for each part of the day." },
  { id: "productivity-198", title: "A daily schedule for a college student with classes", category: "productivity", text: "Make a daily schedule for a college student in [your city] with classes from [time] to [time]. Include travel, lunch, study, and one hour of rest. Keep the schedule simple, with clear timings from morning to night." },
  { id: "productivity-199", title: "A daily schedule for a homemaker with three children", category: "productivity", text: "Make a daily schedule for a homemaker with three children in [your city]. Cover school drops, cooking, cleaning, homework help, and one hour of rest. Keep it in time order, with simple timings the whole family can follow." },
  { id: "productivity-200", title: "A daily schedule for a farmer in the summer season", category: "productivity", text: "Make a daily schedule for a farmer in the summer season in [your village]. Start early at [time], rest at noon, and work again in the evening. Include watering, feeding animals, and one hour for the market or bank work." },
  { id: "productivity-201", title: "A work schedule for a nurse on a day shift", category: "productivity", text: "Make a work schedule for a nurse on a day shift from [time] to [time] in [your city]. Include the handover, patient rounds, meals, and the end-of-shift notes. Keep it in clear time order, with a short rest break in the middle." },
  { id: "productivity-202", title: "A daily schedule for a retired teacher at home", category: "productivity", text: "Make a daily schedule for a retired teacher at home in [your city]. Include a morning walk, reading, a visit to friends or the market, rest, and an evening with family. Keep it gentle, with plenty of free time." },
  { id: "productivity-203", title: "A work schedule for a bank employee", category: "productivity", text: "Make a work schedule for a bank employee in [your city] with a long day from [time] to [time]. Include the morning opening, customer hours, lunch, and the closing work. Keep it simple, with a short break in the afternoon." },
  { id: "productivity-204", title: "A daily schedule for a school bus driver", category: "productivity", text: "Make a daily schedule for a school bus driver in [your city]. Include the morning route, the vehicle check, the afternoon route, and fuel. Keep it in time order, with the school timings clearly marked." },
  { id: "productivity-205", title: "A work schedule for a cook in a small hotel", category: "productivity", text: "Make a work schedule for a cook in a small hotel in [your town]. Cover the morning prep, lunch service, a rest break, and dinner service. Add time for checking stock and cleaning the kitchen at the end of the day." },
  { id: "productivity-206", title: "A daily schedule for a student preparing for NEET", category: "productivity", text: "Make a daily schedule for a student preparing for NEET in [your city]. Include classes, self-study, sample papers, and rest, from [time] to [time]. Keep the schedule steady, with the same timings every day and one free evening." },
  { id: "productivity-207", title: "A work schedule for a security guard on night duty", category: "productivity", text: "Make a work schedule for a security guard on night duty from [time] to [time] in [your city]. Include the rounds, the log book, meals, and the morning handover. Keep it in clear time order, with rest breaks marked." },
  { id: "productivity-208", title: "A daily schedule for a tailor during wedding season", category: "productivity", text: "Make a daily schedule for a tailor during wedding season in [your town]. Cover cutting in the morning, stitching in the afternoon, and trying on in the evening. Add one hour for new orders and keep the day from [time] to [time]." },
  { id: "productivity-209", title: "A work schedule for a field sales person", category: "productivity", text: "Make a work schedule for a field sales person in [your city] who visits [number] shops a day. Include the morning route, lunch, the afternoon visits, and the evening report. Keep it simple, with the shops grouped by area." },
  { id: "productivity-210", title: "A daily schedule for a homemaker who also tutors", category: "productivity", text: "Make a daily schedule for a homemaker in [your city] who also tutors children in the evening. Fit cooking, cleaning, and the tuition batch into the day, and keep one hour free in the afternoon for rest." },
  { id: "productivity-211", title: "A day packed with back-to-back meetings", category: "productivity", text: "Help me plan a busy day with back-to-back meetings in [your city]. The meetings are at [times]. Tell me how to prepare for each one, what to do in the gaps, and how to keep notes so nothing is forgotten by evening." },
  { id: "productivity-212", title: "An end-of-day wrap-up list for office work", category: "productivity", text: "Make an end-of-day wrap-up list for office work in [your city]. Include saving files, noting pending jobs, clearing the desk, and writing tomorrow's first job. Keep it to six quick steps I can finish in ten minutes." },
  { id: "productivity-213", title: "Juggle a school event and office work", category: "productivity", text: "Help me plan a busy day with a school event at [time] and office work in [your city]. Tell me how to fit both in, what to keep ready for the event, and how to finish the office work without staying late." },
  { id: "productivity-214", title: "An end-of-day wrap-up list for a shopkeeper", category: "productivity", text: "Make an end-of-day wrap-up list for a shopkeeper in [your town]. Include counting cash, noting pending orders, locking up, and writing tomorrow's first job. Keep it to six steps I can finish in fifteen minutes before closing." },
  { id: "productivity-215", title: "A day with three deliveries and a meeting", category: "productivity", text: "Help me plan a busy day with three deliveries and a meeting at [time] in [your city]. Tell me the best order for the deliveries, what to prepare for the meeting, and how to fit lunch in between without rushing." },
  { id: "productivity-216", title: "An end-of-day wrap-up list for a student", category: "productivity", text: "Make an end-of-day wrap-up list for a student in [class]. Include packing the school bag, noting homework, keeping books ready, and writing tomorrow's first task. Keep it to five steps I can finish in ten minutes." },
  { id: "productivity-217", title: "Fit a doctor visit into a work day", category: "productivity", text: "Help me plan a busy day with a doctor visit at [time] and work in [your city]. Tell me how to fit the visit between work hours, what papers to carry, and how to catch up on the work I miss during the visit." },
  { id: "productivity-218", title: "An end-of-day wrap-up list for a homemaker", category: "productivity", text: "Make an end-of-day wrap-up list for a homemaker in [your city]. Include cleaning the kitchen, keeping tomorrow's clothes ready, noting pending jobs, and setting the morning alarm. Keep it to six steps I can finish in fifteen minutes." },
  { id: "productivity-219", title: "A day of train travel and office work", category: "productivity", text: "Help me plan a busy day with a train journey from [city] to [city] and office work. Tell me what work to do on the train, what to keep ready for the station, and how to finish the day's jobs without staying late." },
  { id: "productivity-220", title: "An end-of-day wrap-up list for a farmer", category: "productivity", text: "Make an end-of-day wrap-up list for a farmer in [your village]. Include feeding the animals, checking the water pump, noting tomorrow's field work, and keeping tools safe. Keep it to five steps I can finish before dark." },
  { id: "productivity-221", title: "A day with a function and a deadline", category: "productivity", text: "Help me plan a busy day with a family function in the evening and a work deadline at [time] in [your city]. Tell me how to finish the deadline first, what to keep ready for the function, and how to reach on time without rushing." },
  { id: "productivity-222", title: "An end-of-day wrap-up list for a tuition teacher", category: "productivity", text: "Make an end-of-day wrap-up list for a tuition teacher in [your city]. Include noting which students came, marking homework, planning tomorrow's lesson, and keeping the notes ready. Keep it to five steps I can finish in ten minutes." },
  { id: "productivity-223", title: "A day with two interviews and travel", category: "productivity", text: "Help me plan a busy day with two interviews at [times] and travel in [your city]. Tell me the best route, what documents to carry for each interview, and how to use the travel time to prepare for the second one." },
  { id: "productivity-224", title: "An end-of-day wrap-up list for a delivery driver", category: "productivity", text: "Make an end-of-day wrap-up list for a delivery driver in [your city]. Include counting cash, noting failed deliveries, checking fuel, and writing tomorrow's first route. Keep it to five steps I can finish in ten minutes." },
  { id: "productivity-225", title: "A day when everything is due at once", category: "productivity", text: "Help me plan a busy day when everything is due at once: [list the jobs]. Tell me which job to do first, which ones to ask for help with, and which ones to move to tomorrow so the day stays under control." },
  { id: "productivity-226", title: "Try the Pomodoro method for office work", category: "productivity", text: "Work in focused blocks of 25 minutes with a 5 minute break after each one. Choose [your most important office task], set a timer, and work without checking your phone or email. After four blocks, take a longer 20 minute break and notice how much you finish." },
  { id: "productivity-227", title: "Use a 25 minute timer for study", category: "productivity", text: "Set a timer for 25 minutes and study [one chapter or topic] without stopping. Keep your phone in another room and your books open on the desk. When the timer rings, take a 5 minute break, stretch, drink water, and then start the next round." },
  { id: "productivity-228", title: "Plan four Pomodoro rounds for one morning", category: "productivity", text: "Plan four 25 minute work rounds for tomorrow morning before you start. Write down [the four small tasks] you will finish, one per round, with a 5 minute break between rounds. Keep the list on your desk and tick each round off as you complete it." },
  { id: "productivity-229", title: "Try a 50 minute focus session for writing", category: "productivity", text: "Set a timer for 50 minutes and write [your report, letter or article] without stopping to edit or check messages. Aim for a rough draft first, not perfect sentences. When the timer ends, take a 10 minute break, then read what you wrote and tidy it up." },
  { id: "productivity-230", title: "Use a 90 minute deep work timer", category: "productivity", text: "Block 90 minutes for [your hardest task] and treat it like an appointment you cannot miss. Close extra tabs, silence your phone, and keep water and your notes nearby. Work slowly and steadily, and take a proper 20 minute break when the timer ends." },
  { id: "productivity-231", title: "Set a timer for exam revision rounds", category: "productivity", text: "Revise [one subject] in 25 minute rounds with 5 minute breaks in between. In each round, read one topic, close the book, and write down what you remember. After three rounds, take a 15 minute break and test yourself again on the same topics." },
  { id: "productivity-232", title: "Pomodoro plan for a busy shopkeeper", category: "productivity", text: "Use 25 minute Pomodoro rounds for shop paperwork between customers. Choose [one pending job, like bills or stock counting], set a timer, and work on it only until the timer rings. If a customer comes in, pause the timer and restart it when you are free again." },
  { id: "productivity-233", title: "Use short timers to finish pending bills", category: "productivity", text: "Set a timer for 20 minutes and finish [your pending bills or payment entries] without doing anything else. Keep the calculator, bills and notebook in one place before you start. When the timer rings, stop, take a short break, and check how many bills you cleared." },
  { id: "productivity-234", title: "Timer method for coding one feature", category: "productivity", text: "Pick [one small feature or bug fix] and set a timer for 45 minutes. Code without opening social media or checking messages, and write down any new idea that pops up instead of following it. When the timer ends, test your work and note what is left." },
  { id: "productivity-235", title: "A Pomodoro routine for college assignments", category: "productivity", text: "Break [your college assignment] into small parts and give each part one 25 minute Pomodoro round. Write the parts on paper first, then work through them one by one with short breaks. Finish the round even if the part is not perfect, and fix it in the last round." },
  { id: "productivity-236", title: "Use a kitchen timer for study sessions", category: "productivity", text: "Use a simple kitchen timer instead of your phone to time [your study session]. A kitchen timer has no messages or videos to pull you away. Set it for 30 minutes, study one topic, and when it rings, take a break away from your desk." },
  { id: "productivity-237", title: "Plan Pomodoro breaks that refresh you", category: "productivity", text: "Plan your 5 minute Pomodoro breaks before you start working on [your task]. Choose refreshing breaks like stretching, drinking water, looking out of the window or walking to the next room. Avoid your phone during breaks, so your mind truly rests before the next round." },
  { id: "productivity-238", title: "Try the 52-17 work and rest method", category: "productivity", text: "Try working for 52 minutes and resting for 17 minutes while doing [your office or study work]. The longer work block suits bigger tasks, and the longer rest helps your mind recover fully. Try it for one morning and compare it with your usual 25 minute rounds." },
  { id: "productivity-239", title: "Use timers to study for a railway exam", category: "productivity", text: "Prepare for [your railway or government exam] with 40 minute timed rounds. In each round, solve questions from one section only, like maths or general knowledge. Mark the questions you could not solve, and use the last round of the day to revise only those marked questions." },
  { id: "productivity-240", title: "Pomodoro for preparing a presentation", category: "productivity", text: "Prepare [your presentation] in four Pomodoro rounds. Round one: plan the points on paper. Round two: make the slides. Round three: add simple examples. Round four: practise speaking it aloud once. Take a short break after each round and keep your phone away." },
  { id: "productivity-241", title: "A timer routine for a home based tailor", category: "productivity", text: "Use 30 minute timer rounds for [your stitching or cutting work] at home. In each round, finish one clear piece of work, like one blouse or one set of alterations. Keep the phone on silent, and use the 5 minute breaks to stretch your back and rest your eyes." },
  { id: "productivity-242", title: "Use a 15 minute timer to start work", category: "productivity", text: "When [a big task] feels too heavy to start, set a timer for just 15 minutes and promise yourself you can stop when it rings. Work on the easiest part first. Most people keep going after 15 minutes, but even if you stop, you have made a real start." },
  { id: "productivity-243", title: "Pomodoro plan for a long report", category: "productivity", text: "Split [your long report] into five parts and give each part two Pomodoro rounds. Write the heading of each part on a sheet first, then fill one part at a time. Do not jump to the next part until the current one is drafted, and take a 15 minute break after every four rounds." },
  { id: "productivity-244", title: "Finish one task before starting another", category: "productivity", text: "Choose [the one task] that matters most today and finish it fully before touching anything else. Put the other tasks on a paper list and keep it out of sight. When you finish, tick it off, take a short break, and only then pick up the next task." },
  { id: "productivity-245", title: "Compare single-tasking and multitasking honestly", category: "productivity", text: "Try one hour of single-tasking on [your work] and one hour of switching between tasks, then compare the results honestly. Count how much you finished in each hour and how tired you felt. Write down which hour felt calmer and which one produced better quality work." },
  { id: "productivity-246", title: "Stop switching between tasks at work", category: "productivity", text: "Pick [your current office task] and stay with it for 40 minutes without switching to email, chats or another file. If a new task comes to mind, write it on a slip of paper and return to it later. Notice how much faster the work moves when you stop switching." },
  { id: "productivity-247", title: "Work on one file at a time", category: "productivity", text: "Open only [one file or document] on your computer and close everything else. Finish the work in that file before opening the next one. If you need a fact from another file, note it down and check it later, instead of opening five files at once." },
  { id: "productivity-248", title: "Single-tasking plan for a busy morning", category: "productivity", text: "Plan tomorrow morning as a chain of single tasks, not a jumble. List [three morning jobs] in order, with a start time for each, and do them one after another without overlap. Leave a 10 minute gap between jobs for delays, and tick each one off as you finish." },
  { id: "productivity-249", title: "Why multitasking slows your office work", category: "productivity", text: "Explain in simple words why doing [two office jobs] at the same time slows you down and causes more mistakes. Use a daily example, like typing an email while talking on the phone, and suggest one change, like finishing the call first, that would help." },
  { id: "productivity-250", title: "Do one chore fully before the next", category: "productivity", text: "Choose [one household chore, like washing the dishes] and finish it completely before starting the next one. Do not leave it half done to start sweeping or folding clothes. Finishing one chore fully gives you a clear win and keeps the house tidy step by step." },
  { id: "productivity-251", title: "Single-tasking for a student with many subjects", category: "productivity", text: "Study [one subject] at a time instead of keeping three books open together. Give each subject its own 40 minute slot, and close the book before opening the next one. Write down doubts on a separate page and clear them in the last slot of the day." },
  { id: "productivity-252", title: "Finish your email reply before opening WhatsApp", category: "productivity", text: "Reply to [your important email] fully before you open WhatsApp or any chat app. Read the email twice, write your reply, check the spelling, and send it. Only then open your chats. This stops a quick message from turning into 20 minutes of scrolling." },
  { id: "productivity-253", title: "One task at a time for a shop counter", category: "productivity", text: "Serve [one customer] fully before moving to the next person at your shop counter. Finish their billing, packing and change, and only then call the next customer. It feels slower, but customers wait less overall and you make fewer billing mistakes." },
  { id: "productivity-254", title: "Stop juggling calls and typing together", category: "productivity", text: "When you are on a phone call about [your work], stop typing and listen fully. Note the key points on paper while you listen. After the call ends, type your notes into the computer. Splitting your attention makes both the call and the typing worse." },
  { id: "productivity-255", title: "Single-tasking while cooking and studying", category: "productivity", text: "If you cook and study in the same morning, keep them separate. Finish [your cooking task] first, clean the kitchen, and then sit down to study [one topic]. Mixing the two leaves the food half cooked and the lesson half learned, so finish one before the other." },
  { id: "productivity-256", title: "Focus on one customer at a time", category: "productivity", text: "Give [each customer] your full attention for the few minutes they are with you. Listen to what they need, answer clearly, and finish their work before turning to the next person. Customers notice when you are truly listening, and they come back again." },
  { id: "productivity-257", title: "A single-task day for a freelancer", category: "productivity", text: "Plan one day where you work on [a single client project] from start to finish, with no other client work in between. Tell your other clients you will reply the next day. At the end of the day, compare how much you finished with a normal day of switching between clients." },
  { id: "productivity-258", title: "Build a distraction-free work block daily", category: "productivity", text: "Choose one hour every day for [your most important work] and protect it like a meeting. Silence your phone, close chat apps, and tell your family not to disturb you. Use the same hour daily, so your mind learns that this hour is for deep, quiet work." },
  { id: "productivity-259", title: "Set up a quiet corner for work", category: "productivity", text: "Pick a quiet corner in [your home] and set it up as your work spot. Keep a chair, a small table, your notebook and a water bottle there, and nothing else. Sit in the same spot every day, so your mind switches into work mode the moment you sit down." },
  { id: "productivity-260", title: "Plan a 90 minute no-distraction block", category: "productivity", text: "Plan a 90 minute block tomorrow for [your biggest pending task]. Tell your family the start and end time, put your phone on silent in another room, and keep only the papers you need on the desk. Work slowly, take one short stretch break in the middle, and finish strong." },
  { id: "productivity-261", title: "Create a work block before lunch", category: "productivity", text: "Use the hour before lunch for [your hardest task], when your energy is still high. Start at the same time every day, work without breaks, and save easy jobs like replying to messages for after lunch. A strong morning block makes the whole day feel productive." },
  { id: "productivity-262", title: "A distraction-free block for exam study", category: "productivity", text: "Create a two hour distraction-free block for [your exam subject] every evening. Keep your phone outside the room, your books open, and a glass of water nearby. Study one chapter fully, then close the book and write down the five most important points from memory." },
  { id: "productivity-263", title: "Prepare your desk for a focused hour", category: "productivity", text: "Spend five minutes preparing your desk before a focused hour on [your task]. Clear the clutter, keep only the notebook, pen and papers you need, and place a glass of water nearby. A clean desk removes small excuses to get up and wander during the hour." },
  { id: "productivity-264", title: "Work block routine for a small office", category: "productivity", text: "Agree with your office team on a daily quiet hour for [focused work]. During that hour, nobody calls a meeting, nobody chats loudly, and everyone works on their own task. Put a small sign on the door, and after a week, check if the team finished more work." },
  { id: "productivity-265", title: "Block out noise during a work block", category: "productivity", text: "During your work block on [your task], block the noise around you with earphones, soft music, or by closing the door and windows. If the noise comes from the street, choose the quietest room in the house. A calm space helps your mind stay on one thing." },
  { id: "productivity-266", title: "A morning work block before the house wakes", category: "productivity", text: "Wake up 45 minutes before the rest of the house and use that quiet time for [your study or writing]. The house is calm, nobody needs anything, and your mind is fresh. Keep the work simple and finish one small part before everyone wakes up." },
  { id: "productivity-267", title: "Design a work block around your energy", category: "productivity", text: "Notice when you feel most alert during the day, and place your work block for [your hardest task] in that hour. If you are sharp in the morning, work then; if you focus better at night, work then. Match hard work to high energy, and easy work to low energy." },
  { id: "productivity-268", title: "Use a work block to finish a report", category: "productivity", text: "Give [your pending report] one full work block of two hours, with no other job allowed inside it. Break the report into three parts on paper first, then write one part per 40 minutes. When the block ends, read the draft once and mark the parts that need fixing." },
  { id: "productivity-269", title: "A distraction-free block for reading files", category: "productivity", text: "Set aside one hour to read [your office files or case papers] without interruption. Keep a notebook beside you, and write down questions and action points as you read. Do not reply to messages during this hour; note them down and answer them after the block ends." },
  { id: "productivity-270", title: "Plan work blocks around school timings", category: "productivity", text: "Plan your work blocks around [your children's school hours], when the house is quiet. Use the morning block for hard work and the afternoon block for easy jobs. Keep a simple timetable on the fridge, so the family knows when you are working and when you are free." },
  { id: "productivity-271", title: "Set a work block for accounts work", category: "productivity", text: "Set a weekly work block of two hours for [your accounts, bills or tax papers]. Gather all the papers, bills and the calculator before you start, and work through them in order. Doing accounts in one calm block causes fewer errors than doing them in scattered minutes." },
  { id: "productivity-272", title: "A quiet work block after dinner", category: "productivity", text: "Use one quiet hour after dinner for [your study or planning] when the house settles down. Keep the TV off, put your phone away, and work on one topic only. A calm evening block is a good time for reading, revision, or planning the next day." },
  { id: "productivity-273", title: "Guard your work block from visitors", category: "productivity", text: "When a visitor arrives during your work block on [your task], greet them politely and say you will be free at [a fixed time]. Offer them water and ask them to wait or return later. Guarding your work time politely is better than losing the whole block to a chat." },
  { id: "productivity-274", title: "Keep your phone in another room", category: "productivity", text: "Put your phone in another room while you work on [your task] for one hour. If you need it for an emergency, tell your family to knock on your door instead. You will be surprised how often you reach for the phone without thinking, and how much calmer work feels without it." },
  { id: "productivity-275", title: "Put the phone on silent during work", category: "productivity", text: "Put your phone on silent and face down while you work on [your task]. Turn off message previews, so a flashing screen does not pull your eyes away. Check your phone only during your planned break, and reply to messages in one batch instead of one by one." },
  { id: "productivity-276", title: "A phone-free hour for study every day", category: "productivity", text: "Keep one hour every day completely phone-free for [your study]. Give the phone to a family member or leave it in another room. Use that hour for one subject only, with your books and notes on the table. After a week, notice how much more you remember." },
  { id: "productivity-277", title: "Keep the phone away while writing", category: "productivity", text: "While writing [your letter, report or story], keep your phone in a drawer and out of sight. A phone on the desk pulls your hand towards it every few minutes, even on silent. Write your full draft first, and only then pick up the phone to check messages." },
  { id: "productivity-278", title: "Phone-free mornings before office work", category: "productivity", text: "Keep your phone away for the first hour of the morning while you plan [your workday]. Use that hour to decide your three main jobs, prepare your bag, and eat breakfast calmly. Starting the day without messages keeps your mind clear and your plans steady." },
  { id: "productivity-279", title: "Put your phone in a drawer at work", category: "productivity", text: "At your office desk, keep your phone inside a drawer while you work on [your task]. Out of sight means out of mind, and you will check it far less. Take it out only during your lunch break or when you truly need to make a call." },
  { id: "productivity-280", title: "A phone-free zone at your study table", category: "productivity", text: "Make your study table a phone-free zone for [your exam preparation]. Keep only books, notes, pens and a water bottle on the table. Put a small basket near the door for your phone, and drop it in every time you sit down to study." },
  { id: "productivity-281", title: "Keep the phone away during online classes", category: "productivity", text: "During [your online class], keep your phone in another room or switched off. A phone beside your laptop tempts you to check messages between slides. If you need to note something, use a paper notebook, and check your phone only after the class ends." },
  { id: "productivity-282", title: "Phone-free time while preparing for exams", category: "productivity", text: "During your exam preparation for [your subject], keep the phone with a parent or in another room for two hours every evening. Tell your friends you will reply after 9 pm. The quiet hours will help you revise more chapters and feel less tired." },
  { id: "productivity-283", title: "Ask family to hold your phone calls", category: "productivity", text: "Ask [a family member] to answer your phone calls for one hour while you finish [your important work]. Tell them to take a message and the caller's name, and to interrupt you only for a real emergency. One protected hour often finishes work that drags on all day." },
  { id: "productivity-284", title: "A phone-free lunch break for your mind", category: "productivity", text: "Take your lunch break without your phone for [one week] and see how you feel. Eat slowly, talk to a colleague or family member, or simply sit quietly. A phone-free break rests your eyes and mind, so you return to work feeling fresher." },
  { id: "productivity-285", title: "Keep the phone away while doing accounts", category: "productivity", text: "While doing [your accounts or bill entries], keep your phone in another room. One wrong number typed while glancing at a message can take an hour to find later. Work through the entries in order, and check your phone only after the full page is done." },
  { id: "productivity-286", title: "Switch off notifications for two hours", category: "productivity", text: "Switch off all notifications on your phone for two hours while you work on [your task]. Keep only phone calls on, in case of an emergency. You will find that most messages can wait, and your work moves much faster without constant pings." },
  { id: "productivity-287", title: "Phone-free evenings for family and study", category: "productivity", text: "Keep the evening phone-free from 7 to 8 pm for [your family time and study]. Put all phones in one basket by the door. Use the hour to eat together, help the children with homework, or read. The family will talk more, and study will feel calmer." },
  { id: "productivity-288", title: "A five minute focus exercise before work", category: "productivity", text: "Before starting [your work], sit still for five minutes and focus only on your breathing. Breathe in slowly, breathe out slowly, and bring your mind back gently each time it wanders. This short exercise clears the morning rush from your head and helps you start calmly." },
  { id: "productivity-289", title: "Concentration exercise for office staff", category: "productivity", text: "Try a simple concentration exercise with your office team before starting [your daily work]. Everyone closes their eyes for two minutes and counts their breaths from one to ten, starting again whenever the mind wanders. A calm team focuses better and makes fewer mistakes." },
  { id: "productivity-290", title: "Practise focusing on one sound daily", category: "productivity", text: "Practise focusing on one sound, like a ticking clock or birdsong, for five minutes every day before [your study]. Sit still, close your eyes, and follow only that sound. When your mind drifts to other thoughts, bring it back gently. Daily practice slowly builds your attention." },
  { id: "productivity-291", title: "A breathing exercise before study time", category: "productivity", text: "Before you open [your study books], do a simple breathing exercise. Breathe in for four counts, hold for four counts, and breathe out for four counts. Repeat it five times. Your mind will feel steadier, and the first page will be easier to read." },
  { id: "productivity-292", title: "Focus exercise for students before exams", category: "productivity", text: "Before your exam revision of [your subject], try a focus exercise. Stare at one word on the page for one minute without looking away, then close your eyes and picture it clearly. Repeat it three times. This trains your mind to hold one thing at a time." },
  { id: "productivity-293", title: "Train your attention with a counting game", category: "productivity", text: "Train your attention with a counting game before [your work]. Count backwards from 100 in steps of three, slowly and without rushing. If you lose count, start again from 100. Ten minutes of this game every day sharpens your ability to stay on one task." },
  { id: "productivity-294", title: "A short focus warm-up for coders", category: "productivity", text: "Before coding [your project], warm up your focus for five minutes. Read the last lines you wrote yesterday, write down the one thing you will finish today, and close every tab you do not need. A clear start stops you from drifting into random browsing." },
  { id: "productivity-295", title: "Focus exercise for a noisy office", category: "productivity", text: "When your office is noisy, practise focusing on [your task] by narrowing your attention to one small thing, like the words on your screen. Read each line slowly and say the key words silently to yourself. This anchors your mind and keeps the noise in the background." },
  { id: "productivity-296", title: "A ten minute attention exercise daily", category: "productivity", text: "Spend ten minutes every day on an attention exercise before [your work or study]. Read one page slowly, then close the book and write down three things you remember. Do it at the same time daily, and after two weeks, notice how much longer you can focus." },
  { id: "productivity-297", title: "Practise reading one page without stopping", category: "productivity", text: "Practise reading [one page of your book] from start to finish without stopping, checking your phone, or looking up. If your mind wanders, return to the start of the paragraph and read it again. Start with one page daily, and add one more page each week." },
  { id: "productivity-298", title: "A focus exercise for night shift workers", category: "productivity", text: "Before your night shift, do a short focus exercise to wake up your mind for [your duty]. Splash cold water on your face, stretch for two minutes, and write down your three main jobs for the night. A clear list keeps you alert through the quiet hours." },
  { id: "productivity-299", title: "Train focus with a simple puzzle daily", category: "productivity", text: "Solve one simple puzzle, like a crossword or sudoku, every morning before [your work]. Give it ten minutes and finish it without checking your phone. Puzzles train your brain to stick with one problem until it is solved, which helps your work focus too." },
  { id: "productivity-300", title: "A focus exercise before a long meeting", category: "productivity", text: "Before [your long meeting], sit quietly for three minutes and decide the two things you must learn from it. Write them at the top of your notebook. During the meeting, listen for those two points, and your mind will stay engaged instead of drifting away." },
  { id: "productivity-301", title: "Focus in a noisy home during work", category: "productivity", text: "When your home is noisy, focus on [your work] by choosing the quietest corner, closing the door, and using earphones with soft music. Work in short 25 minute rounds, and take your breaks in the noisy part of the house. Short, calm rounds beat long, distracted hours." },
  { id: "productivity-302", title: "Study in a busy joint family home", category: "productivity", text: "Study [your subject] in a busy joint family home by fixing one quiet hour when everyone knows not to disturb you. Sit facing a wall, keep your books ready, and use earphones if needed. Tell the family your study time in advance, so they can plan around it." },
  { id: "productivity-303", title: "Work from a noisy flat with earplugs", category: "productivity", text: "If your flat is noisy, try soft earplugs while working on [your task]. They cut the street and neighbour sounds without blocking everything completely. Work in 40 minute rounds, remove the earplugs during breaks, and keep a glass of water nearby." },
  { id: "productivity-304", title: "Focus while the TV plays in the next room", category: "productivity", text: "When the TV plays in the next room, focus on [your study] by closing your door, sitting with your back to the sound, and reading aloud softly to yourself. Reading aloud keeps your ears busy with your own words, so the TV dialogue fades into the background." },
  { id: "productivity-305", title: "Study during a wedding at home", category: "productivity", text: "During a wedding at home, study [your subject] in the early morning before the guests wake up. Keep your books in one room, tell one family member your study hour, and revise only short notes. Even one quiet hour a day keeps your preparation on track." },
  { id: "productivity-306", title: "Focus while neighbours play loud music", category: "productivity", text: "When neighbours play loud music, focus on [your work] by moving to the farthest room, closing the windows, and using earphones with soft instrumental music. If the music continues for hours, plan your hardest work for the quieter morning hours instead." },
  { id: "productivity-307", title: "Work during festival noise at home", category: "productivity", text: "During festival days, do [your work] in the early morning before the celebrations start, or late at night after they end. Keep your work small and clear, like finishing one page or one file. Short, planned work fits around festivals better than long, hopeful sessions." },
  { id: "productivity-308", title: "Study with siblings playing nearby", category: "productivity", text: "When your siblings play nearby, study [your subject] by giving them a small activity first, like drawing or a puzzle, and then sitting in a corner with your books. Use earphones if it helps, and study in 25 minute rounds with short breaks to check on them." },
  { id: "productivity-309", title: "Focus while construction work goes on", category: "productivity", text: "While construction work goes on nearby, focus on [your task] by working in the room farthest from the noise, closing windows and doors, and using earphones. Plan your hardest work for the workers' lunch break, when the noise stops for an hour." },
  { id: "productivity-310", title: "A quiet corner in a crowded home", category: "productivity", text: "Create a quiet corner in [your crowded home] for your work. Choose a spot near a window, keep a small table and chair there, and tell the family this corner is your work space. Even a small, fixed corner helps your mind switch into focus mode." },
  { id: "productivity-311", title: "Focus while guests visit your home", category: "productivity", text: "When guests visit, protect your focus on [your work] by greeting them warmly, then asking a family member to look after them for one hour. Work in a closed room, finish one clear part of your task, and then join the guests. A short, honest request works better than silent frustration." },
  { id: "productivity-312", title: "Work while children play in the next room", category: "productivity", text: "While your children play in the next room, work on [your task] in 25 minute rounds with the door half open, so you can hear them but still focus. Give them a quiet game before you start, and use your breaks to check on them and play for a few minutes." },
  { id: "productivity-313", title: "Focus in a shared room with your brother", category: "productivity", text: "If you share a room with your brother, agree on a daily quiet hour for [your study]. During that hour, he uses earphones or reads quietly, and you study without talking. Swap the favour the next hour, so both of you get focused time every day." },
  { id: "productivity-314", title: "Stay focused in a long online class", category: "productivity", text: "Stay focused in [your long online class] by sitting at a table, keeping your notebook open, and writing one line of notes every few minutes. Keep your phone in another room and your camera on, so you stay alert. Stand and stretch during the break between sessions." },
  { id: "productivity-315", title: "Take notes during an online lecture", category: "productivity", text: "During [your online lecture], take short notes in your own words instead of only listening. Write the main point of each slide, and mark anything you do not understand with a star. After the class, read your notes once and clear the starred doubts the same day." },
  { id: "productivity-316", title: "Focus in a live class on a small phone", category: "productivity", text: "If you attend [your live class] on a small phone, keep the phone on a stand at eye level, use earphones, and sit in a bright, quiet corner. Keep a notebook beside you and write the key points. A steady phone and a notebook beat holding the phone in your hand." },
  { id: "productivity-317", title: "Prepare questions before an online class", category: "productivity", text: "Before [your online class], read the topic for ten minutes and write down three questions you want answered. Keep the questions in front of you during the class and listen for the answers. Having questions ready keeps your mind active instead of drifting." },
  { id: "productivity-318", title: "A focus routine before online classes", category: "productivity", text: "Build a short focus routine before [your online class]. Charge your phone or laptop, keep your notebook and pen ready, drink a glass of water, and close all other apps. Starting the class prepared stops the first ten minutes from being lost to scrambling." },
  { id: "productivity-319", title: "Stay awake during an afternoon online class", category: "productivity", text: "Stay awake during [your afternoon online class] by washing your face before it starts, sitting upright in a chair, and keeping a glass of water nearby. Take notes actively, and stand up for a minute during any break. A cool room and an upright chair beat a warm bed." },
  { id: "productivity-320", title: "Focus during a boring online lecture", category: "productivity", text: "When [your online lecture] feels boring, stay focused by turning it into a game. Write down five new facts you learn, and try to frame one question for the teacher. Looking for facts and questions keeps your mind busy, even when the lecture moves slowly." },
  { id: "productivity-321", title: "Revise after an online class the same day", category: "productivity", text: "Revise [your online class] the same evening while it is still fresh. Read your notes once, close the notebook, and write down the three main points from memory. Then check what you missed. Same-day revision takes 15 minutes and saves hours later." },
  { id: "productivity-322", title: "Focus in a group video class", category: "productivity", text: "In [your group video class], stay focused by keeping your camera on, sitting upright, and speaking at least once during the session. Answer a question, share an example, or ask a doubt. Speaking once keeps you alert for the whole class." },
  { id: "productivity-323", title: "Sit properly for an online class at home", category: "productivity", text: "Sit properly for [your online class] at a table and chair, with your back straight and your feet on the floor. Avoid studying on the bed, where your body wants to sleep. A proper sitting posture tells your brain that class time is work time." },
  { id: "productivity-324", title: "A distraction-free setup for online classes", category: "productivity", text: "Set up a distraction-free corner for [your online classes]. Keep only your laptop, notebook and water bottle on the table, and put your phone in another room. Tell your family your class timings, and close the door so nobody walks in during the lesson." },
  { id: "productivity-325", title: "Focus during a recorded video lesson", category: "productivity", text: "Watch [your recorded video lesson] in one sitting without pausing every few minutes. Keep a notebook open, write the key points, and pause only to write a difficult point. After the video ends, read your notes once and test yourself with three questions." },
  { id: "productivity-326", title: "Take a proper break between online classes", category: "productivity", text: "Between [your online classes], take a real break away from the screen. Stand up, stretch, drink water, and look out of the window for five minutes. Do not open social media, or the break will eat into the next class. Return to your desk one minute before it starts." },
  { id: "productivity-327", title: "Stay focused in a three hour online session", category: "productivity", text: "For [your three hour online session], break it into three parts in your mind, one hour at a time. Take notes in each part, stand during the breaks, and keep water nearby. Focus on finishing one hour well, then the next, instead of worrying about all three hours." },
  { id: "productivity-328", title: "Use a notebook during online classes", category: "productivity", text: "Keep a paper notebook open during [your online class] and write by hand. Writing by hand forces you to listen and choose the important points, unlike typing everything. After class, read the notebook once and highlight the three points you must revise." },
  { id: "productivity-329", title: "Deep work plan for writing a report", category: "productivity", text: "Plan a deep work session for [your report]. Block two quiet hours, gather your notes and data first, and write the rough draft without stopping to check facts. Mark the missing facts with a star and fill them in later. A full rough draft beats a perfect first paragraph." },
  { id: "productivity-330", title: "Deep work for coding one feature daily", category: "productivity", text: "Give [one feature] a daily deep work block of 90 minutes. Start by reading the requirement once, write the steps on paper, and then code without opening chats or videos. Test your code in the last 15 minutes, and write down what is left for tomorrow." },
  { id: "productivity-331", title: "Deep work for studying a tough chapter", category: "productivity", text: "Study [your toughest chapter] in a deep work block of two hours. Read it slowly once, then close the book and explain it aloud in your own words. Write down the parts you could not explain, read them again, and explain them once more until they are clear." },
  { id: "productivity-332", title: "A deep work morning for a writer", category: "productivity", text: "Use the first two hours of the morning for [your writing] before checking any messages. Keep your phone away, your notes open, and a glass of water nearby. Write freely without editing, and save the corrections for later. Mornings are often the quietest time to write well." },
  { id: "productivity-333", title: "Deep work for preparing a thesis", category: "productivity", text: "Prepare [your thesis or project] in daily deep work blocks of two hours. Each day, finish one clear section, like one chapter or one set of tables. Keep all your papers in one folder, and start each block by reading yesterday's last paragraph to pick up the thread." },
  { id: "productivity-334", title: "Deep work for memorising new words", category: "productivity", text: "Memorise [ten new words] in a deep work block of 45 minutes. Write each word, say it aloud, use it in a simple sentence, and then cover the list and recall them. Repeat the recall after one hour and again the next morning, so the words stay in your memory." },
  { id: "productivity-335", title: "Deep work for a research project", category: "productivity", text: "Work on [your research project] in focused blocks of 90 minutes. In each block, read one source fully and write a short summary in your own words. Keep the summaries in one notebook, and at the end of the week, read them together to see the full picture." },
  { id: "productivity-336", title: "A deep work routine for a CA student", category: "productivity", text: "As a CA student, give [one subject] a deep work block of three hours every morning. Solve problems on paper without looking at the answers first, and mark the ones you got wrong. Use the last 30 minutes to redo only the marked problems." },
  { id: "productivity-337", title: "Deep work for editing a long document", category: "productivity", text: "Edit [your long document] in a quiet block of 90 minutes. Read it aloud slowly, and fix one thing at a time: first the facts, then the order of paragraphs, then the spelling. Reading aloud catches mistakes your eyes skip when you read silently." },
  { id: "productivity-338", title: "A deep work plan for a UPSC aspirant", category: "productivity", text: "Plan your deep work day as a UPSC aspirant around [one subject]. Study it for three hours in the morning, revise notes for one hour after lunch, and solve ten practice questions in the evening. Keep your phone away during the morning block, when your mind is freshest." },
  { id: "productivity-339", title: "Deep work for designing a poster", category: "productivity", text: "Design [your poster] in a focused block of two hours. First, sketch the layout on paper and choose the main words. Then build the design without checking messages or browsing for ideas. Finish a full draft, take a break, and look at it fresh before making changes." },
  { id: "productivity-340", title: "Deep work for a school project deadline", category: "productivity", text: "Finish [your school project] with three deep work blocks over two days. Block one: gather the material and plan the pages. Block two: write the full content. Block three: add pictures, check the spelling, and practise explaining it. Do not leave it for the last night." },
  { id: "productivity-341", title: "A deep work evening for a working student", category: "productivity", text: "After office, use one deep work hour in the evening for [your study]. Change your clothes, eat something light, and sit down at the same time every day. Study one topic only, keep your phone away, and stop on time so you can sleep well." },
  { id: "productivity-342", title: "Deep work for practising maths problems", category: "productivity", text: "Practise [your maths chapter] in a deep work block of one hour. Solve each problem fully on paper without peeking at the answer. If you get stuck, try for five more minutes, then mark it and move on. Return to the marked problems at the end with fresh eyes." },
  { id: "productivity-343", title: "Handle interruptions from family politely", category: "productivity", text: "When family interrupts [your work], respond politely instead of snapping. Say what you are doing, when you will be free, and ask them to note their question for later. A calm, clear answer protects both your focus and your relationship with your family." },
  { id: "productivity-344", title: "Tell colleagues you need quiet time", category: "productivity", text: "Tell your colleagues politely that you need one quiet hour for [your urgent work]. Say the exact time you will be free again, and ask them to message you instead of coming to your desk. Most colleagues respect a clear time limit better than a vague request." },
  { id: "productivity-345", title: "A polite reply when someone interrupts work", category: "productivity", text: "Prepare a polite reply for interruptions during [your work], like asking the person to give you ten minutes and promising to come to them. Keep the reply short and warm. Having the words ready stops you from reacting angrily in the moment." },
  { id: "productivity-346", title: "Handle a knock on the door during study", category: "productivity", text: "When someone knocks during [your study], open the door, listen to what they need, and give a clear answer. If it can wait, say you will come in 30 minutes. If it is urgent, handle it and return to your books at once, instead of letting the break stretch." },
  { id: "productivity-347", title: "Deal with interruptions from your children", category: "productivity", text: "When your children interrupt [your work], give them a quick hug, listen to their need, and set them up with an activity before returning to work. A calm five minute pause settles them faster than shouting, and you can return to your task with a clear mind." },
  { id: "productivity-348", title: "Ask your family for one quiet hour", category: "productivity", text: "Ask your family for one quiet hour every day for [your work or study]. Choose the same hour, explain what you are working on, and promise to be fully free afterwards. When the family sees you keep your promise, they will protect your quiet hour willingly." },
  { id: "productivity-349", title: "Handle interruptions during an important call", category: "productivity", text: "Before [your important call], tell your family the call time and ask them not to enter the room. Keep the door closed and your notes ready. If someone still interrupts, mute yourself for a moment, handle it briefly, and return to the call calmly." },
  { id: "productivity-350", title: "A sign on the door for focus time", category: "productivity", text: "Put a simple sign on your door during [your focus time], saying when you will be free. Write it by hand on paper, with the time clearly shown. A visible sign is a polite reminder that works better than repeating the same request to everyone in the house." },
  { id: "productivity-351", title: "Deal with a chatty colleague at work", category: "productivity", text: "When a chatty colleague stops by during [your work], listen for a minute, then say warmly that you must finish this task by [a time] and will chat during lunch. Standing up and walking them towards the door gently also helps end the chat without hurting feelings." },
  { id: "productivity-352", title: "Handle interruptions during exam revision", category: "productivity", text: "During [your exam revision], handle interruptions by keeping a small notepad nearby. When someone interrupts, note their message on the pad and return to your books at once. Deal with all the noted messages together during your break, instead of after each one." },
  { id: "productivity-353", title: "Return to work after an interruption quickly", category: "productivity", text: "After an interruption, return to [your work] quickly by reading the last line you wrote and the next step on your list. Do not check your phone or start a new task in between. A fast return stops one small interruption from breaking your whole work block." },
  { id: "productivity-354", title: "Ask your spouse for quiet study time", category: "productivity", text: "Ask your spouse for quiet study time for [your exam or course], and offer the same help in return. Agree on the hours, share the household jobs around them, and thank them when they keep the house calm. Teamwork at home makes focused study possible for both of you." },
  { id: "productivity-355", title: "Handle interruptions from delivery people", category: "productivity", text: "When a delivery person arrives during [your work], handle it in two minutes: open the door, collect the parcel, and return to your desk. Keep a small tray near the door for cash or change, so you do not waste time searching. Then read your last sentence and continue." },
  { id: "productivity-356", title: "A family rule for study hours at home", category: "productivity", text: "Make a simple family rule for study hours at home during [your exam season]. During those hours, the TV stays off, visitors wait, and everyone speaks softly. Write the hours on a paper on the fridge, so the whole family can see and follow them." },
  { id: "productivity-357", title: "Deal with interruptions in a shared office", category: "productivity", text: "In a shared office, deal with interruptions to [your work] by wearing earphones, which signals that you are busy. Keep a small notebook for messages, and answer them in a batch every hour. Most interruptions can wait an hour without any harm." },
  { id: "productivity-358", title: "Stay focused in a long office meeting", category: "productivity", text: "Stay focused in [your long office meeting] by writing down the decisions and your own action points as they are discussed. Sit upright, keep water nearby, and ask one question when you do not understand something. Active note-taking keeps your mind in the room." },
  { id: "productivity-359", title: "Take notes to stay alert in meetings", category: "productivity", text: "Take short notes in [your meeting] to stay alert from start to finish. Write the speaker's main point, any date or number mentioned, and the tasks given to you. Review the notes right after the meeting and send a short summary to yourself, so nothing is forgotten." },
  { id: "productivity-360", title: "Focus during a two hour training session", category: "productivity", text: "Focus during [your two hour training session] by arriving with a notebook and a clear question you want answered. Write down each new idea, and try one small exercise the trainer suggests. Participating keeps you awake far better than sitting silently." },
  { id: "productivity-361", title: "Stay awake in a meeting after lunch", category: "productivity", text: "Stay awake in [your after-lunch meeting] by drinking water before it starts, sitting upright, and taking notes from the first minute. Avoid a heavy lunch on meeting days, and take a short walk before the meeting. A light meal and an active mind beat a sleepy afternoon." },
  { id: "productivity-362", title: "Focus in a video meeting from home", category: "productivity", text: "Focus in [your video meeting from home] by joining from a quiet room, keeping your camera on, and closing all other tabs. Keep your notes in front of you and speak at least once. A camera-on meeting feels real, and you stay far more alert." },
  { id: "productivity-363", title: "Prepare before a long meeting", category: "productivity", text: "Prepare before [your long meeting] by reading the agenda for ten minutes and writing down your two main points. Keep the papers you need in one folder, and arrive five minutes early. A prepared person listens better, because they know what to listen for." },
  { id: "productivity-364", title: "Ask a question to stay engaged in meetings", category: "productivity", text: "Stay engaged in [your meeting] by asking at least one good question. Listen for a point you do not fully understand, and ask about it clearly. Asking a question keeps your mind active, and it shows the speaker that you are paying attention." },
  { id: "productivity-365", title: "Focus during a boring presentation", category: "productivity", text: "During [a boring presentation], stay focused by writing down three useful points, even if they are small. Look for one idea you can use in your own work. Hunting for useful points keeps your mind busy, instead of counting the minutes until it ends." },
  { id: "productivity-366", title: "Stay focused in a parent teacher meeting", category: "productivity", text: "Stay focused in [your parent teacher meeting] by writing down the teacher's main points about your child, and the two questions you want to ask. Listen fully before replying, and note the action points for home. Clear notes help you act on the meeting later." },
  { id: "productivity-367", title: "Focus during a society meeting at night", category: "productivity", text: "Focus during [your society meeting] by arriving on time, sitting near the front, and keeping a small notebook. Write down each decision and who will do it. Sitting near the front keeps you alert, and your notes help you remember what was agreed." },
  { id: "productivity-368", title: "A focus plan for a full day workshop", category: "productivity", text: "Plan your focus for [a full day workshop] by breaking the day into sessions. For each session, write one thing you want to learn. Take notes, stand and stretch during breaks, and drink water often. A session-by-session plan keeps a long day from feeling endless." },
  { id: "productivity-369", title: "Stay alert in a morning team meeting", category: "productivity", text: "Stay alert in [your morning team meeting] by reading the agenda the night before and writing down your update in three short lines. Speak early in the meeting, while your mind is fresh. An early contribution keeps you engaged for the rest of the discussion." },
  { id: "productivity-370", title: "Refocus quickly after a tea break", category: "productivity", text: "After your tea break, refocus on [your work] by reading the last line you wrote before the break. Write down the next small step, set a timer for 25 minutes, and start at once. A quick restart stops a five minute break from becoming a 30 minute drift." },
  { id: "productivity-371", title: "Get back to work after lunch", category: "productivity", text: "Get back to [your work] after lunch by starting with an easy task for ten minutes, like sorting papers or replying to one message. Then move to your main task with a timer. A gentle restart beats sitting down to the hardest job while you still feel sleepy." },
  { id: "productivity-372", title: "Refocus after a phone call at work", category: "productivity", text: "After a phone call, refocus on [your task] by writing down the call's main points in 30 seconds, then reading your last sentence of work. Put the phone away and set a 25 minute timer. Writing the call notes down clears your mind for the work ahead." },
  { id: "productivity-373", title: "Return to study after a festival break", category: "productivity", text: "Return to [your study] after a festival break by starting with a light revision day. Read your old notes, solve five easy questions, and plan the next three days. Do not try to cover a full chapter on day one; a gentle restart builds your rhythm back." },
  { id: "productivity-374", title: "Refocus after a long weekend off", category: "productivity", text: "After a long weekend, refocus on [your work] by spending the first 15 minutes listing your three main jobs for the day. Start with the smallest one to build momentum, then move to the bigger ones. A short plan turns Monday morning from chaos into a clear start." },
  { id: "productivity-375", title: "Get back to coding after a break", category: "productivity", text: "Get back to [your coding] after a break by reading the last ten lines you wrote and the comment you left for yourself. Run the code once to see where it stands, then fix the smallest issue first. A small fix rebuilds your flow faster than staring at the whole project." },
  { id: "productivity-376", title: "Refocus after checking WhatsApp messages", category: "productivity", text: "After checking WhatsApp, refocus on [your work] by closing the app fully and putting the phone away. Read the last line you wrote, and set a 20 minute timer for the next part. Do not reply to every message at once; answer them together in your next break." },
  { id: "productivity-377", title: "Start again after a power cut break", category: "productivity", text: "After a power cut, restart [your work] by checking what you had finished before the lights went out. If you study, read the last page again to pick up the thread. If you work on a computer, save your file first, then continue from where you stopped." },
  { id: "productivity-378", title: "Refocus after a short nap at home", category: "productivity", text: "After a short nap, refocus on [your study] by washing your face, drinking water, and reading your notes for five minutes. Start with an easy topic to wake your mind up, then move to the harder one. A 20 minute nap refreshes you, but a slow restart wastes the benefit." },
  { id: "productivity-379", title: "Get back to writing after a visitor leaves", category: "productivity", text: "After a visitor leaves, get back to [your writing] by reading the last paragraph you wrote aloud. Write one new sentence at once, even a rough one, to restart your flow. Do not tidy the house or check your phone first, or the writing mood will slip away." },
  { id: "productivity-380", title: "Use soft music to focus while working", category: "productivity", text: "Play soft music without words while working on [your task]. Keep the volume low, so it sits in the background and does not pull your attention. Try instrumental music or gentle rain sounds, and stop the music if you notice yourself listening to it instead of working." },
  { id: "productivity-381", title: "A quiet routine before starting work", category: "productivity", text: "Build a quiet routine before [your work]. Clear your desk, fill a water bottle, close extra tabs, and write down your first small step. Doing the same three steps every day tells your mind that work is starting, and helps you settle into focus faster." },
  { id: "productivity-382", title: "Focus music for studying at night", category: "productivity", text: "Study [your subject] at night with soft focus music playing quietly in the background. Choose music without lyrics, keep the volume low, and use the same playlist every night. A familiar, calm sound helps your mind settle, and signals that it is study time." },
  { id: "productivity-383", title: "A calm playlist for office work", category: "productivity", text: "Make a calm playlist for [your office work] with gentle instrumental songs that last about one hour. Play it during your focused work block, and stop it during breaks. A fixed playlist removes the need to choose songs, which itself is a distraction." },
  { id: "productivity-384", title: "Use white noise to block office sounds", category: "productivity", text: "Use white noise through earphones to block office sounds while working on [your task]. White noise is a steady, soft sound that covers phone rings and nearby talking. Keep the volume low, and take the earphones off during breaks to rest your ears." },
  { id: "productivity-385", title: "A quiet start before a deep work session", category: "productivity", text: "Before a deep work session on [your task], spend ten quiet minutes with no phone, no TV and no talking. Sit with your notes, read the plan once, and decide the first step. A quiet start clears the noise of the morning and lets you enter deep work calmly." },
  { id: "productivity-386", title: "Rain sounds for focus while studying", category: "productivity", text: "Play gentle rain sounds while studying [your subject] to cover the noise of the house. Keep the volume low and steady, and use the same sound every day. Rain sounds have no words to follow, so your mind can stay with your books while the background feels calm." },
  { id: "productivity-387", title: "A silent hour routine for the family", category: "productivity", text: "Fix one silent hour every evening for [your family], when the TV stays off and everyone does quiet work. Children study, parents read or plan, and nobody talks loudly. A shared silent hour makes focus easier for everyone, because nobody is the only one working." },
  { id: "productivity-388", title: "Focus music for study on a train journey", category: "productivity", text: "Study [your notes] on a train journey with soft focus music in your earphones. The music covers the train noise, and your notes stay in front of you. Revise short points that fit on one page, and keep your bag and phone safe beside you." },
  { id: "productivity-389", title: "A quiet evening routine for revision", category: "productivity", text: "Build a quiet evening routine for revising [your subject]. After dinner, switch off the TV, sit in the same spot, and revise your notes for 40 minutes. End by writing three questions from memory. The same routine every evening trains your mind to focus on time." },
  { id: "productivity-390", title: "Build attention span for a young student", category: "productivity", text: "Build attention span for [your young student] with short, fun focus sessions. Start with 10 minutes of one activity, like reading or a puzzle, then add five minutes each week. Praise the child for finishing, and keep the phone and TV away during the session." },
  { id: "productivity-391", title: "Help a class 5 student focus longer", category: "productivity", text: "Help [your class 5 student] focus longer by breaking homework into 15 minute parts with short breaks. Give one clear task at a time, like five sums, and check it together before the next part. Small wins keep a young child interested and build longer focus slowly." },
  { id: "productivity-392", title: "Attention exercises for a restless child", category: "productivity", text: "Try attention exercises for [your restless child], like listening to a story and retelling it, or sorting coloured buttons by size. Do one exercise for ten minutes every day. Playful focus games train a child's attention without making study feel like a punishment." },
  { id: "productivity-393", title: "Build focus for a teenager studying at home", category: "productivity", text: "Build focus for [your teenager] by agreeing on fixed study hours together, with the phone kept outside the room. Let them choose the subject order, and check their progress at the end of each hour. Choice plus clear rules works better than constant watching." },
  { id: "productivity-394", title: "A focus plan for a student with short attention", category: "productivity", text: "Make a focus plan for [your student] who struggles to sit still. Use 15 minute study rounds with 5 minute movement breaks, like stretching or walking to the next room. Give one small task per round, and tick it off together. Short rounds build attention step by step." },
  { id: "productivity-395", title: "Help your child focus on homework daily", category: "productivity", text: "Help [your child] focus on homework by fixing the same time and place every day. Clear the table, keep the TV off, and sit nearby with your own quiet work. A fixed routine and a calm parent nearby make homework feel normal, not like a daily battle." },
  { id: "productivity-396", title: "Attention span games for a primary student", category: "productivity", text: "Play attention games with [your primary school child], like memory cards, spot the difference, or listening to a story and naming three details. Play for 15 minutes daily. These games stretch a child's attention span while feeling like play, not study." },
  { id: "productivity-397", title: "A focus routine for a class 10 student", category: "productivity", text: "Build a focus routine for [your class 10 student] with two study blocks daily: one hour in the morning and one hour in the evening. Keep the phone away during both blocks, and use the last ten minutes to write down what was learned. Steady blocks beat last-minute panic." },
  { id: "productivity-398", title: "Build attention for a slow learner gently", category: "productivity", text: "Build attention gently for [your slow learner] with very short tasks and lots of praise. Give one question at a time, wait patiently, and celebrate each correct answer. Never compare the child with others. Slow, kind steps build focus better than pressure." },
  { id: "productivity-399", title: "A focus plan for a student preparing for boards", category: "productivity", text: "Make a focus plan for [your board exam student] with three study blocks a day and a fixed phone-free rule during each block. Mix one hard subject with one easy subject daily, and keep Sundays for revision only. A steady plan reduces fear and builds real confidence." },
  { id: "productivity-400", title: "Focus while working from home with kids", category: "productivity", text: "Focus on [your work from home] with kids around by working in short 30 minute rounds. Give the children an activity before each round, close your door halfway, and use your breaks to play with them. Short rounds plus happy breaks keep both work and children calm." },
  { id: "productivity-401", title: "Work from home with a toddler nearby", category: "productivity", text: "Work from home with [your toddler] nearby by planning your hardest tasks for nap time. During waking hours, do easy jobs like replying to messages while the child plays beside you. Keep toys in a basket near your desk, so the child stays close and safe." },
  { id: "productivity-402", title: "A work plan when kids are on holiday", category: "productivity", text: "When the kids are on holiday, plan [your work] around their day. Work early in the morning before they wake, and again during their afternoon rest. Give them a morning activity like drawing or reading, and take a proper lunch break together as a family." },
  { id: "productivity-403", title: "Focus during your child's online class", category: "productivity", text: "While your child attends [their online class], do [your quiet work] in the same room. Keep your own laptop open, help them only when they ask, and avoid phone calls. Your calm presence keeps them focused, and you finish your own work at the same time." },
  { id: "productivity-404", title: "Share childcare and work with your spouse", category: "productivity", text: "Share childcare and work with your spouse by splitting the day into shifts for [your jobs]. One parent watches the children in the morning while the other works, then you swap after lunch. Write the shift times on paper, so both of you know when to focus and when to rest." },
  { id: "productivity-405", title: "Work in short bursts with small kids", category: "productivity", text: "Work in short bursts of 20 minutes on [your task] when you have small kids at home. Set a timer, work fast on one small part, then take a break to check on the children. Four short bursts a day add up to real progress without ignoring your kids." },
  { id: "productivity-406", title: "A quiet activity for kids during work", category: "productivity", text: "Prepare a quiet activity for [your kids] before you start [your work]. Give them colouring books, building blocks, or a simple puzzle that keeps them busy for 30 minutes. A prepared child plays happily, and you get a full, focused work round." },
  { id: "productivity-407", title: "Focus while the baby naps at home", category: "productivity", text: "Use your baby's nap time for [your most important work]. Keep your work ready before the nap starts, so you can begin at once without wasting ten minutes preparing. Work in silence, keep your phone away, and stop when the baby wakes, even mid-sentence." },
  { id: "productivity-408", title: "Work from home with two school kids", category: "productivity", text: "Work from home with [two school kids] by matching your work hours to their school and homework hours. When they study, you work; when they take a break, you take a break too. A shared timetable keeps the whole house in the same rhythm." },
  { id: "productivity-409", title: "A family timetable for work and kids", category: "productivity", text: "Make a family timetable for [your work hours and the children's study hours] and stick it on the fridge. Mark work time, study time, play time and meal time clearly. When everyone can see the plan, children disturb you less, and your work hours stay protected." },
  { id: "productivity-410", title: "Avoid TV during work hours", category: "productivity", text: "Keep the TV switched off during [your work hours], even in the background. A TV in the next room pulls your ears and eyes away every few minutes, even when you think you are ignoring it. Work in a room without a TV, or ask the family to watch later." },
  { id: "productivity-411", title: "Stop checking news during study time", category: "productivity", text: "Stop checking the news during [your study time]. News updates repeat the same stories all day, and each check breaks your focus for ten minutes. Read the news once in the morning and once at night, and keep your study hours completely news-free." },
  { id: "productivity-412", title: "Avoid cricket scores during office work", category: "productivity", text: "Avoid checking cricket scores during [your office work] on match days. Score checks turn into long chats and video clips, and your work piles up. Check the score once during lunch, and watch the highlights after work. The match will still be there in the evening." },
  { id: "productivity-413", title: "A news-free morning for better focus", category: "productivity", text: "Try a news-free morning for [one week] while you work. Skip the news channels and apps until lunch, and use the morning for your hardest task. You will find that your mind feels calmer, and you still learn the important news later in the day." },
  { id: "productivity-414", title: "Stop watching reels during study breaks", category: "productivity", text: "Stop watching short videos during [your study breaks]. One reel leads to twenty, and five minutes quietly turn into thirty. Instead, stretch, drink water, or step outside for fresh air. A real break refreshes your mind; reels only tire it more." },
  { id: "productivity-415", title: "Avoid serials while working from home", category: "productivity", text: "Avoid watching serials while working from home on [your task]. A serial in the background steals your attention with every dialogue, and your work slows down without you noticing. Save the serial for after work, and enjoy it fully without guilt." },
  { id: "productivity-416", title: "A TV-free study room for your child", category: "productivity", text: "Make [your child's study room] TV-free. Move the television to the hall, and keep only books, notes and a water bottle in the study room. A room without a TV removes the biggest temptation, and your child will focus longer without a daily struggle." },
  { id: "productivity-417", title: "Stop news alerts during deep work", category: "productivity", text: "Switch off news alerts on your phone during [your deep work block]. Breaking news rarely needs your attention within the hour, and each alert breaks your focus. Check the news once after the block ends, and keep your deep work hours alert-free." },
  { id: "productivity-418", title: "Avoid match highlights during exam week", category: "productivity", text: "During [your exam week], avoid match highlights and sports videos completely. They are designed to keep you watching, and one video leads to another. Promise yourself a full match as a reward after the exams, and use the saved hours for revision." },
  { id: "productivity-419", title: "Finish the report before checking email", category: "productivity", text: "Finish [your report] fully before you open your email inbox. Email brings new jobs that push your report aside, and it often stays unfinished all day. Write the report first, send it, and only then open your inbox to handle the new messages." },
  { id: "productivity-420", title: "Complete one chapter before starting the next", category: "productivity", text: "Finish [one chapter] completely, including its exercises, before starting the next one. Do not jump ahead when a chapter feels boring, or you will carry gaps into the next topic. A finished chapter gives you a clear win and a solid base for what follows." },
  { id: "productivity-421", title: "Finish cooking before starting your study", category: "productivity", text: "Finish [your cooking] fully, including cleaning the kitchen, before sitting down to study. A half-finished kitchen keeps calling you back, and your mind stays on the stove instead of your books. A clean kitchen and a clear mind make study much easier." },
  { id: "productivity-422", title: "Complete the bill entries before the next job", category: "productivity", text: "Complete [your bill entries] fully before moving to the next shop job. Half-done entries cause confusion later, when you cannot remember which bills are paid. Tick each entry off as you finish it, and only then start the next job with a clear mind." },
  { id: "productivity-423", title: "Finish one email before writing the next", category: "productivity", text: "Write and send [one email] fully before starting the next one. Finish the subject, the message and the attachment, and click send. Starting three emails together leaves all three half done, and you waste time remembering what each one was about." },
  { id: "productivity-424", title: "Close one task fully before opening another", category: "productivity", text: "Close [your current task] fully before opening another one. Save the file, tick it off your list, and clear your desk. A closed task frees your mind completely, while an open task keeps pulling your thoughts back even while you work on something else." },
  { id: "productivity-425", title: "Finish the first job before the second begins", category: "productivity", text: "Make a simple rule for your day: finish [the first job] before the second begins. Write the jobs in order on paper, and do not start the next one until the first is done. This rule stops the pile of half-finished jobs that makes every day feel busy but empty." },
  { id: "productivity-426", title: "Set up a simple note-taking app for daily use", category: "productivity", text: "Help me set up a simple note-taking app on my phone for daily use. I want one place for shopping lists, phone numbers, ideas and reminders. Explain the basic settings, how to make folders, and how to find a note quickly later." },
  { id: "productivity-427", title: "Keep a paper notebook for work notes", category: "productivity", text: "Show me how to keep one paper notebook for all my work notes instead of loose papers. Give me a simple way to start each page, date every note, and mark urgent points. Explain how to find an old note fast when a customer calls." },
  { id: "productivity-428", title: "Turn phone call notes into clear next steps", category: "productivity", text: "I scribbled quick notes during a phone call with [a supplier] and now I cannot read my own writing. Help me turn the messy notes into clear next steps. Ask me what I remember, then list each task with a date and who will do it." },
  { id: "productivity-429", title: "Choose between a notes app and a paper diary", category: "productivity", text: "Help me choose between a notes app on my phone and a paper diary for my daily notes. Compare them simply on cost, finding old notes, sharing with family, and using them without internet. Then suggest which one suits [a busy shopkeeper] best and why." },
  { id: "productivity-430", title: "Make a simple index page for your notebook", category: "productivity", text: "Show me how to make a simple index page at the front of my notebook so I can find old notes. Explain what to write for each entry, how to number the pages, and how to update the index every week without spending more than ten minutes." },
  { id: "productivity-431", title: "Save important messages in one notes file", category: "productivity", text: "I get important details in messages, like addresses, account numbers and order dates, and then I lose them. Show me a simple way to copy them into one notes file. Explain how to organise the file by topic and find a detail in under a minute." },
  { id: "productivity-432", title: "Keep supplier details in one notebook", category: "productivity", text: "Help me keep all my supplier details in one notebook: names, phone numbers, prices and payment dates. Show me a simple layout for each supplier, how to update prices, and how to find a number quickly when I need to order stock." },
  { id: "productivity-433", title: "Use coloured pens to mark notebook sections clearly", category: "productivity", text: "Show me how to use coloured pens to organise my notebook into clear sections. Explain which colour to use for money notes, phone numbers, ideas and reminders. Keep it simple so I can find the right page at a glance." },
  { id: "productivity-434", title: "Move old paper notes into a phone app", category: "productivity", text: "Help me move my old paper notes into a notes app on my phone. Give me a simple step-by-step plan I can finish in small parts over one week. Explain how to sort the notes first and check that nothing important gets lost." },
  { id: "productivity-435", title: "Share a shopping list note with family", category: "productivity", text: "Show me how to share one shopping list note with my family so everyone can add items. Explain how to set it up on a phone, how to tick off items already bought, and what to do if two people edit the list at the same time." },
  { id: "productivity-436", title: "Keep a small notebook by your bed for ideas", category: "productivity", text: "Help me keep a small notebook by my bed for ideas that come at night. Show me a quick way to write them down in a few words, sort them in the morning, and move the good ones into my main notebook without losing any." },
  { id: "productivity-437", title: "Start a new notebook without losing old notes", category: "productivity", text: "Show me how to start a new notebook when the old one is full without losing any old notes. Explain how to carry forward unfinished lists, mark the old notebook clearly, and store it where I can still find it." },
  { id: "productivity-438", title: "Organise notes from different family members in one app", category: "productivity", text: "My family shares one phone for notes, and everyone's lists get mixed up. Help me organise the notes so each person has their own section. Explain how to name the sections, colour them differently, and keep private notes separate from shared ones." },
  { id: "productivity-439", title: "Make a daily checklist for opening your shop", category: "productivity", text: "Help me make a simple daily checklist for opening my small shop in the morning. List the tasks in order, from unlocking and cleaning to checking stock and cash. Keep the list short enough to finish in fifteen minutes every day." },
  { id: "productivity-440", title: "Make a closing checklist for your shop each evening", category: "productivity", text: "Help me make a simple closing checklist for my shop each evening. Include counting cash, locking up, switching off fans and lights, and noting tomorrow's urgent jobs. Keep it short so I can finish it in ten minutes." },
  { id: "productivity-441", title: "Make a monthly checklist for paying bills", category: "productivity", text: "Help me make a monthly checklist for paying all my household bills on time. Include electricity, water, gas, phone, internet and rent. Explain how to tick each bill off, note the payment date, and spot any bill I have missed." },
  { id: "productivity-442", title: "Make a template for messages you send every week", category: "productivity", text: "I send the same kind of message to customers every week, like order updates and payment reminders. Help me make a simple message template I can reuse. Show me which parts to keep fixed and which parts to change each time." },
  { id: "productivity-443", title: "Make a checklist for your first day at work", category: "productivity", text: "Help me make a checklist for my first day at a new job. Include documents to carry, questions to ask, people to meet and things to set up on my desk. Keep it simple so I feel calm and ready." },
  { id: "productivity-444", title: "Create a template for tracking daily shop sales", category: "productivity", text: "Help me make a simple template for writing down my shop's daily sales. Include the date, total cash, total UPI payments and best-selling item. Explain how to fill it in every evening in two minutes and use it at the end of the month." },
  { id: "productivity-445", title: "Make a monthly checklist for your bank tasks", category: "productivity", text: "Help me make a monthly checklist for my bank tasks. Include checking the balance, noting any unknown charges, updating the passbook and keeping receipts. Explain how to do it in one sitting of twenty minutes each month." },
  { id: "productivity-446", title: "Make a yearly checklist for renewing documents", category: "productivity", text: "Help me make a yearly checklist for renewing documents like insurance, vehicle papers and licences. List each document, its renewal month and where to keep the receipt. Explain how to set reminders so nothing expires by mistake." },
  { id: "productivity-447", title: "Make a template for recording customer orders", category: "productivity", text: "Help me make a simple template for recording customer orders in my notebook. Include the customer name, item, quantity, price, advance paid and delivery date. Explain how to fill it in quickly and find an old order later." },
  { id: "productivity-448", title: "Make a reusable checklist for ordering stock", category: "productivity", text: "Help me make a reusable checklist for ordering stock for my shop. List each item, the usual supplier, the lowest stock level and the order quantity. Explain how to check it every Monday and tick off items as they arrive." },
  { id: "productivity-449", title: "Make a template for comparing two suppliers", category: "productivity", text: "Help me make a simple template for comparing two suppliers before I buy stock. Include price, quality, delivery time, payment terms and past service. Explain how to fill it in with real numbers and choose the better one." },
  { id: "productivity-450", title: "Make a weekly checklist for keeping your desk tidy", category: "productivity", text: "Help me make a simple weekly checklist for keeping my work desk tidy. Include clearing papers, filing bills, cleaning the surface and checking pens and chargers. Explain how to finish it in ten minutes every Saturday." },
  { id: "productivity-451", title: "Make a checklist for a community event you organise", category: "productivity", text: "Help me make a checklist for organising a small community event in my area. Include the venue, invitations, food, seating and clean-up. Explain how to share the jobs with helpers and check each task off on the day." },
  { id: "productivity-452", title: "Sort your computer files into five simple folders", category: "productivity", text: "Help me sort all my computer files into five simple folders: work, money, family, photos and important documents. Explain what goes in each folder, how to move files quickly, and how to keep new files in the right place every time." },
  { id: "productivity-453", title: "Name your files so you can find them later", category: "productivity", text: "Show me a simple way to name my files so I can find them later. Give me a clear naming pattern using the date and a short description. Explain with examples for bills, photos and school certificates." },
  { id: "productivity-454", title: "Organise your scanned documents into yearly folders", category: "productivity", text: "Help me organise my scanned documents into yearly folders on my computer. Explain how to name each year folder, split it into money, health and school parts, and move old scans in without losing any file." },
  { id: "productivity-455", title: "Keep work files and personal files separate", category: "productivity", text: "Show me how to keep my work files and personal files separate on one computer. Explain how to set up two main folders, what to do with files that belong to both, and how to stop mixing them up again." },
  { id: "productivity-456", title: "Organise your children's school files by year", category: "productivity", text: "Help me organise my children's school files by year and subject on my computer. Explain how to make one folder per child, split it by school year, and name report cards and certificates so I can find them in seconds." },
  { id: "productivity-457", title: "Sort your downloaded files every Sunday", category: "productivity", text: "Show me a simple Sunday routine for sorting the files I downloaded during the week. Explain how to check the downloads folder, move each file to its proper place, and delete the ones I do not need in under fifteen minutes." },
  { id: "productivity-458", title: "Make a folder for each customer or client", category: "productivity", text: "Help me make one folder for each regular customer on my computer. Explain what to store inside: orders, bills, payment notes and messages. Show me how to name the folders and find a customer's full history in under a minute." },
  { id: "productivity-459", title: "Organise your shop's bills into monthly folders", category: "productivity", text: "Help me organise my shop's bills into monthly folders on my computer. Explain how to name each month, sort purchase bills and sale bills separately, and check at month end that no bill is missing." },
  { id: "productivity-460", title: "Delete duplicate files safely from your computer", category: "productivity", text: "Show me how to find and delete duplicate files on my computer safely. Explain how to spot copies with the same name and size, check which copy is the newest, and keep one safe copy before deleting the rest." },
  { id: "productivity-461", title: "Keep your desktop clean with three folders only", category: "productivity", text: "Help me keep my computer desktop clean using only three folders: today, this week and important. Explain what goes in each folder, how to move files out every Friday, and why a clear desktop helps me find things faster." },
  { id: "productivity-462", title: "Organise your phone's documents folder simply", category: "productivity", text: "Show me how to organise the documents folder on my phone simply. Explain how to make folders for money, school, health and work, move each document to the right folder, and keep new downloads from piling up." },
  { id: "productivity-463", title: "Organise all your small business files in one place", category: "productivity", text: "Help me organise all my small business files in one place on my computer. Explain how to make folders for bills, orders, tax papers and staff notes, and how to keep the system simple enough to use every day." },
  { id: "productivity-464", title: "Label folders with colours for quick finding", category: "productivity", text: "Show me how to use coloured folder labels to find files quickly on my computer. Explain which colour to use for urgent, money, school and personal files, and how to keep the colour system the same on my phone too." },
  { id: "productivity-465", title: "Find any file on your computer in seconds", category: "productivity", text: "Show me how to find any file on my computer in seconds using search. Explain what words to type, how to search by file name or date, and what to do when the file does not appear in the results." },
  { id: "productivity-466", title: "Find an old bill using file search", category: "productivity", text: "Help me find an old electricity bill on my computer using search. Explain which words to type, how to narrow the search by month, and how to save the bill in a place where I can find it again easily." },
  { id: "productivity-467", title: "Use search in your notes app to find anything", category: "productivity", text: "Show me how to use search inside my notes app to find any note in seconds. Explain which words to type, how to search by a date or a person's name, and how to keep my notes tidy so search works better." },
  { id: "productivity-468", title: "Find a file when you forgot its name", category: "productivity", text: "Help me find a file on my computer when I have forgotten its name. Explain how to search by the date I made it, the type of file, and the folder it might be in. Give me a simple step-by-step method to try first." },
  { id: "productivity-469", title: "Find a document using the recent files list", category: "productivity", text: "Show me how to find a document I worked on yesterday using the recent files list. Explain where to find the list on a computer and a phone, and what to do if the file is not listed there." },
  { id: "productivity-470", title: "Use tags to find files faster", category: "productivity", text: "Explain in simple words how to use tags or labels to find files faster on a computer. Give me a small set of tags for money, school, work and family, and show me how to add a tag when I save a new file." },
  { id: "productivity-471", title: "Recover a file you deleted by mistake", category: "productivity", text: "Help me recover a file I deleted from my computer by mistake. Explain where deleted files go, how to restore one in a few clicks, and what to do if it is no longer in the recycle bin." },
  { id: "productivity-472", title: "Find a file shared with you last month", category: "productivity", text: "Help me find a file someone shared with me last month on my phone. Explain where shared files are stored, how to search by the sender's name or the date, and how to save a copy in my own folder." },
  { id: "productivity-473", title: "Find the newest version of a document", category: "productivity", text: "Help me find the newest version of a document when I have saved it several times. Explain how to check the dates, compare file sizes, and rename the final version clearly so I never open the wrong copy again." },
  { id: "productivity-474", title: "Use file history to find yesterday's work", category: "productivity", text: "Show me how to use the file history on my computer to find the work I did yesterday. Explain where to look, how to open a file from the list, and how to pin the files I use every day." },
  { id: "productivity-475", title: "Find a school certificate in your files", category: "productivity", text: "Help me find my child's school certificate in my computer files. Explain how to search by the school name or year, check the right folder first, and save a clear copy on my phone for quick sharing." },
  { id: "productivity-476", title: "Search inside a document for one word", category: "productivity", text: "Show me how to search inside a long document for one word or number. Explain the simple shortcut to open search, what to type, and how to jump from one match to the next without reading the whole document." },
  { id: "productivity-477", title: "Find a file by its size or type", category: "productivity", text: "Explain in simple words how to find a file by its size or type on a computer. Show me how to list only photos, only documents or only large files, and how to use that list to clean up space safely." },
  { id: "productivity-478", title: "Sort your email inbox into simple folders", category: "productivity", text: "Help me sort my email inbox into simple folders: bills, school, work, shopping and family. Explain how to make each folder, move old emails into the right one, and keep new emails sorted without spending much time." },
  { id: "productivity-479", title: "Use labels to mark important emails", category: "productivity", text: "Show me how to use labels to mark important emails in my inbox. Explain how to make labels for urgent, money and school emails, how to apply a label in one tap, and how to find all emails with one label." },
  { id: "productivity-480", title: "Search your inbox for an old bill", category: "productivity", text: "Help me search my email inbox for an old bill I need to show someone. Explain which words to type, how to search by the sender's name or the month, and how to save the bill so I can find it again quickly." },
  { id: "productivity-481", title: "Clear a crowded inbox in one hour", category: "productivity", text: "Help me clear my crowded email inbox in one hour. Give me a simple plan: delete old offers first, file the important emails, and unsubscribe from newsletters I never read. Explain how to do each step quickly without missing anything important." },
  { id: "productivity-482", title: "Set up email filters for bills automatically", category: "productivity", text: "Show me how to set up a simple email filter so all my bills go into one folder automatically. Explain the steps in plain words, how to test that it works, and how to change the filter if a bill lands in the wrong folder." },
  { id: "productivity-483", title: "Stop unwanted emails without blocking friends", category: "productivity", text: "Help me stop unwanted promotional emails without blocking messages from friends and family. Explain how to unsubscribe safely, mark spam correctly, and check that important emails still reach my inbox." },
  { id: "productivity-484", title: "Find an email from a school or office", category: "productivity", text: "Help me find an email from [my child's school] in my crowded inbox. Explain how to search by the sender's name, use the date to narrow it down, and star the email so I can open it again in one tap." },
  { id: "productivity-485", title: "Organise emails by sender for quick reading", category: "productivity", text: "Show me how to organise my emails by sender so I can read them quickly. Explain how to group emails from one shop, one school or one bank together, and how to check only the newest email from each sender." },
  { id: "productivity-486", title: "Save important email attachments in folders", category: "productivity", text: "Help me save important email attachments, like bills and certificates, into folders on my phone. Explain how to download an attachment, name it clearly, and move it to the right folder so I can find it later." },
  { id: "productivity-487", title: "Check email once a day without missing anything", category: "productivity", text: "Help me check my email only once a day without missing anything important. Show me how to turn off constant alerts, set one fixed checking time, and mark urgent senders so their emails stand out in my inbox." },
  { id: "productivity-488", title: "Archive old emails instead of deleting them", category: "productivity", text: "Explain in simple words the difference between archiving and deleting an email. Show me how to archive old emails I might need later, how to find an archived email, and when it is safe to delete one for good." },
  { id: "productivity-489", title: "Set up a separate email folder for shopping orders", category: "productivity", text: "Help me set up a separate email folder just for my shopping orders. Explain how to move order emails there, how to find a delivery date quickly, and how to keep the folder tidy after each order arrives." },
  { id: "productivity-490", title: "Use stars and flags to mark emails to reply", category: "productivity", text: "Show me how to use stars or flags to mark emails I still need to reply to. Explain how to mark an email, find all marked emails in one list, and clear the mark after I have replied so nothing is missed." },
  { id: "productivity-491", title: "Make a simple spreadsheet to track monthly spending", category: "productivity", text: "Help me make a simple spreadsheet to track my monthly spending. Include columns for the date, what I bought, the shop and the amount in ₹. Explain how to add each expense in under a minute and see the total at the end." },
  { id: "productivity-492", title: "Track your shop stock in a simple spreadsheet", category: "productivity", text: "Help me make a simple spreadsheet to track my shop stock. Include columns for the item name, quantity left, supplier and price. Explain how to update it after each sale and spot which items need ordering soon." },
  { id: "productivity-493", title: "Use a spreadsheet to compare prices before buying", category: "productivity", text: "Help me use a spreadsheet to compare prices before buying [a new fridge]. Include columns for the shop name, model, price in ₹, warranty and delivery charge. Explain how to fill it in and pick the best deal." },
  { id: "productivity-494", title: "Track daily work hours in a spreadsheet", category: "productivity", text: "Help me make a simple spreadsheet to track my daily work hours. Include columns for the date, start time, end time and total hours. Explain how to fill it in each evening and add up the hours at the end of the week." },
  { id: "productivity-495", title: "Make a spreadsheet for your child's school fees", category: "productivity", text: "Help me make a simple spreadsheet to track my child's school fees. Include columns for the term, amount in ₹, due date and payment date. Explain how to mark each fee as paid and check at a glance what is still pending." },
  { id: "productivity-496", title: "Find the biggest expense in your spreadsheet", category: "productivity", text: "Show me how to find my biggest expense in a spreadsheet in one minute. Explain how to sort the amounts from largest to smallest, spot the top three expenses, and use that list to plan next month's spending." },
  { id: "productivity-497", title: "Track festival spending in a spreadsheet", category: "productivity", text: "Help me make a simple spreadsheet to track my festival spending for [Diwali]. Include columns for gifts, sweets, decorations, clothes and total in ₹. Explain how to fill it in daily and stay within my budget of [₹10,000]." },
  { id: "productivity-498", title: "Make a spreadsheet to track money lent to others", category: "productivity", text: "Help me make a simple spreadsheet to track money I have lent to friends and family. Include columns for the person's name, amount in ₹, date and return date. Explain how to update it when money comes back and keep the record clear." },
  { id: "productivity-499", title: "Track your monthly mobile and internet bills", category: "productivity", text: "Help me make a simple spreadsheet to track my mobile and internet bills each month. Include columns for the month, plan name, amount in ₹ and payment date. Explain how to spot a price rise and compare plans at renewal time." },
  { id: "productivity-500", title: "Print your spreadsheet neatly on one page", category: "productivity", text: "Show me how to print my spreadsheet neatly on one page. Explain how to set the page size, fit the columns, and check the preview before printing so nothing gets cut off at the edges." },
  { id: "productivity-501", title: "Add up totals automatically in a spreadsheet", category: "productivity", text: "Explain in simple words how to add up a column of numbers automatically in a spreadsheet. Show me the steps with an example of monthly expenses, and how to check that the total is correct before I trust it." },
  { id: "productivity-502", title: "Make a spreadsheet for a small savings goal", category: "productivity", text: "Help me make a simple spreadsheet for my savings goal of [₹50,000] for a new scooter. Include columns for the date, amount saved and total so far. Explain how to update it weekly and see how close I am to the goal." },
  { id: "productivity-503", title: "Share a spreadsheet with your family safely", category: "productivity", text: "Show me how to share a spreadsheet with my family so we can all see the same household budget. Explain how to share it safely, let others add their expenses, and stop anyone from deleting the whole sheet by mistake." },
  { id: "productivity-504", title: "Set a reminder for your monthly bill payments", category: "productivity", text: "Show me how to set a monthly reminder on my phone for paying bills. Explain how to pick the date, write a clear reminder message, and set it to repeat every month so I never miss a payment." },
  { id: "productivity-505", title: "Set an alarm for your morning school run", category: "productivity", text: "Help me set a reliable alarm on my phone for the morning school run. Explain how to pick the time, choose a loud sound, and set a second alarm five minutes later as a backup in case I sleep through the first." },
  { id: "productivity-506", title: "Set a reminder to call a customer back", category: "productivity", text: "Show me how to set a quick reminder to call a customer back after lunch. Explain how to add the person's name and number to the reminder, pick the right time, and mark it done after the call." },
  { id: "productivity-507", title: "Use reminders for birthdays and anniversaries", category: "productivity", text: "Help me set up reminders for family birthdays and anniversaries on my phone. Explain how to add each date once, set a reminder one week before, and add a note about the gift I plan to buy." },
  { id: "productivity-508", title: "Remind yourself to check stock every Monday", category: "productivity", text: "Show me how to set a weekly reminder to check my shop stock every Monday morning. Explain how to write a clear reminder, repeat it every week, and link it to my stock checklist so I do both together." },
  { id: "productivity-509", title: "Use a reminder app instead of sticky notes", category: "productivity", text: "Help me switch from paper sticky notes to a reminder app on my phone. Explain how to add my first ten reminders, set times for each one, and check the list each morning in under two minutes." },
  { id: "productivity-510", title: "Set a location reminder for the market", category: "productivity", text: "Explain in simple words how to set a reminder that pops up when I reach the market. Show me how to add the place, write the shopping list in the reminder, and turn the reminder off after I have bought everything." },
  { id: "productivity-511", title: "Set a reminder to pay your child's school fees", category: "productivity", text: "Show me how to set a reminder for my child's school fee due date. Explain how to add the amount in ₹, set the reminder three days before the due date, and mark it paid so the reminder stops." },
  { id: "productivity-512", title: "Use one reminder app for work and home", category: "productivity", text: "Help me use one reminder app for both work and home tasks. Explain how to make two simple lists inside the app, give each task a time, and check both lists once in the morning and once in the evening." },
  { id: "productivity-513", title: "Set a birthday reminder for a close friend", category: "productivity", text: "Show me how to set a birthday reminder for a close friend on my phone. Explain how to add the date, set the reminder for the morning of the birthday, and write a short message I can send in one tap." },
  { id: "productivity-514", title: "Set a monthly reminder to update your passbook", category: "productivity", text: "Show me how to set a monthly reminder to update my bank passbook. Explain how to pick a fixed date, add a note about which branch to visit, and tick the reminder off once the passbook is updated." },
  { id: "productivity-515", title: "Compare two reminder apps simply", category: "productivity", text: "Help me compare two reminder apps on my phone in simple words. Compare them on how easy they are to use, whether they work without internet, and whether they show reminders on time. Then suggest the better one for [a busy parent]." },
  { id: "productivity-516", title: "Turn a message into a reminder in seconds", category: "productivity", text: "Show me how to turn an important message into a reminder in seconds. Explain how to copy the key details, set the time, and add the sender's name so I remember why the reminder matters when it pops up." },
  { id: "productivity-517", title: "Back up your phone contacts safely", category: "productivity", text: "Show me how to back up all my phone contacts safely so I never lose a number. Explain the simple steps, how to check that the backup worked, and what to do when I buy a new phone." },
  { id: "productivity-518", title: "Back up your family photos every month", category: "productivity", text: "Help me back up my family photos every month so they are safe even if my phone breaks. Explain how to copy them to a computer or cloud storage, check that they copied fully, and keep the newest photos backed up too." },
  { id: "productivity-519", title: "Back up important documents on two places", category: "productivity", text: "Explain in simple words why I should keep important documents backed up in two places. Show me how to save copies of my Aadhaar, PAN and certificates on my phone and on a pen drive, and how to check both copies every six months." },
  { id: "productivity-520", title: "Set up automatic backup for your phone", category: "productivity", text: "Show me how to set up automatic backup for my phone so my photos and contacts save themselves. Explain the settings in plain words, how much free space I get, and what happens when the backup runs out of space." },
  { id: "productivity-521", title: "Back up your shop's sales records weekly", category: "productivity", text: "Help me back up my shop's sales records every week so a lost phone does not lose my business data. Explain how to copy the records to a computer, name the backup file by date, and check that the copy opens correctly." },
  { id: "productivity-522", title: "Save a backup of your WhatsApp chats", category: "productivity", text: "Show me how to save a backup of my WhatsApp chats and photos. Explain the simple steps, how often to back up, and how to restore the chats on a new phone without losing any messages." },
  { id: "productivity-523", title: "Keep a pen drive backup of important files", category: "productivity", text: "Help me keep a pen drive backup of my most important files. Explain which files to copy first, how to organise them on the pen drive, and how to update the backup once a month in under fifteen minutes." },
  { id: "productivity-524", title: "Back up your notes before changing phones", category: "productivity", text: "Show me how to back up all my notes before I change to a new phone. Explain how to check that every note is saved, move them to the new phone, and confirm that nothing is missing before I erase the old phone." },
  { id: "productivity-525", title: "Store a backup copy at a relative's home", category: "productivity", text: "Explain in simple words why keeping a backup copy at a relative's home is smart. Show me what to copy onto a pen drive, how to label it clearly, and how often to bring it home and update it." },
  { id: "productivity-526", title: "Check your backups actually work every month", category: "productivity", text: "Help me check every month that my backups actually work. Explain how to open one backed-up photo, one document and one contact from the backup, and what to do if any of them will not open." },
  { id: "productivity-527", title: "Back up your child's school certificates", category: "productivity", text: "Show me how to back up my child's school certificates safely. Explain how to scan or photograph each certificate clearly, save the copies in a folder by year, and keep a second copy on a pen drive." },
  { id: "productivity-528", title: "Back up your email inbox once a year", category: "productivity", text: "Help me back up my email inbox once a year so old bills and certificates are never lost. Explain how to download the important emails, save them in folders by year, and check that the attachments opened correctly." },
  { id: "productivity-529", title: "Choose between cloud backup and a pen drive", category: "productivity", text: "Help me choose between cloud backup and a pen drive for my important files. Compare them simply on cost, safety if my phone is lost, and ease of use. Then suggest which one suits [a small shop owner] best and why." },
  { id: "productivity-530", title: "Scan paper bills with your phone camera", category: "productivity", text: "Show me how to scan a paper bill clearly using my phone camera. Explain how to hold the phone steady, get good light, and check that all the numbers are readable before I throw the paper away." },
  { id: "productivity-531", title: "Store scanned bills by month and shop", category: "productivity", text: "Help me store my scanned bills in folders by month and shop name. Explain how to name each scan, move it to the right month folder, and find any bill in under a minute when I need it." },
  { id: "productivity-532", title: "Keep digital copies of warranty cards", category: "productivity", text: "Show me how to keep digital copies of warranty cards for my fridge, TV and mixer. Explain how to scan each card, save it with the purchase date in the file name, and find it quickly when something stops working." },
  { id: "productivity-533", title: "Scan old receipts before the ink fades", category: "productivity", text: "Help me scan my old paper receipts before the ink fades and they become unreadable. Give me a simple plan to scan a few each day, name them by shop and date, and store them safely on my phone." },
  { id: "productivity-534", title: "Keep a folder for rent and deposit receipts", category: "productivity", text: "Help me keep one folder for all my rent and deposit receipts. Explain how to scan each receipt when I pay, name it by month, and check at year end that every month has a receipt saved." },
  { id: "productivity-535", title: "Scan school fee receipts for safekeeping", category: "productivity", text: "Show me how to scan my child's school fee receipts and keep them safe. Explain how to photograph each receipt clearly, save it in a folder by school year, and find it quickly if the school asks for proof." },
  { id: "productivity-536", title: "Use your phone to scan a full A4 page", category: "productivity", text: "Explain in simple words how to scan a full A4 page, like a certificate, using my phone. Show me how to line up the page, avoid shadows, and save the scan as a clear file I can share or print." },
  { id: "productivity-537", title: "Make a simple receipt tracker with scanned bills", category: "productivity", text: "Help me make a simple receipt tracker using my scanned bills. Explain how to note the date, shop and amount in ₹ for each bill, and how to add up a month's spending from the tracker in a few minutes." },
  { id: "productivity-538", title: "Scan visiting cards and save the numbers", category: "productivity", text: "Show me how to scan visiting cards and save the phone numbers in my contacts. Explain how to photograph each card clearly, type the number once, and throw the paper card away only after checking the number is saved." },
  { id: "productivity-539", title: "Keep digital copies of your insurance papers", category: "productivity", text: "Help me keep digital copies of my insurance papers safe on my phone. Explain how to scan each policy, save it in a folder by year, and share it quickly with family if there is an emergency." },
  { id: "productivity-540", title: "Sort scanned bills into paid and pending", category: "productivity", text: "Show me how to sort my scanned bills into paid and pending folders. Explain how to move a bill to the paid folder after paying, check the pending folder every week, and spot any bill I have forgotten to pay." },
  { id: "productivity-541", title: "Scan and save old family documents safely", category: "productivity", text: "Help me scan and save old family documents, like birth certificates and old agreements, before the paper wears out. Explain how to scan them clearly, name each file, and keep a backup copy on a pen drive." },
  { id: "productivity-542", title: "Check a scanned bill is clear before deleting paper", category: "productivity", text: "Show me how to check that a scanned bill is clear before I throw away the paper copy. Explain what to look for: the shop name, date, amount in ₹ and GST number. Tell me when it is safe to delete the paper." },
  { id: "productivity-543", title: "Keep a password notebook safely at home", category: "productivity", text: "Show me how to keep a password notebook safely at home. Explain what to write for each account, how to hide the full password with a hint only I understand, and where to store the notebook so visitors never find it." },
  { id: "productivity-544", title: "Use a password app instead of memory", category: "productivity", text: "Help me switch from remembering passwords to using a password app on my phone. Explain the basic setup, how to save my first five passwords, and how to open an account using the app without typing the password." },
  { id: "productivity-545", title: "Make strong passwords you can still remember", category: "productivity", text: "Explain in simple words how to make a strong password I can still remember. Show me a method using three random words and a number, with examples for a bank app and an email account. Explain why I should never reuse one password." },
  { id: "productivity-546", title: "Change a password after sharing your phone", category: "productivity", text: "Show me how to change a password after I let someone use my phone. Explain which accounts to change first, how to pick a new strong password, and how to check that the old password no longer works." },
  { id: "productivity-547", title: "Store bank passwords separately from other passwords", category: "productivity", text: "Explain in simple words why bank passwords should be stored separately from other passwords. Show me a simple system: one notebook for bank accounts and one app for the rest, and how to keep both safe at home." },
  { id: "productivity-548", title: "Write passwords in code only you understand", category: "productivity", text: "Show me how to write my passwords in a notebook using a simple code only I understand. Explain how to replace a few letters with symbols, keep the code pattern in my head, and test that I can still read my own notes a week later." },
  { id: "productivity-549", title: "Keep a list of your accounts in one place", category: "productivity", text: "Help me make a simple list of all my accounts in one place: bank, email, shopping, school and government apps. Explain what to write for each account, how to note the recovery phone number, and how to update the list when I open a new account." },
  { id: "productivity-550", title: "Set up a password app with a master password", category: "productivity", text: "Show me how to set up a password app with one strong master password. Explain how to choose the master password, why I must never share it, and what to do if I forget it so I am not locked out of everything." },
  { id: "productivity-551", title: "Update old passwords once every six months", category: "productivity", text: "Help me update my old passwords once every six months. Explain which accounts to change first, how to pick new passwords I can remember, and how to record the changes in my password notebook without confusion." },
  { id: "productivity-552", title: "Share one password safely with your spouse", category: "productivity", text: "Explain in simple words how to share one important password safely with my spouse. Show me how to pass it in person, never by message, and how to change it if our phones are ever lost or stolen." },
  { id: "productivity-553", title: "Recover an account when you forgot the password", category: "productivity", text: "Help me recover my account when I have forgotten the password. Explain the simple steps: use the forgot password link, check my phone or email for the code, and set a new password I can remember this time." },
  { id: "productivity-554", title: "Keep your phone lock code separate from passwords", category: "productivity", text: "Explain in simple words why my phone lock code should be different from my bank and email passwords. Show me how to pick a lock code I remember, and what to do if someone watches me type it." },
  { id: "productivity-555", title: "Compare a password notebook and a password app", category: "productivity", text: "Help me compare a password notebook and a password app in simple words. Compare them on safety, finding a password quickly, and what happens if the notebook or phone is lost. Then suggest which one suits [an elderly parent] best and why." },
  { id: "productivity-556", title: "Add family birthdays to your calendar app", category: "productivity", text: "Show me how to add all my family birthdays to my calendar app. Explain how to add each date once, set it to repeat every year, and add a reminder one week before so I have time to buy a gift." },
  { id: "productivity-557", title: "Block time on your calendar for important work", category: "productivity", text: "Help me block time on my calendar app for important work, like billing and stock checking. Explain how to pick a fixed time each week, add it as a repeating event, and keep that time free from other plans." },
  { id: "productivity-558", title: "Share your calendar with your spouse simply", category: "productivity", text: "Show me how to share my calendar with my spouse so we both know the family plans. Explain how to share it safely, add events like school functions and doctor visits, and check the shared calendar each morning together." },
  { id: "productivity-559", title: "Add school holidays to your calendar", category: "productivity", text: "Help me add my child's school holidays to my calendar app. Explain how to add each holiday once, set a reminder the evening before, and use the calendar to plan family outings on those free days." },
  { id: "productivity-560", title: "Use colour labels for different calendar events", category: "productivity", text: "Show me how to use colour labels in my calendar app for different kinds of events. Explain which colour to use for work, school, family and money events, and how the colours help me see a busy day at a glance." },
  { id: "productivity-561", title: "Move a calendar event when plans change", category: "productivity", text: "Help me move a calendar event when my plans change. Explain how to change the date or time in a few taps, tell the other people about the change, and check that the old time is no longer booked." },
  { id: "productivity-562", title: "Set up a shared family calendar for the month", category: "productivity", text: "Help me set up a shared family calendar for the whole month. Explain how to add school events, work shifts, bill dates and festivals in one place, and how each family member can check it on their own phone." },
  { id: "productivity-563", title: "Add your weekly market day to the calendar", category: "productivity", text: "Show me how to add my weekly market day to my calendar app as a repeating event. Explain how to pick the day and time, add a short shopping note to the event, and set a reminder one hour before I leave." },
  { id: "productivity-564", title: "Use your calendar to spot a double booking", category: "productivity", text: "Show me how to use my calendar app to spot a double booking before it happens. Explain how to check one day's events, see two events at the same time, and move one of them to a free slot." },
  { id: "productivity-565", title: "Add reminders to calendar events easily", category: "productivity", text: "Explain in simple words how to add a reminder to a calendar event. Show me how to set a reminder one day before a bill date and one hour before a shop visit, and how to change the reminder time later." },
  { id: "productivity-566", title: "Keep work events and family events separate", category: "productivity", text: "Help me keep work events and family events separate in my calendar app. Explain how to make two calendars inside the app, give each one a colour, and switch between them when I want to see only work or only family plans." },
  { id: "productivity-567", title: "Sync your calendar between phone and computer", category: "productivity", text: "Show me how to sync my calendar between my phone and my computer so both show the same events. Explain the simple steps, how to check that a new event appears on both, and what to do if one device misses an event." },
  { id: "productivity-568", title: "Delete old calendar events to keep it tidy", category: "productivity", text: "Help me delete old calendar events to keep my calendar tidy. Explain which past events are safe to delete, how to delete one event or a whole repeating series, and how to keep important past events for records." },
  { id: "productivity-569", title: "Record a voice note when an idea strikes", category: "productivity", text: "Show me how to record a quick voice note on my phone when a good idea strikes. Explain how to open the recorder fast, speak clearly for under a minute, and name the note so I can find it later." },
  { id: "productivity-570", title: "Turn a voice note into a written list", category: "productivity", text: "Help me turn a voice note into a written list I can use. Explain how to listen once, write down the main points in short lines, and tick each point off when it is done. Use a simple example of a shopping list." },
  { id: "productivity-571", title: "Save a voice note with a clear name", category: "productivity", text: "Show me how to save a voice note with a clear name so I can find it later. Explain how to name it by topic and date, move it into the right folder, and delete old voice notes I no longer need." },
  { id: "productivity-572", title: "Use voice notes to remember a shop order", category: "productivity", text: "Help me use a voice note to remember a shop order a customer gives on the phone. Explain what to say in the note: the name, items, quantity and price. Show me how to check the note before I pack the order." },
  { id: "productivity-573", title: "Send a voice note instead of typing a long message", category: "productivity", text: "Explain in simple words when to send a voice note instead of typing a long message. Show me how to record it clearly, keep it under one minute, and check that the other person can hear it well." },
  { id: "productivity-574", title: "Keep a voice diary of your daily work", category: "productivity", text: "Help me keep a short voice diary of my daily work. Explain how to record two minutes each evening about what I finished and what is still pending, and how to listen back at the end of the week to check my progress." },
  { id: "productivity-575", title: "Share a voice note with your family group", category: "productivity", text: "Show me how to share a voice note with my family group so everyone hears the same message. Explain how to record it clearly, send it to the group, and check who has listened to it." },
  { id: "productivity-576", title: "Organise voice notes by topic and date", category: "productivity", text: "Help me organise my voice notes by topic and date so I can find them. Explain how to make folders for work, family and ideas, move each note to the right folder, and delete the ones I have already used." },
  { id: "productivity-577", title: "Turn a voice note into written text easily", category: "productivity", text: "Explain in simple words how to turn a voice note into written text on my phone. Show me the basic steps, how to fix any wrong words, and how to save the text in my notes app for later." },
  { id: "productivity-578", title: "Record a voice note for a future gift idea", category: "productivity", text: "Help me record a voice note when I think of a good gift idea for someone. Explain what to say: the person's name, the gift idea and the shop where I saw it. Show me how to find the note again before the birthday." },
  { id: "productivity-579", title: "Use voice notes during a market visit", category: "productivity", text: "Show me how to use voice notes during a market visit to remember prices. Explain how to record the shop name, item and price in ₹ quickly, and how to compare the notes at home before buying." },
  { id: "productivity-580", title: "Back up your voice notes every month", category: "productivity", text: "Help me back up my voice notes every month so they are safe if my phone is lost. Explain how to copy them to my computer, name the backup folder by month, and check that the notes play correctly after copying." },
  { id: "productivity-581", title: "Compare voice notes and written notes simply", category: "productivity", text: "Help me compare voice notes and written notes in simple words. Compare them on speed, finding an old note, and sharing with others. Then suggest which one suits [a shopkeeper who is always busy] best and why." },
  { id: "productivity-582", title: "Compare three simple to-do apps for beginners", category: "productivity", text: "Help me compare three simple to-do apps for beginners in plain words. Compare them on how easy they are to use, whether they work without internet, and whether they send reminders. Then suggest the best one for [a busy parent]." },
  { id: "productivity-583", title: "Set up your first to-do list in an app", category: "productivity", text: "Show me how to set up my first to-do list in a simple app. Explain how to add five tasks, give each one a date, and tick off a task when it is done. Keep the setup under ten minutes." },
  { id: "productivity-584", title: "Move your paper to-do list into an app", category: "productivity", text: "Help me move my paper to-do list into a to-do app on my phone. Explain how to add each task once, set the most urgent ones first, and throw the paper list away only after checking everything is in the app." },
  { id: "productivity-585", title: "Use a to-do app for your shop's daily tasks", category: "productivity", text: "Show me how to use a to-do app for my shop's daily tasks. Explain how to add tasks like ordering stock, calling suppliers and counting cash, set a time for each one, and check the list at closing time." },
  { id: "productivity-586", title: "Share a to-do list with your family", category: "productivity", text: "Help me share one to-do list with my family in a simple app. Explain how to add tasks for each person, let everyone tick off their own tasks, and check the list together in the evening to see what is left." },
  { id: "productivity-587", title: "Add repeating tasks to your to-do app", category: "productivity", text: "Show me how to add repeating tasks to my to-do app, like paying rent and watering plants. Explain how to set a task to repeat weekly or monthly, and how to change the repeat if my routine changes." },
  { id: "productivity-588", title: "Mark urgent tasks first in your to-do app", category: "productivity", text: "Help me mark urgent tasks first in my to-do app so I never miss a deadline. Explain how to use stars or colours for urgent tasks, sort the list by urgency, and move a task down when it is no longer urgent." },
  { id: "productivity-589", title: "Use a to-do app for school admission tasks", category: "productivity", text: "Help me use a to-do app to track my child's school admission tasks. Explain how to add tasks like collecting forms, submitting documents and paying fees, with a date for each one, and tick them off as they are done." },
  { id: "productivity-590", title: "Check your to-do list at the end of the day", category: "productivity", text: "Help me check my to-do list at the end of the day using my app. Explain how to see what is done, move unfinished tasks to tomorrow, and add any new tasks that came up during the day in under five minutes." },
  { id: "productivity-591", title: "Add a photo to a task in your to-do app", category: "productivity", text: "Show me how to add a photo to a task in my to-do app. Explain how to attach a photo of a bill, a broken item or a product, so I remember exactly what the task is about when I open it later." },
  { id: "productivity-592", title: "Use a to-do app without internet", category: "productivity", text: "Explain in simple words how to use a to-do app without internet. Show me how to add and tick off tasks offline, and how the app saves my changes and syncs them when the internet comes back." },
  { id: "productivity-593", title: "Keep a separate to-do list for money tasks", category: "productivity", text: "Help me keep a separate to-do list just for money tasks in my app. Explain how to add tasks like paying bills, checking the bank balance and collecting payments, and how to check this list every Friday." },
  { id: "productivity-594", title: "Choose between a to-do app and a paper list", category: "productivity", text: "Help me choose between a to-do app and a paper list for my daily tasks. Compare them simply on reminders, sharing with family, and finding old tasks. Then suggest which one suits [a small shop owner] best and why." },
  { id: "productivity-595", title: "Print a document from your phone easily", category: "productivity", text: "Show me how to print a document from my phone easily. Explain how to connect to a printer, pick the right file, and check the preview before printing so I do not waste paper on a wrong print." },
  { id: "productivity-596", title: "File important papers in labelled folders", category: "productivity", text: "Help me file my important papers in labelled folders at home. Explain how to make folders for money, school, health and property papers, label each one clearly, and put new papers in the right folder at once." },
  { id: "productivity-597", title: "Keep originals and photocopies in separate files", category: "productivity", text: "Explain in simple words why originals and photocopies should be kept in separate files. Show me how to label each file clearly, store the originals safely, and use photocopies for everyday needs like school forms." },
  { id: "productivity-598", title: "Print your child's school timetable for the fridge", category: "productivity", text: "Show me how to print my child's school timetable and stick it on the fridge. Explain how to make the print large and clear, add the timings for each subject, and update it when the school changes the timetable." },
  { id: "productivity-599", title: "Keep a box file for each school year", category: "productivity", text: "Help me keep one box file for each school year of my child's papers. Explain what to store inside: report cards, fee receipts and certificates, and how to label the box so I can find any year in seconds." },
  { id: "productivity-600", title: "Print both sides to save paper at home", category: "productivity", text: "Explain in simple words how to print on both sides of a paper to save money. Show me the setting to choose, how to check that the second side printed correctly, and when single-side printing is still better." },
  { id: "productivity-601", title: "Make a simple index for your home filing cabinet", category: "productivity", text: "Help me make a simple index for my home filing cabinet so I can find any paper fast. Explain how to list each folder on one page, number the folders, and update the index when I add a new folder." },
  { id: "productivity-602", title: "Store old papers safely from damp and insects", category: "productivity", text: "Show me how to store old papers safely at home so damp and insects do not damage them. Explain how to use plastic covers, keep them off the floor, and check the files once every six months for damage." },
  { id: "productivity-603", title: "Print a shopping list from your phone", category: "productivity", text: "Show me how to print a shopping list from my phone before going to the market. Explain how to make the list in my notes app, send it to the printer, and tick off items on the paper as I buy them." },
  { id: "productivity-604", title: "Start a simple work diary in a notebook", category: "productivity", text: "Help me start a simple work diary in a notebook. Explain what to write each evening: what I finished, what is pending, and any money I spent or received. Keep each entry short enough to write in five minutes." },
  { id: "productivity-605", title: "Record daily sales in your work diary", category: "productivity", text: "Show me how to record my daily shop sales in my work diary. Explain what to note: total cash, total UPI payments and the best-selling item. Show me how to use the notes at month end to see my best and worst days." },
  { id: "productivity-606", title: "Note customer feedback in your work diary", category: "productivity", text: "Help me note customer feedback in my work diary every day. Explain how to write down what customers liked, what they complained about, and one small change I can make tomorrow based on what they said." },
  { id: "productivity-607", title: "Track your work hours in a diary", category: "productivity", text: "Help me track my work hours in a diary without a spreadsheet. Explain how to note start and end times each day, add up the hours on Sunday, and use the total to plan my week ahead." },
  { id: "productivity-608", title: "Write a weekly summary in your work diary", category: "productivity", text: "Show me how to write a short weekly summary in my work diary every Sunday. Explain what to include: the best sale, the biggest problem, and one thing to improve next week. Keep it to half a page." },
  { id: "productivity-609", title: "Keep a diary of ideas for your business", category: "productivity", text: "Help me keep a diary of new ideas for my business. Explain how to write each idea in a few lines, note where the idea came from, and review the diary once a month to pick one idea to try." },
  { id: "productivity-610", title: "Record expenses in your work diary daily", category: "productivity", text: "Help me record my daily work expenses in my work diary. Explain how to note each expense with the amount in ₹, add them up each evening, and check at month end where the money went." },
  { id: "productivity-611", title: "Note down supplier prices in your work diary", category: "productivity", text: "Show me how to note supplier prices in my work diary so I can compare them later. Explain what to write for each supplier: the item, price in ₹ and date. Show me how to find the cheapest price when I need to order again." },
  { id: "productivity-612", title: "Keep a diary of lessons from mistakes at work", category: "productivity", text: "Help me keep a diary of lessons from mistakes at work. Explain how to write what went wrong in a few lines, what I will do differently next time, and how to read old lessons before starting a similar job." },
  { id: "productivity-613", title: "Track daily expenses in a simple sheet", category: "productivity", text: "Help me track my daily expenses in a simple sheet I can fill in every night. Include columns for the date, what I bought and the amount in ₹. Explain how to add each expense in one minute and see the weekly total." },
  { id: "productivity-614", title: "Split your expenses into needs and wants", category: "productivity", text: "Explain in simple words how to split my expenses into needs and wants in a sheet. Give me examples for each group, show me how to add up both totals, and explain what to do if the wants total is too high." },
  { id: "productivity-615", title: "Track cash and UPI spending separately", category: "productivity", text: "Help me track my cash and UPI spending separately in one sheet. Explain how to make two columns, note each payment in the right column, and compare the totals at the end of the week to see where my money goes." },
  { id: "productivity-616", title: "Find where your money leaks each month", category: "productivity", text: "Help me find where my money leaks each month using my expense sheet. Explain how to sort expenses by size, spot small daily spends that add up, and list three easy leaks I can fix this month." },
  { id: "productivity-617", title: "Keep a sheet for children's daily expenses", category: "productivity", text: "Help me keep a simple sheet for my child's daily expenses. Include columns for the date, item and amount in ₹. Explain how to fill it in each evening and add up the total at the end of the month." },
  { id: "productivity-618", title: "Compare this month's spending with last month", category: "productivity", text: "Show me how to compare this month's spending with last month using my expense sheet. Explain how to find both totals, see which group grew the most, and pick one group to spend less on next month." },
  { id: "productivity-619", title: "Set up a recurring reminder for rent day", category: "productivity", text: "Show me how to set up a recurring reminder for rent day on my phone. Explain how to pick the date, write a clear message with the amount in ₹, and set it to repeat every month so I never pay late." },
  { id: "productivity-620", title: "Use a template for your daily order message", category: "productivity", text: "Help me make a template for the daily order message I send to my supplier. Explain which parts stay the same every day, which parts change, and how to fill in the numbers quickly before sending it each morning." },
  { id: "productivity-621", title: "Auto-save photos from messages to one folder", category: "productivity", text: "Show me how to make my phone save photos from messages into one folder by itself. Explain the simple setting, how to check that new photos are saving, and how to turn it off if the folder gets too full." },
  { id: "productivity-622", title: "Set your phone to remind you every Monday", category: "productivity", text: "Help me set my phone to remind me every Monday about my weekly tasks. Explain how to write one clear reminder, set it to repeat every Monday morning, and change the tasks inside it when my routine changes." },
  { id: "productivity-623", title: "Use a template for your weekly stock order", category: "productivity", text: "Help me make a template for my weekly stock order message to my supplier. Explain which items stay the same, how to update the quantities each week, and how to save the template so I can send it in under a minute." },
  { id: "productivity-624", title: "Set up auto-backup for your notes app", category: "productivity", text: "Show me how to set up auto-backup for my notes app so my notes save themselves. Explain the simple setting, how to check that the backup is working, and what to do if the backup stops and my notes are at risk." },
  { id: "productivity-625", title: "Create a simple shortcut for your daily checklist", category: "productivity", text: "Help me create a simple shortcut on my phone for my daily checklist. Explain how to put the checklist on my home screen, open it with one tap each morning, and tick off tasks without opening any other app." },
  { id: "productivity-626", title: "Write a short clear email to a client", category: "productivity", text: "Draft a short, polite work email to [a client] about [the topic]. Keep it under 120 words, use a clear subject line, and put the main point in the first two lines. End with one clear next step and the date by which you need a reply." },
  { id: "productivity-627", title: "Ask a supplier for a revised price quote", category: "productivity", text: "Write a polite email to [a supplier] asking for a revised price quote for [the items] in [the quantity]. Mention the last price you paid, ask what has changed, and request the new quote by [a date]. Keep the tone friendly and businesslike." },
  { id: "productivity-628", title: "Confirm an order by email in simple words", category: "productivity", text: "Draft a short email to [a customer] confirming their order of [the items] for ₹[amount]. Include the delivery date, the payment already received, and one line asking them to reply if anything is wrong. Keep it warm, clear and easy to read." },
  { id: "productivity-629", title: "Write an email about a delayed delivery", category: "productivity", text: "Write a polite email to [a customer] explaining that their delivery of [the items] will arrive [number] days late because [the reason]. Apologise briefly, give the new date, and offer one useful option such as a partial delivery or a small discount." },
  { id: "productivity-630", title: "Introduce yourself to a new work contact", category: "productivity", text: "Draft a short introduction email to [a new work contact] explaining who you are, what your shop or office does, and why you are writing. Keep it friendly and brief, suggest one simple next step, and end with your phone number and the best time to call." },
  { id: "productivity-631", title: "Write a thank-you email after a meeting", category: "productivity", text: "Write a short thank-you email to [the person] after a meeting about [the topic]. Mention two points you agreed on, list the next steps with dates, and thank them for their time. Keep it under 100 words and use a clear subject line." },
  { id: "productivity-632", title: "Request a meeting with a busy manager", category: "productivity", text: "Draft a polite email asking [a manager] for a 20 minute meeting about [the topic]. Suggest two possible times, say what you need to decide, and list the three points you will cover so the meeting stays short. Keep the whole email under 100 words." },
  { id: "productivity-633", title: "Write an out-of-office email message", category: "productivity", text: "Write a clear out-of-office email message saying you are away from [the start date] to [the end date] and will reply after you return. Give the name and phone number of [a colleague] for urgent work, and keep the message short, polite and easy to understand." },
  { id: "productivity-634", title: "Follow up on an unpaid invoice politely", category: "productivity", text: "Write a polite follow-up email to [a customer] about invoice [number] for ₹[amount], due on [the date]. Remind them of the work already done, ask when they can pay, and offer your bank details again. Keep the tone firm but friendly and respectful." },
  { id: "productivity-635", title: "Write a short email to fix a mistake", category: "productivity", text: "Draft a short honest email to [a customer] admitting a mistake with [the order or service]. Say what went wrong in one line, explain how you will fix it, give the date it will be fixed, and offer a small goodwill gesture to keep their trust." },
  { id: "productivity-636", title: "Reply to an email in two minutes", category: "productivity", text: "Show me how to reply to this email in under two minutes: [paste the email]. Give me a short reply of three to four lines that answers the question, confirms the next step, and sounds polite. If any detail is missing, add one clear question at the end." },
  { id: "productivity-637", title: "Sort a full inbox in thirty minutes", category: "productivity", text: "Help me clear a full work inbox in 30 minutes. Give me a simple order to follow: which emails to answer first, which to file, and which to delete. Include a short reply template for common messages and a rule for emails that need more time." },
  { id: "productivity-638", title: "Reply to a rude email calmly", category: "productivity", text: "Draft a calm, professional reply to this angry email: [paste the email]. Do not argue or blame anyone. Acknowledge the problem, say what you will do to fix it, give a clear date, and invite the sender to call you if they want to talk further." },
  { id: "productivity-639", title: "Short replies for common work emails", category: "productivity", text: "Write five short reply templates I can reuse at work: one to confirm I received an email, one to say I will check and reply by a date, one to ask for more details, one to confirm a meeting time, and one to say thanks. Keep each reply under 30 words." },
  { id: "productivity-640", title: "Decide which emails need a reply today", category: "productivity", text: "Here are my unread work emails: [paste the list]. Sort them into three groups: reply today, reply this week, and no reply needed. For each email in the reply-today group, write one line saying what the reply should cover." },
  { id: "productivity-641", title: "Reply when you need more time", category: "productivity", text: "Draft a short reply to [a customer] saying I need two more days to answer their question about [the topic]. Thank them for their patience, explain briefly why more time is needed, and promise a reply by [a date]. Keep it polite and under 60 words." },
  { id: "productivity-642", title: "Turn a long email into a short reply", category: "productivity", text: "Read this long email and write a short reply of four lines: [paste the email]. The reply should confirm the main point, agree or disagree clearly, state the next step, and ask one question if anything is unclear. Use simple words and a polite tone throughout." },
  { id: "productivity-643", title: "Reply to many similar emails quickly", category: "productivity", text: "I get many emails asking the same question about [the topic]. Write one polite reply template I can reuse, with blanks for the name, date and price. Then list three small changes I can make so each reply still feels personal and not copied." },
  { id: "productivity-644", title: "Set up a simple email checking routine", category: "productivity", text: "Help me set up a simple routine for checking work emails three times a day without it taking over my work. Suggest the best times, a time limit for each check, and a rule for when to reply at once and when to save an email for later." },
  { id: "productivity-645", title: "Write a holding reply for a complaint", category: "productivity", text: "Draft a short holding reply to [a customer] who has complained about [the problem]. Acknowledge their message, say you are looking into it, give the date you will update them, and thank them for telling you. Keep it warm, honest and under 70 words." },
  { id: "productivity-646", title: "Plan a 20 minute team meeting", category: "productivity", text: "Plan a 20 minute team meeting about [the topic] for [number] people. Give me a simple minute-by-minute plan, one clear goal for the meeting, and three questions to ask the team. End with a short list of who does what after the meeting." },
  { id: "productivity-647", title: "Keep a meeting on time and on track", category: "productivity", text: "Give me five simple tricks to keep a work meeting on time and on track when people talk too long or go off topic. For each trick, give one polite sentence I can say in the meeting. Keep the advice practical for a small office team of [number] people." },
  { id: "productivity-648", title: "Start a meeting with a clear purpose", category: "productivity", text: "Write a short opening script for a meeting about [the topic] that I can read in one minute. It should state the purpose, the decision we need to make, the time we will finish, and one rule for keeping the discussion short and useful for everyone." },
  { id: "productivity-649", title: "End a meeting with clear next steps", category: "productivity", text: "Give me a simple closing script for a meeting about [the topic]. It should repeat the three decisions made, list who does what by which date, and confirm the date of the next check-in. Keep it short enough to read aloud in two minutes." },
  { id: "productivity-650", title: "Run a meeting when people disagree", category: "productivity", text: "Give me a step-by-step way to run a meeting where two team members disagree about [the topic]. Include what to say to calm the discussion, how to let both sides speak, and how to reach a decision in 15 minutes without anyone feeling ignored." },
  { id: "productivity-651", title: "Hold a quick meeting with a supplier", category: "productivity", text: "Plan a 15 minute meeting with [a supplier] about [the topic, e.g. prices or delivery]. List four questions to ask, two points I must not forget, and one line to close the meeting with a clear agreement and date. Keep the plan simple and practical." },
  { id: "productivity-652", title: "Decide if a meeting is really needed", category: "productivity", text: "Help me decide if a meeting about [the topic] is really needed. Give me five questions to ask first, and for each one, say what to do instead of a meeting if the answer is no, such as a short email, a phone call, or a shared note." },
  { id: "productivity-653", title: "Run a weekly team check-in meeting", category: "productivity", text: "Plan a 30 minute weekly team check-in for [number] people in [a small shop or office]. Include a round where each person shares one win, one problem and one plan for the week. End with a short list of tasks and who owns each one." },
  { id: "productivity-654", title: "Invite people to a meeting politely", category: "productivity", text: "Write a short meeting invite message for a meeting about [the topic] on [the date] at [the time] in [the place]. State the purpose in one line, list the two things people should bring or prepare, and ask them to confirm if they can attend." },
  { id: "productivity-655", title: "Take charge of a meeting as a junior", category: "productivity", text: "I am the youngest person in my office and I must lead a meeting about [the topic]. Give me a simple plan to prepare, five polite phrases to guide the discussion, and tips to handle questions I cannot answer on the spot without losing the room." },
  { id: "productivity-656", title: "Write a simple meeting agenda", category: "productivity", text: "Write a simple agenda for a 30 minute meeting about [the topic] with [number] people. List four items in order, give each item a time limit, and add one line at the end for any other business. Keep the agenda on one page and easy to read." },
  { id: "productivity-657", title: "Turn messy meeting notes into action points", category: "productivity", text: "Here are my messy notes from a meeting about [the topic]: [paste the notes]. Turn them into a clean list of decisions made, action points with the name of the person responsible, and the date each action is due. Keep the whole list short and clear." },
  { id: "productivity-658", title: "Write minutes for a small office meeting", category: "productivity", text: "Write simple minutes for a meeting held on [the date] about [the topic], attended by [the names]. Include the decisions made, the tasks agreed with dates, and any points left open for the next meeting. Use short bullet points and plain words." },
  { id: "productivity-659", title: "Share meeting notes with the whole team", category: "productivity", text: "Write a short message to share meeting notes about [the topic] with the whole team on [WhatsApp or email]. Summarise the three main decisions in simple words, list the tasks with names and dates, and ask everyone to reply if anything is wrong or missing." },
  { id: "productivity-660", title: "Prepare an agenda for a client meeting", category: "productivity", text: "Prepare an agenda for a one hour meeting with [a client] about [the topic]. List five items in order, with the time for each, and add a short note under each item saying what we need to decide. End with space for the client's own points." },
  { id: "productivity-661", title: "Note down decisions during a meeting", category: "productivity", text: "Give me a simple one-page template for noting decisions during a meeting. It should have space for the date, the people present, each decision, who is responsible, and the due date. Add one tip for filling it in quickly while the meeting is still going on." },
  { id: "productivity-662", title: "Follow up on last meeting's action points", category: "productivity", text: "Write a short message to the team checking progress on the action points from our last meeting about [the topic]. List the three tasks with their due dates, ask each person for a one-line update, and remind everyone of the next meeting date." },
  { id: "productivity-663", title: "Write an agenda for a vendor meeting", category: "productivity", text: "Write an agenda for a 30 minute meeting with [a vendor] about [prices, delivery or quality]. List four items to discuss, the time for each, and one question to ask under each item. End with a line to agree the next order date before we finish." },
  { id: "productivity-664", title: "Summarise a long meeting in five lines", category: "productivity", text: "Here are my notes from a long meeting about [the topic]: [paste the notes]. Summarise the whole meeting in five short lines: what was decided, what is still open, and who does what next. Use plain words so anyone in the team can understand it." },
  { id: "productivity-665", title: "Prepare notes before a meeting with your manager", category: "productivity", text: "Help me prepare short notes for a meeting with my manager about [the topic]. List the three points I want to raise, the facts or numbers to support each one, and the one decision I need from the meeting. Keep the notes on one page." },
  { id: "productivity-666", title: "Write a simple monthly sales report", category: "productivity", text: "Help me write a simple monthly sales report for [the month] for [a small shop]. Include total sales, the best-selling items, the slowest items, and three short points on what to do next month. Use simple tables and plain words a non-expert can follow." },
  { id: "productivity-667", title: "Write a short weekly work report", category: "productivity", text: "Write a short weekly work report for the week of [the dates]. List the work finished, the work still in progress, any problems faced, and the plan for next week. Keep it to one page, use bullet points, and write in simple, clear language." },
  { id: "productivity-668", title: "Turn raw numbers into a simple report", category: "productivity", text: "Here are my raw sales numbers for [the month]: [paste the numbers]. Turn them into a short report with a one-line summary, a small table of the main figures, and three simple observations about what went well and what needs attention next month." },
  { id: "productivity-669", title: "Write a report on a customer complaint", category: "productivity", text: "Write a short report about a customer complaint on [the date] regarding [the problem]. Include what happened, what the customer asked for, what we did to fix it, and two steps to stop it happening again. Keep it factual and under 200 words." },
  { id: "productivity-670", title: "Make a simple stock report for a shop", category: "productivity", text: "Help me make a simple stock report for [a small shop] for [the month]. List the items running low, the items with too much stock, and the items that did not sell at all. Add a short note on what to order next and what to stop ordering." },
  { id: "productivity-671", title: "Write a report after a site visit", category: "productivity", text: "Write a short report after a site visit to [the place] on [the date]. Cover what you saw, the condition of the place, the people you met, and the three main problems found. End with your recommendation and the next step with a date." },
  { id: "productivity-672", title: "Write a one-page project status report", category: "productivity", text: "Write a one-page status report for [the project] as of [the date]. Include what is done, what is in progress, what is delayed and why, and the next three steps with dates. Use a simple traffic-light style: green for on track, amber for at risk, red for delayed." },
  { id: "productivity-673", title: "Compare two suppliers in a short report", category: "productivity", text: "Write a short report comparing [supplier A] and [supplier B] for [the items]. Compare price, quality, delivery time and payment terms in a simple table, then give a clear recommendation on which supplier to choose and why, in two short paragraphs." },
  { id: "productivity-674", title: "Write a report on staff attendance", category: "productivity", text: "Help me write a simple monthly attendance report for [number] staff members in [a small office]. Show who was present, who took leave, and who was often late, in a small table. Add two lines on what to discuss with anyone whose attendance needs attention." },
  { id: "productivity-675", title: "Write a handover report for a finished project", category: "productivity", text: "Write a short handover report for [the project] that is now finished. List what was done, the documents and passwords handed over, the people to contact for help, and two things the next person should watch out for. Keep it clear and practical." },
  { id: "productivity-676", title: "Plan a simple 10 slide presentation", category: "productivity", text: "Plan a simple 10 slide presentation about [the topic] for [the audience]. Give me the title of each slide, one line saying what goes on it, and a tip for keeping the slides clean and easy to read. Keep the whole talk under 15 minutes." },
  { id: "productivity-677", title: "Write speaker notes for a presentation", category: "productivity", text: "Write short speaker notes for my presentation about [the topic] that I can read in [number] minutes. Give me one or two lines to say for each slide, plus a simple opening line and a strong closing line. Use plain words I can speak naturally." },
  { id: "productivity-678", title: "Present monthly sales to your team simply", category: "productivity", text: "Help me present last month's sales to my team of [number] people in 10 minutes. Give me five slides: the total, the best sellers, the weak spots, the main lesson, and the plan for this month. Add one simple chart idea for each slide." },
  { id: "productivity-679", title: "Turn a long report into slides", category: "productivity", text: "Here is a long report about [the topic]: [paste the report]. Turn it into eight simple slides, each with a short heading and no more than three bullet points. Add a one-line summary slide at the end and suggest one chart to include." },
  { id: "productivity-680", title: "Pitch a new idea to your manager", category: "productivity", text: "Help me pitch a new idea to my manager: [describe the idea]. Write a short five-slide plan: the problem, the idea, the cost, the benefit, and what I need from them. Add one polite line to open the talk and one line to ask for their decision." },
  { id: "productivity-681", title: "Make slides that are easy to read", category: "productivity", text: "Give me ten simple rules for making slides that are easy to read in a small office meeting. Cover font size, colours, how many words per slide, pictures, and charts. For each rule, give one example of a good slide and one common mistake to avoid." },
  { id: "productivity-682", title: "Present a new product to customers", category: "productivity", text: "Plan a short presentation to show [a new product] to [the customers] in [a shop or office]. Give me six slides: what it is, who it is for, the price, how it works, why it is better, and how to buy it. Add one line to invite questions at the end." },
  { id: "productivity-683", title: "Practise a presentation in 30 minutes", category: "productivity", text: "Help me practise a [number] minute presentation about [the topic] in 30 minutes. Give me a timed practise plan: what to do in the first 10 minutes, the next 10, and the last 10. Include a short checklist to test myself before the real talk." },
  { id: "productivity-684", title: "Answer tough questions after a presentation", category: "productivity", text: "Give me five polite ways to answer tough questions after a presentation about [the topic]. Include what to say when I do not know the answer, when someone disagrees, and when a question is off topic. Add one line to bring the discussion back on track." },
  { id: "productivity-685", title: "Present a training session for new staff", category: "productivity", text: "Plan a one hour training presentation for [number] new staff about [the topic]. Give me eight slides with a short heading and two bullet points each, plus one simple activity to keep the new staff involved and one question to check they understood." },
  { id: "productivity-686", title: "Divide a big task among four people", category: "productivity", text: "Help me divide this big task among four people: [describe the task]. Split it into four clear parts, match each part to a person's skill, and give a deadline for each part. Add one line on how to check progress without disturbing everyone daily." },
  { id: "productivity-687", title: "Share work fairly in a small team", category: "productivity", text: "Give me a simple way to share work fairly among [number] people in [a small shop or office]. List each person's main skill, suggest who takes which task, and add a rule for swapping tasks when someone is on leave or very busy that week." },
  { id: "productivity-688", title: "Write a task list for a team project", category: "productivity", text: "Write a clear task list for our team project: [describe the project]. Break it into ten small tasks, give each task an owner and a due date, and mark which tasks must finish first before others can start. Keep the list on one page." },
  { id: "productivity-689", title: "Assign tasks based on each person's strength", category: "productivity", text: "Here are my team members and their strengths: [paste the list]. Assign the tasks for [the project] so each person does what they are best at. Explain your choice in one line per person and suggest one task each person can learn from." },
  { id: "productivity-690", title: "Handle a team member who misses deadlines", category: "productivity", text: "Give me a calm, practical plan to handle a team member who keeps missing deadlines on [the task]. Include what to say in a private talk, how to find out the real reason, and three changes to the work plan that make the next deadline easier to meet." },
  { id: "productivity-691", title: "Plan a team effort for a festival sale", category: "productivity", text: "Plan how our team of [number] people will run a festival sale at [a shop] during [the festival]. Divide the work into stalls, billing, stock and customer help, give each person a role, and add a simple daily schedule for the sale week." },
  { id: "productivity-692", title: "Split work between office and field staff", category: "productivity", text: "Help me split the work for [the project] between office staff and field staff. List which tasks stay in the office, which go to the field, and who must share updates with whom and how often. Add one rule to avoid the same work being done twice." },
  { id: "productivity-693", title: "Make a duty roster for a small shop", category: "productivity", text: "Make a simple weekly duty roster for [number] staff at [a small shop]. Cover opening, billing, stock, cleaning and closing for each day, give everyone one day off, and keep the hours fair. Show it as a small table I can print and pin on the wall." },
  { id: "productivity-694", title: "Divide work for a last-minute order", category: "productivity", text: "We have a last-minute order for [the items] that must be ready by [the date]. Divide the work among [number] people with clear tasks and times, and add a short checklist to check quality before packing. Keep the plan simple enough to explain in five minutes." },
  { id: "productivity-695", title: "Write a team agreement on who does what", category: "productivity", text: "Write a short team agreement for [number] people working on [the project]. State who handles each part, the deadline for each part, and how we will share updates. Keep it to half a page, use simple words, and end with a line everyone can agree to." },
  { id: "productivity-696", title: "Follow up with a team member politely", category: "productivity", text: "Write a polite follow-up message to [a team member] about [the task] that was due on [the date]. Ask for a short update, offer help if they are stuck, and suggest a new date if needed. Keep the message friendly and under 60 words so it does not feel like pressure." },
  { id: "productivity-697", title: "Share a weekly update with your manager", category: "productivity", text: "Write a short weekly update to my manager about [the project]. Cover what I finished, what is still in progress, one problem I faced, and what I plan next week. Keep it to four short paragraphs and use bullet points so it is easy to scan." },
  { id: "productivity-698", title: "Chase a reply from a client gently", category: "productivity", text: "Write a gentle follow-up message to [a client] who has not replied to my email about [the topic] sent on [the date]. Remind them of the one thing I need, give a simple reason it matters now, and ask for a reply by [a date]. Keep it polite and short." },
  { id: "productivity-699", title: "Give a progress update in three lines", category: "productivity", text: "Help me write a three-line progress update about [the project] for our team group. Line one: what is done. Line two: what is stuck and why. Line three: what happens next and by when. Keep each line short and use simple words." },
  { id: "productivity-700", title: "Remind the team about a deadline", category: "productivity", text: "Write a short reminder message to the team that [the task] is due on [the date]. List the three things that must be finished, name who is responsible for each one, and ask everyone to confirm they are on track. Keep the tone encouraging, not scolding." },
  { id: "productivity-701", title: "Share good news with the team", category: "productivity", text: "Write a short happy message to the team sharing that [the good news, e.g. we won an order]. Thank the people who helped, mention what went well, and add one line about what we will do next. Keep it warm, short and easy to share in the team group." },
  { id: "productivity-702", title: "Ask a colleague for a status update", category: "productivity", text: "Write a polite message asking [a colleague] for a status update on [the task]. Say why I need the update, give the date I need it by, and offer to help if something is blocking them. Keep it short and friendly so it does not sound like I am checking up on them." },
  { id: "productivity-703", title: "Update a client when work is delayed", category: "productivity", text: "Write a short update to [a client] saying the work on [the project] will be delayed by [number] days because [the reason]. Apologise briefly, give the new date, explain what we are doing to catch up, and thank them for their patience and understanding." },
  { id: "productivity-704", title: "Send a daily update to a small team", category: "productivity", text: "Give me a simple daily update format for a team of [number] people working on [the project]. Each person writes three lines: done today, plan for tomorrow, and any help needed. Add one rule to keep updates short and a time by which everyone must send theirs." },
  { id: "productivity-705", title: "Follow up after sending a quotation", category: "productivity", text: "Write a polite follow-up message to [a customer] after sending them a quotation of ₹[amount] for [the items] on [the date]. Ask if they have any questions, mention one benefit of choosing us, and ask when they plan to decide. Keep it short and friendly." },
  { id: "productivity-706", title: "Set up a work-from-home routine", category: "productivity", text: "Help me set up a simple work-from-home routine for [number] hours a day. Suggest a start time, two break times, and a finish time, plus one rule for keeping work and home separate. Add a short checklist to prepare the night before each workday." },
  { id: "productivity-707", title: "Work from home with small children around", category: "productivity", text: "Give me a practical plan to work from home with small children around. Suggest the best hours to do deep work, simple activities to keep the children busy, and a signal the family understands when I must not be disturbed. Keep the plan kind and realistic." },
  { id: "productivity-708", title: "Stay in touch with your team remotely", category: "productivity", text: "Give me a simple plan to stay in touch with my team while working from home. Suggest one daily check-in, one weekly call, and a shared place for updates. Add one tip for making remote chats feel friendly and one rule for urgent messages." },
  { id: "productivity-709", title: "Manage remote work across two cities", category: "productivity", text: "Help me manage a small team working remotely across [two cities]. Suggest how to share tasks, how often to meet online, and how to track who is doing what. Add one rule for handling time differences and one way to celebrate small wins together." },
  { id: "productivity-710", title: "Set work hours when working from home", category: "productivity", text: "Help me set clear work hours for working from home in [a small flat] with family around. Suggest a start and finish time, two break times, and a simple way to tell the family I am at work. Add one rule for after-hours messages from the office." },
  { id: "productivity-711", title: "Handle internet problems during remote work", category: "productivity", text: "Give me a practical backup plan for internet problems during work from home in [your area]. List what to do first when the connection drops, how to tell the team quickly, and three low-data ways to keep working until the internet is back." },
  { id: "productivity-712", title: "Keep remote team members feeling included", category: "productivity", text: "Give me five simple ways to keep remote team members feeling included in a team where some people work in the office and some from home. For each way, give one example I can try this week with a team of [number] people." },
  { id: "productivity-713", title: "Share files with a remote team easily", category: "productivity", text: "Explain in simple words how to share files with a remote team of [number] people without confusion. Cover naming files clearly, keeping one latest version, and who can edit what. Add a short checklist for sharing a file for the first time." },
  { id: "productivity-714", title: "Work from home during a power cut", category: "productivity", text: "Give me a simple plan for working from home during a power cut in [your city]. List what to charge the night before, how to keep working on a phone, and what to tell the team. Add one tip for staying cool in summer without a fan." },
  { id: "productivity-715", title: "Switch between office days and home days", category: "productivity", text: "Help me plan a week that mixes office days and work-from-home days. Suggest which tasks suit the office and which suit home, a simple packing list for office days, and one routine to start each home day well. Keep the plan easy to follow." },
  { id: "productivity-716", title: "Share a small home office with your partner", category: "productivity", text: "My partner and I both work from home in one small room in [your city]. Help us share the space without disturbing each other. Suggest where to place two desks, how to split quiet hours and calls, storage for two people's files, and three low-cost items that keep the room calm and tidy for both of us." },
  { id: "productivity-717", title: "Choose a good chair for long work hours", category: "productivity", text: "Help me choose a good chair for working [number] hours a day at home on a budget of ₹[amount]. List the four features that matter most, three mistakes to avoid, and two simple checks I can do in the shop before buying." },
  { id: "productivity-718", title: "Organise a small work desk at home", category: "productivity", text: "Give me a simple plan to organise a small work desk at home. List what to keep on the desk, what to store in a drawer, and what to remove completely. Add a five-minute daily tidy routine and one idea for keeping cables neat and safe." },
  { id: "productivity-719", title: "Improve lighting for a home office", category: "productivity", text: "Help me improve the lighting in my home office corner in [a small room]. Suggest the best place for the desk, one affordable lamp to buy, and two free changes I can make today. Add one tip to reduce eye strain during long screen hours." },
  { id: "productivity-720", title: "Set up a home office on a low budget", category: "productivity", text: "Help me set up a home office corner on a budget of ₹[amount]. List the must-buy items in order of importance, what I can reuse from home, and what to skip for now. Add a simple shopping list with rough prices for each item." },
  { id: "productivity-721", title: "Keep a home office quiet for calls", category: "productivity", text: "Give me five practical ways to keep a home office corner quiet for video calls when family members are at home. For each way, give one low-cost idea and one free idea, and add a simple sign I can put on the door during important calls." },
  { id: "productivity-722", title: "Store office papers at home neatly", category: "productivity", text: "Give me a simple system to store office papers at home without a big cupboard. Suggest three types of folders, what goes in each one, and a weekly routine to file new papers. Add one tip for finding any paper in under a minute." },
  { id: "productivity-723", title: "Make a home office corner for two people", category: "productivity", text: "Help me set up a home office corner for two people sharing one room in [a small flat]. Suggest how to split the space, two ways to reduce noise, and a simple timetable so both can take calls without disturbing each other. Keep the cost low." },
  { id: "productivity-724", title: "Add plants to a home office corner", category: "productivity", text: "Suggest five easy indoor plants for a home office corner with little sunlight in [your city]. For each plant, say how often to water it, where to place it, and one benefit for the workspace. Add one tip for keeping plants alive during a long holiday." },
  { id: "productivity-725", title: "Keep work and home separate in one room", category: "productivity", text: "Give me five simple tricks to keep work and home separate when my office corner is in the same room as my bedroom. Cover a start-of-day routine, an end-of-day routine, and one physical change to the room that signals work is over." },
  { id: "productivity-726", title: "Prepare for a video call in five minutes", category: "productivity", text: "Give me a five-minute checklist to prepare for a video call about [the topic]. Cover camera, sound, lighting, background, and the notes I need. Add one tip for what to do if the internet drops in the middle of the call." },
  { id: "productivity-727", title: "Look and sound good on video calls", category: "productivity", text: "Give me ten simple tips to look and sound good on video calls from home. Cover where to sit, where to look, how to speak clearly, and what to wear. Keep the tips free or low cost, and add one common mistake beginners make on video calls." },
  { id: "productivity-728", title: "Handle background noise on a video call", category: "productivity", text: "Give me five practical ways to handle background noise during a video call from home in [your area]. Include what to say when noise starts, how to mute quickly, and three free fixes for a noisy room. Add one line to apologise politely if the noise disturbs others." },
  { id: "productivity-729", title: "Run a video call with ten people", category: "productivity", text: "Plan a 30 minute video call with ten people about [the topic]. Give me a simple order: who speaks first, how to take questions without chaos, and how to share the screen. End with a short list of who does what after the call." },
  { id: "productivity-730", title: "Introduce yourself on a first video call", category: "productivity", text: "Write a short script to introduce myself on a first video call with [a client or new team]. Keep it under one minute: my name, my role, what I do, and one friendly line to open the conversation. Add two questions I can ask to keep the talk going." },
  { id: "productivity-731", title: "Take notes during a video call", category: "productivity", text: "Give me a simple method to take notes during a video call about [the topic] without missing what people say. Suggest a one-page layout, three short codes for decisions and tasks, and a five-minute routine after the call to clean up the notes." },
  { id: "productivity-732", title: "Fix common video call problems quickly", category: "productivity", text: "List the five most common video call problems, no sound, frozen picture, echo, dark screen and dropped call, and give a quick fix for each one that a beginner can try in under a minute. Add one tip to test everything before an important call." },
  { id: "productivity-733", title: "Set video call rules for your team", category: "productivity", text: "Write a short list of video call rules for a team of [number] people working from different places. Cover joining on time, muting when not speaking, camera use, and what to do if someone drops off. Keep the rules friendly and easy to follow." },
  { id: "productivity-734", title: "Present your screen on a video call", category: "productivity", text: "Explain in simple steps how to present my screen on a video call to show [the document or slides]. Cover how to share, how to stop sharing, and what to close before the call so private messages do not appear. Add one tip if the screen looks blurry." },
  { id: "productivity-735", title: "End a video call politely and clearly", category: "productivity", text: "Give me a short closing script for a video call about [the topic]. It should thank everyone, repeat the two main decisions, list who does what by which date, and confirm the next call. Keep it under one minute and easy to read aloud." },
  { id: "productivity-736", title: "Refuse an extra task from your manager", category: "productivity", text: "Write a polite reply to my manager saying I cannot take on [the extra task] this week because my plate is already full with [the current work]. Offer one helpful alternative, such as doing it next week or helping someone else start it. Keep it respectful and short." },
  { id: "productivity-737", title: "Decline a meeting you do not need", category: "productivity", text: "Write a polite message declining a meeting about [the topic] on [the date] because it does not need my input. Suggest who can attend instead, offer to read the notes after, and add one line offering help if they really need me there." },
  { id: "productivity-738", title: "Say no to a customer request politely", category: "productivity", text: "Write a polite message to [a customer] saying no to their request for [the thing] because [the reason]. Offer two alternatives we can do instead, keep the tone warm and helpful, and end by asking which alternative they would like to choose." },
  { id: "productivity-739", title: "Refuse extra work without upsetting anyone", category: "productivity", text: "Give me five polite sentences I can use to refuse extra work at the office without upsetting anyone. For each sentence, say when to use it, with a manager, a colleague, or a customer, and add one tip for staying calm while saying no." },
  { id: "productivity-740", title: "Say no to working on a Sunday", category: "productivity", text: "Write a polite message to [a manager or client] saying I cannot work on [Sunday, the date] because it is my weekly off. Offer to finish the urgent part on Saturday or first thing Monday, and keep the message short, respectful and firm without sounding rude." },
  { id: "productivity-741", title: "Decline a last-minute task at work", category: "productivity", text: "Write a short message declining a last-minute task from [a colleague] because I am finishing [the urgent work] due today. Suggest a realistic time I can help, offer one small part I can do now, and keep the tone friendly and team-minded." },
  { id: "productivity-742", title: "Say no to a discount request politely", category: "productivity", text: "Write a polite reply to [a customer] asking for a discount on [the items] priced at ₹[amount]. Explain in simple words why the price is fair, mention the quality or service included, and offer one small extra instead of a price cut. Keep it warm and firm." },
  { id: "productivity-743", title: "Turn down extra duties after office hours", category: "productivity", text: "Give me a simple script to turn down extra duties after office hours when [a manager] asks. Include one line stating my boundary clearly, one line offering a time tomorrow, and one line thanking them for understanding. Keep it polite and under 60 words." },
  { id: "productivity-744", title: "Say no to a colleague asking for help", category: "productivity", text: "Write a polite message to [a colleague] saying I cannot help with [the task] today because I have my own deadline. Offer to help tomorrow after [the time], suggest one other person who could help now, and keep the message kind and short." },
  { id: "productivity-745", title: "Decline a job offer politely by email", category: "productivity", text: "Write a polite email declining a job offer from [the company] for [the role] because [the reason]. Thank them for the offer, say one nice thing about the company, and leave the door open for the future. Keep it short, warm and professional." },
  { id: "productivity-746", title: "Plan a week with too much work", category: "productivity", text: "Help me plan a week when I have too much work: [list the tasks]. Sort the tasks into must-do, should-do and can-wait, give each one a day, and add two short breaks a day. End with one line on what to tell my manager about the load." },
  { id: "productivity-747", title: "Prioritise ten tasks before a deadline", category: "productivity", text: "Here are ten tasks I must finish before [the date]: [paste the list]. Put them in order of importance, say which three to do first, which two to ask for help with, and which one can be dropped or delayed. Give one line of reason for each choice." },
  { id: "productivity-748", title: "Ask for help when work piles up", category: "productivity", text: "Write a short message to my manager saying my workload has become too much this week because [the reason]. List the three biggest tasks, ask which one can move to next week, and offer one task a colleague could take. Keep it honest and calm." },
  { id: "productivity-749", title: "Handle a sudden urgent task at work", category: "productivity", text: "Give me a step-by-step plan for handling a sudden urgent task that lands when I am already busy with [the current work]. Include how to pause the current work safely, how to tell the team, and how to pick up the old work again afterwards." },
  { id: "productivity-750", title: "Finish a busy day without working late", category: "productivity", text: "Help me finish a busy day without working late. Here is my task list: [paste the list]. Pick the three tasks that must finish today, move the rest to tomorrow with times, and add a short end-of-day routine to close the day cleanly." },
  { id: "productivity-751", title: "Deal with two managers giving different work", category: "productivity", text: "Give me a practical plan for dealing with two managers who both give me urgent work on the same day. Include what to say to each one, how to show them the clash clearly, and how to agree on which task comes first without upsetting either of them." },
  { id: "productivity-752", title: "Work through a heavy month step by step", category: "productivity", text: "Help me plan a heavy month at work in [the month] with [the big tasks]. Break the month into four weekly goals, give each week one main task, and add a simple check at the end of each week. Keep the plan realistic for one person." },
  { id: "productivity-753", title: "Take a proper lunch break on busy days", category: "productivity", text: "Give me a simple plan to take a proper 30 minute lunch break even on the busiest days at [a small office]. Suggest the best time, what to eat for energy, and three things to avoid during the break so I return to work fresh and focused." },
  { id: "productivity-754", title: "Stop work piling up every Monday", category: "productivity", text: "Give me a simple Friday routine that stops work piling up every Monday at [a small office]. Include five things to finish on Friday, three things to prepare for Monday, and one short note to write to myself so Monday starts calmly and clearly." },
  { id: "productivity-755", title: "Share a heavy workload with your team", category: "productivity", text: "Write a short message to my team asking them to share a heavy workload this week on [the project]. List the tasks, suggest who could take each one, and thank them in advance. Keep the message honest, fair and encouraging, not demanding." },
  { id: "productivity-756", title: "Ask your manager for more time politely", category: "productivity", text: "Write a polite message to my manager asking for [number] more days to finish [the task] because [the reason]. Show what is already done, give the new date I can deliver, and offer one part I can send early. Keep the message short and honest." },
  { id: "productivity-757", title: "Explain a delay to your manager clearly", category: "productivity", text: "Write a short message explaining to my manager why [the task] will be late by [number] days. State the reason in one line, say what I have already finished, give the new delivery date, and add one step I am taking to avoid the same delay next time." },
  { id: "productivity-758", title: "Ask a client for a deadline extension", category: "productivity", text: "Write a polite email to [a client] asking to move the deadline for [the work] from [the old date] to [the new date] because [the reason]. Mention the progress so far, offer one part early if possible, and thank them for their understanding." },
  { id: "productivity-759", title: "Negotiate a realistic deadline with your manager", category: "productivity", text: "Give me a simple script to negotiate a realistic deadline with my manager for [the task]. Include how to show the work involved, how to suggest a fair date, and what to say if they insist on the original date. Keep the tone respectful and practical." },
  { id: "productivity-760", title: "Ask for an extension on a team project", category: "productivity", text: "Write a short message to the team asking for [number] extra days to finish our part of [the project] because [the reason]. List what is done, what is left, and the new date we can deliver. Ask the team to confirm the new plan works for everyone." },
  { id: "productivity-761", title: "Apologise for missing a deadline at work", category: "productivity", text: "Write a short honest apology to [a manager or client] for missing the deadline on [the task] by [number] days. Say what caused the delay, what is done now, and the exact date the work will be finished. Keep it sincere, brief and free of excuses." },
  { id: "productivity-762", title: "Ask for an extension before the deadline passes", category: "productivity", text: "Write a short message asking for an extension on [the task] before the deadline passes. Explain the problem early, suggest a new date, and show the work already done. Add one line offering to send a first draft now so the manager can see the progress." },
  { id: "productivity-763", title: "Explain a supplier delay to your manager", category: "productivity", text: "Write a short message to my manager explaining that [the task] is delayed because [a supplier] has not delivered [the items]. Give the new expected date, say what I have done to chase the supplier, and suggest one workaround so the team can keep working." },
  { id: "productivity-764", title: "Request a new deadline after falling ill", category: "productivity", text: "Write a polite message to my manager asking for a new deadline on [the task] because I was ill for [number] days. Say when I am back at work, what I can finish this week, and the new date for the rest. Keep it brief and professional." },
  { id: "productivity-765", title: "Set a new deadline everyone agrees on", category: "productivity", text: "Give me a simple way to set a new deadline for [the project] that everyone on the team agrees on. List the steps to check how much work is left, how to ask each person for a fair date, and how to confirm the final date in writing." },
  { id: "productivity-766", title: "Delegate a task to a junior colleague", category: "productivity", text: "Write a clear message delegating [the task] to [a junior colleague]. Explain what to do, the result you expect, the deadline, and who to ask for help. Add one line offering to check the first draft together so they feel supported, not alone." },
  { id: "productivity-767", title: "Hand over billing work to a new staff member", category: "productivity", text: "Give me a simple step-by-step guide to hand over billing work to a new staff member at [a small shop]. Cover how to use the billing book or software, common mistakes to watch for, and a one-week check routine until they are confident doing it alone." },
  { id: "productivity-768", title: "Delegate stock checking in a small shop", category: "productivity", text: "Write a short instruction sheet for [a staff member] to check stock at [a small shop] every [day of the week]. List what to count, how to note shortages, and when to tell you. Keep it simple enough for someone doing stock checks for the first time." },
  { id: "productivity-769", title: "Let go of tasks you should delegate", category: "productivity", text: "Help me decide which of my tasks to delegate: [paste the list]. Sort them into tasks only I can do, tasks someone else can do with training, and tasks to stop doing. For each task to delegate, suggest who could take it and what to teach them first." },
  { id: "productivity-770", title: "Give clear instructions when delegating work", category: "productivity", text: "Give me five rules for giving clear instructions when I delegate [the task] to someone in my team. For each rule, give one example of a clear instruction and one example of a confusing one, so I can see the difference and avoid the common mistakes." },
  { id: "productivity-771", title: "Check delegated work without micromanaging", category: "productivity", text: "Give me a simple plan to check delegated work on [the task] without micromanaging. Suggest how often to check in, what three questions to ask, and how to give feedback when the work is good and when it needs fixing. Keep the tone trusting and supportive." },
  { id: "productivity-772", title: "Delegate customer follow-up calls to staff", category: "productivity", text: "Write a short guide for [a staff member] on making customer follow-up calls for [a small shop]. Include what to say first, three questions to ask, how to note the answers, and what to do if a customer is unhappy. Keep the guide friendly and easy to follow." },
  { id: "productivity-773", title: "Delegate packing and dispatch work", category: "productivity", text: "Write a simple instruction sheet for packing and dispatching orders at [a small shop]. List the steps in order, the checks before sealing a parcel, and what to write on the parcel. Add one line on what to do if an item is damaged or missing." },
  { id: "productivity-774", title: "Train someone to handle the cash counter", category: "productivity", text: "Give me a simple training plan to teach [a new helper] to handle the cash counter at [a small shop]. Cover opening the counter, giving change, handling UPI payments, and closing at night. Add a short checklist for the first week of supervised practice." },
  { id: "productivity-775", title: "Delegate social media replies to a team member", category: "productivity", text: "Write a short guide for [a team member] on replying to customer messages on [WhatsApp or Instagram] for [a small business]. Include the tone to use, three reply templates, and when to pass a message to you instead of answering it themselves." },
  { id: "productivity-776", title: "Welcome a new helper on day one", category: "productivity", text: "Write a warm welcome message for [a new helper] joining [a small shop or office] on [the date]. Tell them the start time, who will meet them, what to bring, and the plan for their first day. Keep it friendly, short and easy to understand." },
  { id: "productivity-777", title: "Make a first-week plan for new staff", category: "productivity", text: "Make a simple first-week plan for [a new staff member] joining [a small office] as [the role]. Give each day one main task to learn, one person to shadow, and one small job to do alone. End the week with a short chat to hear how they are settling in." },
  { id: "productivity-778", title: "Explain shop rules to a new helper", category: "productivity", text: "Write a simple one-page sheet explaining the rules of [a small shop] to a new helper. Cover timings, leave, dress, phone use, handling cash, and talking to customers. Use plain words and short points so a first-time worker can understand everything easily." },
  { id: "productivity-779", title: "Introduce a new employee to the team", category: "productivity", text: "Write a short message introducing [a new employee] to the team at [a small office]. Say their name, their role, one thing about their past work, and who they will work with. Add a warm line asking the team to help them settle in during the first week." },
  { id: "productivity-780", title: "Give a new helper their first task", category: "productivity", text: "Write clear instructions for [a new helper]'s first task: [describe the task]. Explain the steps in order, show what a good result looks like, give the time they have, and say who to ask if they get stuck. Keep the tone encouraging and simple." },
  { id: "productivity-781", title: "Check how a new employee is settling in", category: "productivity", text: "Give me ten short questions to ask a new employee after their first week at [a small office]. Cover what they found easy, what confused them, who helped them, and what they need next. Add one tip for listening well and acting on what they say." },
  { id: "productivity-782", title: "Prepare a simple joining kit for new staff", category: "productivity", text: "List what to include in a simple joining kit for a new staff member at [a small shop]. Cover the welcome note, the rules sheet, the duty list, and one small useful gift. Add a short checklist to prepare the kit before their first day." },
  { id: "productivity-783", title: "Teach a new helper to greet customers", category: "productivity", text: "Write a short training script to teach [a new helper] how to greet customers at [a small shop]. Include five polite greeting lines, what to say when the shop is busy, and how to handle a customer who seems upset. Keep the language simple and warm." },
  { id: "productivity-784", title: "Set work timings for a new part-time helper", category: "productivity", text: "Help me set clear work timings for a new part-time helper at [a small shop]. Suggest the days and hours, the lunch break, and how to handle swaps when they need a day off. Add one line on how to record their hours fairly each week." },
  { id: "productivity-785", title: "Give feedback to a new employee after week one", category: "productivity", text: "Write a short, kind feedback note for [a new employee] after their first week at [a small office]. Mention two things they did well, one thing to improve, and what to focus on next week. Keep the tone encouraging so they feel welcome and motivated." },
  { id: "productivity-786", title: "Make a simple task tracker for a team", category: "productivity", text: "Make a simple task tracker for a team of [number] people working on [the project]. It should show each task, who owns it, the due date, and whether it is done, in progress or stuck. Show it as a small table I can update every day." },
  { id: "productivity-787", title: "Track daily tasks on a whiteboard", category: "productivity", text: "Give me a simple whiteboard layout to track daily tasks for [number] staff at [a small shop]. Include three columns, to do, doing and done, plus a small space for urgent notes. Add one rule for updating the board at the start and end of each day." },
  { id: "productivity-788", title: "Follow up on overdue team tasks", category: "productivity", text: "Write a short message to the team about [number] overdue tasks on [the project]. List each task with its owner and original date, ask for a one-line update, and suggest new dates together. Keep the tone firm but fair, and thank those who are on track." },
  { id: "productivity-789", title: "Use a shared notebook to track team work", category: "productivity", text: "Explain how to use one shared notebook to track team work at [a small office] without any app. Cover what to write each morning, how to mark tasks done, and how to hand the notebook over at the end of the day. Add a simple page layout to copy." },
  { id: "productivity-790", title: "Track tasks for a festival event team", category: "productivity", text: "Make a simple task tracker for a team of [number] people organising [a festival event] at [the place]. List the tasks by week, give each task an owner and a date, and add a column for problems. Keep the tracker on one page so everyone can see it." },
  { id: "productivity-791", title: "Check team progress every Friday", category: "productivity", text: "Give me a simple Friday routine to check team progress on [the project]. List five questions to ask each person, how to note what is done and what is stuck, and how to set the plan for next week in 20 minutes. Keep the routine short and practical." },
  { id: "productivity-792", title: "Mark tasks done, delayed or stuck clearly", category: "productivity", text: "Give me a simple colour or symbol system to mark tasks as done, delayed or stuck for a team of [number] people. Explain what each mark means, how to update it daily, and one rule for what to do when a task stays stuck for more than two days." },
  { id: "productivity-793", title: "Track work across two shop branches", category: "productivity", text: "Help me track work across two branches of [a small business] in [two towns]. Suggest one shared daily update, who sends it, and how to compare sales and stock between branches. Add one rule for handling a task that needs both branches to act together." },
  { id: "productivity-794", title: "Make a simple progress chart for a project", category: "productivity", text: "Help me make a simple progress chart for [the project] that anyone in the team can read. Show the main stages, how much of each stage is done, and the next milestone date. Suggest how to update it weekly in under ten minutes." },
  { id: "productivity-795", title: "Review completed tasks with your team", category: "productivity", text: "Give me a simple way to review completed tasks with my team at the end of [the project]. List five questions to ask, how to note what worked well, and how to record one lesson for the next project. Keep the review to 30 minutes." },
  { id: "productivity-796", title: "Write a daily stand-up update in three lines", category: "productivity", text: "Write a short daily stand-up update for me about [the project]. Line one: what I finished yesterday. Line two: what I will do today. Line three: anything blocking me. Keep each line under 15 words and use simple, clear language." },
  { id: "productivity-797", title: "Run a five minute morning stand-up", category: "productivity", text: "Plan a five minute morning stand-up for a team of [number] people working on [the project]. Give each person 30 seconds to share yesterday's work, today's plan and any block. Add one rule to keep side talks for after the stand-up." },
  { id: "productivity-798", title: "Share a stand-up update on WhatsApp", category: "productivity", text: "Write a short stand-up update I can send on WhatsApp to my team about [the project]. Cover what I did yesterday, what I am doing today, and one thing I need help with. Keep it to four short lines with simple words and no long explanations." },
  { id: "productivity-799", title: "Report a blocker in a stand-up update", category: "productivity", text: "Write a short stand-up update reporting a blocker on [the task]. Say what is stuck, what I have already tried, what I need from the team, and the date by which I need it. Keep it clear and factual so the team can help quickly without a long meeting." },
  { id: "productivity-800", title: "Keep stand-up updates short and useful", category: "productivity", text: "Give me five rules to keep daily stand-up updates short and useful for a team of [number] people. For each rule, give one example of a good update and one example of a long, unclear update, so the team can see the difference and improve quickly." },
  { id: "productivity-801", title: "Stand-up update for a remote team", category: "productivity", text: "Give me a simple stand-up format for a remote team of [number] people in different towns working on [the project]. Each person posts three lines by [the time] every morning. Add one rule for replying to blockers and one tip to keep the chat tidy." },
  { id: "productivity-802", title: "Ask for help in a stand-up meeting", category: "productivity", text: "Write a short stand-up update asking for help with [the task]. Say what I have done so far, where I am stuck, and exactly what help I need and from whom. Keep it under 60 words and use a polite tone so asking for help feels normal." },
  { id: "productivity-803", title: "Summarise a week of stand-up updates", category: "productivity", text: "Here are our stand-up updates for the week on [the project]: [paste the updates]. Summarise them into a short weekly note: what got done, what is still stuck, and the three priorities for next week. Keep it to half a page in simple words." },
  { id: "productivity-804", title: "Stand-up update when nothing is blocked", category: "productivity", text: "Write a short stand-up update for a day when my work on [the project] is going smoothly and nothing is blocked. Cover yesterday's progress, today's plan, and one small win to share. Keep it positive, brief and under 50 words." },
  { id: "productivity-805", title: "Start stand-ups in a team that never had them", category: "productivity", text: "Help me start daily stand-ups in a team of [number] people that has never done them. Give me a one-week plan to introduce the habit, a simple three-line format, and tips to handle people who think stand-ups waste time. Keep the tone friendly and practical." },
  { id: "productivity-806", title: "Write handover notes before your leave", category: "productivity", text: "Write clear handover notes before my leave from [the start date] to [the end date]. List my open tasks, who will handle each one, the key contacts, and where important files are kept. Keep it to one page so my colleague can follow it easily." },
  { id: "productivity-807", title: "Hand over urgent work before a holiday", category: "productivity", text: "Help me hand over urgent work before a holiday starting [the date]. List the tasks that cannot wait, who will do each one, the deadlines, and the customer details they will need. Add one line on how to reach me only for a real emergency." },
  { id: "productivity-808", title: "Write a handover note for the cash counter", category: "productivity", text: "Write a short handover note for the cash counter at [a small shop] while I am on leave. Include the opening cash, pending bills, customers who owe money, and who to call if the billing machine fails. Keep it clear and easy to follow." },
  { id: "productivity-809", title: "Hand over customer work to a colleague", category: "productivity", text: "Write handover notes for my customers while I am away from [the start date] to [the end date]. For each customer, list the work in progress, the next step, and the date it is due. Add the name of the colleague who will look after each customer." },
  { id: "productivity-810", title: "Prepare a handover for a long leave", category: "productivity", text: "Help me prepare a handover for a long leave of [number] weeks starting [the date]. List every open task, the person taking it over, the training they need, and the files to share. Add a short plan for a handover meeting before I leave." },
  { id: "productivity-811", title: "Write a leave handover email to the team", category: "productivity", text: "Write a short email to the team about my leave from [the start date] to [the end date]. Say who will handle my work, list the three most urgent tasks with dates, and give the name and number of the person to contact. Keep it clear and polite." },
  { id: "productivity-812", title: "Hand over supplier contacts before leave", category: "productivity", text: "Write a short handover note listing my supplier contacts while I am on leave from [the start date]. For each supplier, give the name, phone number, what we buy from them, and the next order date. Add one line on who can approve a new order." },
  { id: "productivity-813", title: "Take over work from a colleague on leave", category: "productivity", text: "Give me a simple checklist for taking over work from a colleague who is going on leave from [the date]. List what to ask them before they go, what to read first, and how to handle their customers. Add one tip for asking questions without disturbing their holiday." },
  { id: "productivity-814", title: "Hand over passwords and files safely", category: "productivity", text: "Give me a safe, simple way to hand over passwords and files to a colleague before my leave. Cover what to share, what never to share by message, and how to take back access when I return. Add a short checklist to tick off on the last working day." },
  { id: "productivity-815", title: "Write a return-from-leave catch-up note", category: "productivity", text: "Write a short note to help me catch up after returning from leave on [the date]. List what to ask my colleague first, which emails to read first, and how to check what changed while I was away. Keep it to five simple steps I can finish in one morning." },
  { id: "productivity-816", title: "Ask a vendor for a better price", category: "productivity", text: "Write a polite message to [a vendor] asking for a better price on [the items] because I order [the quantity] every month. Mention the current price, the price I can afford, and ask what they can offer. Keep the tone friendly and businesslike throughout." },
  { id: "productivity-817", title: "Compare three vendors before ordering stock", category: "productivity", text: "Help me compare three vendors for [the items] before placing an order. Make a small table comparing price, quality, delivery time and payment terms, then give a clear recommendation on which vendor to choose and why in two short lines." },
  { id: "productivity-818", title: "Chase a late delivery from a supplier", category: "productivity", text: "Write a firm but polite message to [a supplier] chasing a late delivery of [the items] ordered on [the date]. State the original delivery date, explain how the delay affects my shop, and ask for a clear new date today. Keep it short and professional." },
  { id: "productivity-819", title: "Place a regular order with a supplier", category: "productivity", text: "Write a clear order message to [a supplier] for [the items] in [the quantity] at the agreed price of ₹[amount]. Confirm the delivery date, the delivery address, and the payment method. Ask them to reply confirming the order and the total amount." },
  { id: "productivity-820", title: "Report damaged goods to a supplier", category: "productivity", text: "Write a polite message to [a supplier] reporting that [the items] delivered on [the date] arrived damaged. Describe the damage briefly, ask for a replacement or refund, and say what proof I will send. Keep the tone calm, clear and businesslike." },
  { id: "productivity-821", title: "Send a thank-you message to a customer", category: "productivity", text: "Write a warm thank-you message to [a customer] after their purchase of [the items] worth ₹[amount]. Thank them for choosing our shop, mention one useful tip about the product, and invite them to visit again. Keep it short and friendly." },
  { id: "productivity-822", title: "Follow up with a customer after a service", category: "productivity", text: "Write a polite follow-up message to [a customer] one week after [the service]. Ask if everything is working well, offer help if they have any problem, and request a short review if they are happy. Keep it warm, brief and easy to reply to." },
  { id: "productivity-823", title: "Remind a customer about their appointment", category: "productivity", text: "Write a short reminder message to [a customer] about their appointment on [the date] at [the time] at [the place]. Confirm what they need to bring, give the phone number to call if they must reschedule, and ask them to reply to confirm." },
  { id: "productivity-824", title: "Ask a happy customer for a referral", category: "productivity", text: "Write a polite message asking [a happy customer] to refer our shop to their friends and family. Mention the service they liked, offer a small thank-you gift for each referral, and make it easy for them to share our number. Keep it warm and short." },
  { id: "productivity-825", title: "Wish a regular customer on their birthday", category: "productivity", text: "Write a warm birthday message to [a regular customer] on their birthday. Thank them for their support, wish them a happy year ahead, and offer a small birthday discount of [the percent] on their next visit. Keep it personal, short and cheerful." },
  { id: "productivity-826", title: "Start the tax return I keep delaying", category: "productivity", text: "Help me finally start my income tax return for [this financial year]. I keep putting it off because it feels confusing and boring. Break it into small first steps I can finish today in 30 minutes, list the papers I need, and tell me exactly what to do first." },
  { id: "productivity-827", title: "Begin the pending shop accounts work", category: "productivity", text: "My shop accounts for [last month] are pending and I keep avoiding them. Help me start today with a simple plan. Tell me which bills and receipts to gather first, how to sort them in one hour, and how to record sales and expenses without confusion." },
  { id: "productivity-828", title: "Finish the form I started months ago", category: "productivity", text: "I started filling [the name of the form] months ago and never finished it. Help me complete it this week. List what is already done, what is still missing, which documents I need, and give me a simple step by step plan to submit it before [the last date]." },
  { id: "productivity-829", title: "Start my pending college assignment today", category: "productivity", text: "My college assignment on [topic] is due on [date] and I have not started. Help me begin today. Break the assignment into small parts, tell me what to do in the first hour, and give me a simple daily plan so I can finish it without rushing at the end." },
  { id: "productivity-830", title: "Tackle the pending repair job at home", category: "productivity", text: "The [tap / fan / door] at home has needed repair for weeks and I keep delaying it. Help me tackle it this weekend. List the tools and parts I need, tell me how to check the problem safely, and explain when I should call a repair person instead of doing it myself." },
  { id: "productivity-831", title: "Start the pending insurance claim paperwork", category: "productivity", text: "My insurance claim for [the incident] is pending because the paperwork feels too long. Help me start it today. List every document I need, explain each form in simple words, and give me a checklist I can tick off as I finish each step." },
  { id: "productivity-832", title: "Begin the pending passport renewal application", category: "productivity", text: "My passport expires in [month] and I have not started the renewal. Help me begin today. List the documents I need, explain the online form step by step in simple words, and tell me how to book an appointment at [my nearest passport office]." },
  { id: "productivity-833", title: "Start the pending bank KYC update", category: "productivity", text: "My bank is asking for a KYC update and I keep putting it off. Help me finish it this week. Tell me which documents I need for [my bank account type], whether I can do it online or must visit the branch, and give me a simple step by step plan to complete it in one visit." },
  { id: "productivity-834", title: "Begin the pending school admission form", category: "productivity", text: "My child school admission form for [class] is still pending and the last date is [date]. Help me start it today. List the documents I need, explain each part of the form in simple words, and give me a checklist to finish and submit it before the last date." },
  { id: "productivity-835", title: "Start the pending visa documents folder", category: "productivity", text: "I need to prepare my visa documents for a trip to [country] and I keep delaying it. Help me start a folder today. List every document I need, tell me which ones take longest to arrange, and give me a simple order to collect them one by one." },
  { id: "productivity-836", title: "Start today with one tiny first step", category: "productivity", text: "I keep delaying [the task] because it feels too big. Help me find the tiniest first step I can do in five minutes. Tell me exactly what to do, what I need, and how to build on that small start tomorrow without feeling stressed or tired." },
  { id: "productivity-837", title: "Open the document I have been avoiding", category: "productivity", text: "I have been avoiding opening [the document] for days because I fear bad news or hard work. Help me open it today. Tell me what to look for first, how to read it calmly, and what three small actions I can take right after opening it." },
  { id: "productivity-838", title: "Make the phone call I keep postponing", category: "productivity", text: "I need to call [the person or office] about [the matter] and I keep postponing it. Help me make the call today. Write a short simple script for what to say, list the details I need before calling, and tell me the best time to call." },
  { id: "productivity-839", title: "Start a task with a five minute timer", category: "productivity", text: "Help me start [the task] using only a five minute timer. Tell me what to prepare before I start, what I should do in those five minutes, and how to decide whether to stop or continue when the timer rings. Keep the plan simple and easy to follow." },
  { id: "productivity-840", title: "Write the first line of a delayed report", category: "productivity", text: "I need to write a report on [topic] and I cannot write the first line. Help me begin today. Suggest three simple opening lines I can choose from, then give me a short outline of the next three parts so I can keep writing without stopping." },
  { id: "productivity-841", title: "Begin a task I dread with one easy step", category: "productivity", text: "I dread starting [the task] and it has been pending for weeks. Help me begin with the easiest step possible. Break the task into tiny steps, pick the simplest one for today, and tell me how to feel good about finishing just that one step." },
  { id: "productivity-842", title: "Start work after lunch without delay", category: "productivity", text: "After lunch I feel sleepy and delay my work for hours. Help me start work again by [time] today. Give me a simple routine for the first ten minutes after lunch, and suggest easy tasks to begin with before I move to harder work." },
  { id: "productivity-843", title: "Begin the task I moved to tomorrow twice", category: "productivity", text: "I moved [the task] to tomorrow twice already and I feel guilty. Help me begin it today without delay. Tell me the smallest part I can finish in 20 minutes, what I need to start, and how to stop myself from moving it again tomorrow." },
  { id: "productivity-844", title: "Start a delayed task before checking my phone", category: "productivity", text: "Every morning I check my phone first and delay [the task] for hours. Help me start the task before I touch my phone tomorrow. Give me a simple plan for the first 30 minutes of the day and tell me where to keep my phone so I am not tempted." },
  { id: "productivity-845", title: "Take the first step on a scary big task", category: "productivity", text: "[The task] feels scary and big, so I have not started. Help me take the first step today. Break it into small safe steps, tell me which step to do first, and explain how to keep going even when the task still feels big and difficult." },
  { id: "productivity-846", title: "Split my home shifting into small steps", category: "productivity", text: "I am shifting my home to [new area] next month and the work feels huge. Break the shifting into small weekly steps. Tell me what to do each week, how to pack room by room, and what to finish first so moving day is calm and easy." },
  { id: "productivity-847", title: "Break a college project into daily steps", category: "productivity", text: "My college project on [topic] is due in [number] weeks and I feel lost. Break it into small daily steps I can follow. Tell me what to finish each week, how much time to give each part, and how to check my progress every Sunday." },
  { id: "productivity-848", title: "Split a shop renovation into weekly steps", category: "productivity", text: "I want to renovate my shop in [area] but the work feels too big to start. Split the renovation into small weekly steps. Tell me what to do first, how to plan the budget in stages, and how to keep the shop open while the work goes on." },
  { id: "productivity-849", title: "Break a wedding plan into small tasks", category: "productivity", text: "My [sister / daughter] wedding is in [month] and planning feels overwhelming. Break the wedding plan into small tasks by week. Tell me what to book first, what to decide each month, and how to track everything without missing an important detail." },
  { id: "productivity-850", title: "Split writing a book into small chapters", category: "productivity", text: "I want to write a book about [topic] but I never start because it feels huge. Split the book into small chapters and weekly writing targets. Tell me how many words to write each day and how to keep going when I feel stuck." },
  { id: "productivity-851", title: "Break a big office report into parts", category: "productivity", text: "I have to write a big office report on [topic] by [date]. Break it into small parts I can finish one by one. Tell me what to write first, how much time each part needs, and how to put the parts together into a clean final report." },
  { id: "productivity-852", title: "Split a festival preparation into daily jobs", category: "productivity", text: "Diwali is in [number] weeks and I have a long list of preparation work. Split the preparation into small daily jobs. Tell me what to do each day, which jobs to finish first, and how to keep the house ready without rushing in the last two days." },
  { id: "productivity-853", title: "Break a garden makeover into weekend steps", category: "productivity", text: "I want to redo my small garden at home but I only have weekends free. Break the garden makeover into small weekend steps. Tell me what to do each weekend, what plants and materials I need for [my small garden], and how to keep the garden tidy between weekends." },
  { id: "productivity-854", title: "Split a business plan into clear stages", category: "productivity", text: "I want to start a small [type of business] in [my city] and need a business plan. Split the plan into clear stages I can finish one by one. Tell me what to research first, how to plan the money, and what to decide before I spend anything." },
  { id: "productivity-855", title: "Break a long course into weekly lessons", category: "productivity", text: "I joined a [number] month online course on [subject] and it feels too long. Break the course into small weekly lessons with clear targets. Tell me how much to study each week, how to revise, and how to finish the course on time." },
  { id: "productivity-856", title: "Work in 25 minute bursts today", category: "productivity", text: "Help me plan my work today in 25 minute bursts with short breaks in between. I need to finish [the task]. Tell me how many bursts I need, what to do in each burst, and what to do during the breaks so I stay fresh all day." },
  { id: "productivity-857", title: "Use short bursts to clean my room", category: "productivity", text: "My room is messy and cleaning it feels like a big job. Help me clean it in short bursts of 15 minutes. Tell me what to clean in each burst in [my bedroom], what order to follow, and how to keep the room tidy after I finish." },
  { id: "productivity-858", title: "Study in short bursts before exams", category: "productivity", text: "My exams start in [number] days and I cannot study for long hours. Help me study in short bursts of 30 minutes. Tell me what to study in each burst, how long the breaks should be, and how to revise quickly at the end of the day." },
  { id: "productivity-859", title: "Write in short bursts every evening", category: "productivity", text: "I want to write [a diary / a story / my notes] every evening but I never have time. Help me write in short bursts of 15 minutes after dinner. Tell me what to write each evening and how to build a small daily writing routine that lasts." },
  { id: "productivity-860", title: "Use short bursts for boring office work", category: "productivity", text: "I have boring office work like [data entry / filing] that I keep avoiding. Help me finish it in short bursts of 20 minutes. Tell me how to divide the work into bursts, what to do in the breaks, and how to stay focused during each burst." },
  { id: "productivity-861", title: "Work in bursts with a kitchen timer", category: "productivity", text: "Help me use my kitchen timer to work in short bursts on [the task]. Tell me how long each burst should be, how long the breaks should be, what to do when the timer rings, and how many bursts I need to finish the task today." },
  { id: "productivity-862", title: "Use short bursts to sort old papers", category: "productivity", text: "I have a big pile of old papers and bills to sort at home. Help me sort them in short bursts of 15 minutes. Tell me how to divide the pile, what to keep, what to throw away, and how to file the papers I keep in [my file folders]." },
  { id: "productivity-863", title: "Study in bursts with rest in between", category: "productivity", text: "I get tired quickly when I study for long hours. Help me plan study bursts of 25 minutes with proper rest in between. Tell me what to study in each burst, what to do during rest, and how many bursts I need each day before my exams in [subject]." },
  { id: "productivity-864", title: "Use short bursts to pack for a trip", category: "productivity", text: "I need to pack for a [number] day trip to [place] and I keep delaying it. Help me pack in short bursts of 20 minutes. Tell me what to pack in each burst, what to check before I close the bag, and how to avoid forgetting important things." },
  { id: "productivity-865", title: "Work in bursts on a hot afternoon", category: "productivity", text: "It is very hot this afternoon and I feel lazy, but I must finish [the task]. Help me work in short bursts of 15 minutes with cool breaks. Tell me what to do in each burst and how to use the breaks to drink water, rest, and stay fresh." },
  { id: "productivity-866", title: "Reward myself after finishing a report", category: "productivity", text: "I have to finish a report on [topic] by [date]. Help me plan a small reward for myself after I finish it. Suggest three simple rewards that cost little or nothing, and tell me how to enjoy the reward without feeling guilty about the work." },
  { id: "productivity-867", title: "Plan a small treat after study hours", category: "productivity", text: "I study for [number] hours every evening for my exams. Help me plan a small treat after my study hours each day. Suggest simple treats like a walk, a favourite snack, or music, and tell me how to keep the treat short so I can sleep on time." },
  { id: "productivity-868", title: "Earn a break after finishing housework", category: "productivity", text: "I have a long list of housework today, including [cleaning / washing / cooking]. Help me plan my work so I earn a proper break after finishing it. Tell me what order to follow, how long each job takes, and what break I can enjoy after the work is done." },
  { id: "productivity-869", title: "Reward myself after a week of steady work", category: "productivity", text: "I worked steadily all week on [the task] and I want to reward myself this Sunday. Help me choose a good reward that fits my budget of ₹[amount]. Suggest five simple ideas, and tell me how to enjoy the reward fully before starting a fresh week." },
  { id: "productivity-870", title: "Choose a treat after finishing my assignment", category: "productivity", text: "My assignment on [topic] is almost done and I want a treat after I submit it. Help me choose a simple treat that costs less than ₹[amount]. Suggest ideas like a favourite meal, a film, or a walk with friends, and tell me how to enjoy it without spending too much." },
  { id: "productivity-871", title: "Plan rewards that keep me working steadily", category: "productivity", text: "I lose interest in long tasks after a few days. Help me plan small rewards at each stage of [the task] so I keep working steadily. Tell me what reward to give after each stage and how to make the rewards simple, cheap, and worth waiting for." },
  { id: "productivity-872", title: "Reward myself after finishing a difficult call", category: "productivity", text: "I have to make a difficult phone call to [the person or office] about [the matter]. Help me plan a small reward for after the call. Tell me how to prepare for the call, what to say, and what nice thing I can do for myself once the call is over." },
  { id: "productivity-873", title: "Give myself a treat after cleaning the kitchen", category: "productivity", text: "My kitchen needs a deep clean today and I keep avoiding it. Help me plan the cleaning in steps and choose a small treat for after I finish. Tell me what order to clean in, how long it will take, and what treat will motivate me to start this [morning / evening]." },
  { id: "productivity-874", title: "Celebrate finishing a chapter with a walk", category: "productivity", text: "I want to celebrate finishing each chapter of [the book or course] with a short walk. Help me plan it simply. Tell me how long the walk should be, where to walk near [my area], and how to use the walk to think about what I just finished reading." },
  { id: "productivity-875", title: "Set a reward for finishing before lunch", category: "productivity", text: "I must finish [the task] before lunch today. Help me set a small reward I will enjoy only if I finish on time. Suggest three simple rewards, tell me how to stay focused till lunch, and explain how to keep the reward for tomorrow if I miss the time." },
  { id: "productivity-876", title: "Find my best hours for hard work", category: "productivity", text: "I do not know when I work best during the day. Help me find my best hours for hard work. Give me a simple way to track my energy for three days, and tell me how to use the results to plan my hardest tasks at the right time for [my job]." },
  { id: "productivity-877", title: "Plan hard work for my freshest hours", category: "productivity", text: "I feel freshest in [the morning / the evening] but I waste that time on easy jobs. Help me plan my hardest work for my freshest hours. Tell me which tasks to move there, what to do with easy tasks, and how to protect that time from interruptions." },
  { id: "productivity-878", title: "Use my morning energy for tough tasks", category: "productivity", text: "I feel most energetic in the morning but I spend it on small jobs. Help me use my morning energy for tough tasks. Tell me which tough task from [my task list] to start with tomorrow, how to prepare tonight, and how to keep my mornings free from distractions." },
  { id: "productivity-879", title: "Schedule deep work when I feel sharpest", category: "productivity", text: "I feel sharpest at [time of day] but my schedule is full of small jobs then. Help me schedule my deep work for that time. Tell me what counts as deep work for me, how to block that time, and what to tell others so they do not disturb me." },
  { id: "productivity-880", title: "Match tasks to my energy through the day", category: "productivity", text: "My energy goes up and down through the day, but I plan my tasks randomly. Help me match my tasks to my energy. Tell me which tasks suit high energy, medium energy, and low energy hours, using my task list for [today / this week]." },
  { id: "productivity-881", title: "Plan my day around my energy peaks", category: "productivity", text: "I want to plan my day around my energy peaks instead of fighting them. Help me build a simple day plan. Ask me when I feel most and least energetic during [a normal weekday], then suggest which tasks to place in each part of the day." },
  { id: "productivity-882", title: "Save easy tasks for my low energy hours", category: "productivity", text: "I waste my fresh hours on easy tasks and have no energy left for hard work. Help me save easy tasks for my low energy hours. List my easy and hard tasks for [today], and tell me the best order to do them." },
  { id: "productivity-883", title: "Find when I work best on weekends", category: "productivity", text: "I want to use my weekends well but I do not know when I work best. Help me find my best weekend work hours. Give me a simple plan to test morning, afternoon, and evening work over two weekends, and tell me how to compare the results for [my weekend tasks]." },
  { id: "productivity-884", title: "Use my evening energy for light work", category: "productivity", text: "After dinner I still have some energy, but I waste it on my phone. Help me use my evening energy for light work. Suggest easy tasks for [my work] like planning tomorrow, sorting papers, or reading, and tell me how to stop at a fixed time so I sleep well." },
  { id: "productivity-885", title: "Plan a workday that fits my energy", category: "productivity", text: "Help me plan a workday that fits my energy instead of fighting it. I wake at [time], feel tired at [time], and must finish [the task] today. Give me a simple hour by hour plan that puts hard work in my best hours and easy work in my tired hours." },
  { id: "productivity-886", title: "Get my energy back after lunch at work", category: "productivity", text: "After lunch I feel dull and slow at work, and my tasks pile up. Help me get my energy back by [time]. Give me a simple restart routine with fresh air, cold water, and one easy task first, then tell me how to move to harder work without feeling sleepy again." },
  { id: "productivity-887", title: "Stay awake after lunch at my desk", category: "productivity", text: "I sit at my desk after lunch and struggle to stay awake. Help me stay awake and alert till [time]. Suggest simple tricks like drinking water, stretching, changing tasks, and taking a short walk, without using too much tea or coffee." },
  { id: "productivity-888", title: "Plan light work for sleepy afternoons", category: "productivity", text: "My afternoons are always sleepy, so hard work never gets done then. Help me plan light work for my sleepy afternoons. List easy tasks from my list for [this week], and tell me how to use that time well instead of wasting it." },
  { id: "productivity-889", title: "Use a short walk to beat afternoon sleepiness", category: "productivity", text: "After lunch I feel very sleepy and cannot focus. Help me use a short walk to beat the sleepiness. Tell me when to walk, how long to walk, where to walk near [my home or office], and what to do right after the walk to start working again." },
  { id: "productivity-890", title: "Plan my lunch to avoid afternoon drowsiness", category: "productivity", text: "After a heavy lunch I feel drowsy and cannot work well. Help me plan my lunch to avoid afternoon drowsiness. Suggest light, filling lunch ideas with Indian food, tell me what to avoid, and explain how much water I should drink during the day in [summer]." },
  { id: "productivity-891", title: "Stay alert during afternoon study time", category: "productivity", text: "My afternoon study time is wasted because I feel sleepy after lunch. Help me stay alert while studying from [time] to [time]. Suggest simple ways to stay awake, which subjects to study when sleepy, and how to take short breaks without losing focus." },
  { id: "productivity-892", title: "Do easy tasks during the afternoon slump", category: "productivity", text: "From [time] to [time] every day I feel too sleepy for hard work. Help me list easy tasks I can do during the afternoon slump. Suggest tasks like replying to messages, filing papers, or tidying my desk, and tell me how to save hard tasks for later." },
  { id: "productivity-893", title: "Take a quick nap without ruining my day", category: "productivity", text: "I want to take a quick nap in the afternoon without ruining my night sleep. Help me plan a short nap after lunch. Tell me the best time to nap after [lunch], how long it should be, how to wake up on time, and what to do right after waking up." },
  { id: "productivity-894", title: "Plan a fresh start after the afternoon slump", category: "productivity", text: "After the afternoon slump my whole day feels wasted. Help me plan a fresh start at [time] each day. Tell me what to do in the first 15 minutes, which task to pick first, and how to finish the day with useful work done." },
  { id: "productivity-895", title: "Use water and fresh air to wake up", category: "productivity", text: "In the afternoon I feel dull and sleepy at my desk. Help me use water and fresh air to wake up. Tell me how much water to drink, when to step outside for fresh air near [my home], and how to use a short break near a window to feel fresh again." },
  { id: "productivity-896", title: "Plan proper breaks during a long workday", category: "productivity", text: "I work for [number] hours a day and never take proper breaks. Help me plan proper breaks during my long workday. Tell me when to take breaks, how long each break should be, and what to do during breaks so I come back fresh and focused." },
  { id: "productivity-897", title: "Take a real lunch break away from work", category: "productivity", text: "I eat lunch at my desk while working and never feel rested. Help me take a real lunch break away from work. Tell me how long the break should be, where to eat near [my office], and what to do during the break so I return to work feeling fresh." },
  { id: "productivity-898", title: "Use a ten minute break to refresh my mind", category: "productivity", text: "I work for hours without a break and my mind feels tired. Help me use a ten minute break to refresh my mind. Suggest simple things I can do in ten minutes, like walking, stretching, or drinking water, and tell me when to take this break during [my workday]." },
  { id: "productivity-899", title: "Plan breaks between study sessions", category: "productivity", text: "I study for long hours without breaks and forget what I read. Help me plan breaks between my study sessions. Tell me how long to study before each break, how long each break should be, and what to do during breaks to remember better for [my exams]." },
  { id: "productivity-900", title: "Take a screen free break every hour", category: "productivity", text: "I look at my phone or computer screen all day and my eyes feel tired. Help me take a screen free break every hour. Tell me what to do during each break, how long it should last, and how to remind myself to take it on time during [my workday]." },
  { id: "productivity-901", title: "Use a break to stretch and move around", category: "productivity", text: "I sit for hours while working and my back and neck hurt. Help me use my breaks to stretch and move around. Suggest five simple stretches I can do at my desk or at home, and tell me how often to do them during the day at [my desk]." },
  { id: "productivity-902", title: "Plan a rest day after a busy week", category: "productivity", text: "This week was very busy and I feel tired. Help me plan a proper rest day this [Sunday / holiday]. Tell me what to do and what to avoid, how to rest without feeling guilty, and how to prepare for the next week calmly." },
  { id: "productivity-903", title: "Take a proper break without feeling guilty", category: "productivity", text: "I feel guilty whenever I take a break from work, even when I am tired. Help me take a proper break without feeling guilty. Explain why breaks help me work better, and give me a simple break plan for today for [my work] that I can follow without worry." },
  { id: "productivity-904", title: "Use breaks to stay fresh till evening", category: "productivity", text: "By evening I feel tired and cannot finish my work. Help me use breaks during the day to stay fresh till evening. Tell me when to take breaks, how long they should be, and what to do in them so I still have energy at [time]." },
  { id: "productivity-905", title: "Plan short breaks while working from home", category: "productivity", text: "I work from home and forget to take breaks because no one reminds me. Help me plan short breaks through my workday at home in [my room]. Tell me when to take them, how long each should be, and what to do so I return to work feeling fresh." },
  { id: "productivity-906", title: "Spot early signs of burnout in my work", category: "productivity", text: "I feel tired all the time but I am not sure if it is burnout. Help me spot the early signs of burnout in my work. List the warning signs to watch for in [my daily work], and tell me what small changes I can make this week to feel better." },
  { id: "productivity-907", title: "Slow down before work burns me out", category: "productivity", text: "I have been working very hard for weeks and I feel exhausted. Help me slow down before work burns me out. Tell me which tasks I can delay, which ones I can share with others, and how to plan a lighter week without falling behind on [my tasks]." },
  { id: "productivity-908", title: "Plan a lighter week after a hectic month", category: "productivity", text: "Last month was very hectic and I feel drained. Help me plan a lighter week to recover. Tell me which tasks to keep, which to postpone, and how to use the lighter week to rest, catch up slowly, and prepare for the month ahead in [my work]." },
  { id: "productivity-909", title: "Set limits on extra work this month", category: "productivity", text: "I keep accepting extra work and now my days are too full. Help me set limits on extra work this month. Tell me how to decide which extra work to accept, how to refuse politely, and how to protect time for rest and family in [my week]." },
  { id: "productivity-910", title: "Recover from a tiring work week", category: "productivity", text: "This week was very tiring and I feel completely drained. Help me recover over the weekend. Tell me what to do on Saturday and Sunday, how much rest I need, and how to start Monday feeling fresh without thinking about [my work] all weekend." },
  { id: "productivity-911", title: "Balance work and rest this week", category: "productivity", text: "My work and rest are completely out of balance this week. Help me balance work and rest for the next seven days of [this week]. Give me a simple daily plan with work hours, break times, and rest time, so I can finish my tasks without feeling exhausted." },
  { id: "productivity-912", title: "Cut back my workload before I burn out", category: "productivity", text: "My workload keeps growing and I feel close to burning out. Help me cut back my workload this week. Tell me which tasks to drop, which to delay, and which to share, and explain how to do this without letting anyone down in [my office]." },
  { id: "productivity-913", title: "Plan rest after finishing a big project", category: "productivity", text: "I just finished a big project on [topic] and I feel exhausted. Help me plan proper rest for the next three days. Tell me what to do each day, how to slowly return to normal work, and how to celebrate the finish before starting something new." },
  { id: "productivity-914", title: "Keep my evenings free from work", category: "productivity", text: "Work keeps spilling into my evenings and I have no time for family. Help me keep my evenings free from work starting tomorrow. Tell me how to finish my tasks before [time], what to do with pending work, and how to switch off properly." },
  { id: "productivity-915", title: "Build a sustainable work pace for months", category: "productivity", text: "I work very hard for a few days and then crash for a week. Help me build a work pace I can keep for months. Tell me how many hours to work each day, when to rest, and how to track my energy so I stay steady without crashing during [my work]." },
  { id: "productivity-916", title: "Finish the book I started last month", category: "productivity", text: "I started reading [the book] last month and stopped halfway. Help me finish it this month. Tell me how many pages to read each day, when to read, and how to get back into the story after a long gap without starting from the beginning." },
  { id: "productivity-917", title: "Finish a half done course before starting another", category: "productivity", text: "I have a half done course on [subject] and I want to start a new one. Help me finish the old course first. Tell me how much is left, how to plan the remaining lessons, and how to avoid starting new courses before finishing old ones." },
  { id: "productivity-918", title: "Complete the painting I left unfinished", category: "productivity", text: "I started a painting of [subject] months ago and it is still unfinished. Help me complete it this month. Tell me what is left to do, what materials I need, and how to plan short painting sessions so I can finish it without pressure." },
  { id: "productivity-919", title: "Finish the sewing project in my cupboard", category: "productivity", text: "I have a half finished sewing project in my cupboard from [last year]. Help me finish it this month. Tell me what is left to sew, what materials I need, and how to plan short sewing sessions in the evening so I can complete it." },
  { id: "productivity-920", title: "Complete my pending online course modules", category: "productivity", text: "I have [number] pending modules left in my online course on [subject]. Help me complete them in [number] weeks. Tell me how many modules to finish each week, when to study, and how to revise quickly before the final test." },
  { id: "productivity-921", title: "Finish the garden work I started", category: "productivity", text: "I started digging and planting in my garden last month and left it half done. Help me finish the garden work this weekend. Tell me what is left to do, what tools and plants I need, and how to plan the work so the garden looks tidy by Sunday evening in [my home]." },
  { id: "productivity-922", title: "Complete a half written letter to my friend", category: "productivity", text: "I started writing a letter to my friend [name] months ago and never finished it. Help me complete it this week. Suggest how to continue from where I stopped, what to write about, and how to end the letter warmly before I post it." },
  { id: "productivity-923", title: "Finish the photo album I started for Diwali", category: "productivity", text: "I started making a photo album for Diwali last year and it is still unfinished. Help me finish it before this Diwali. Tell me which photos to choose, how to arrange them, and how to plan short sessions so the album is ready on time for [Diwali]." },
  { id: "productivity-924", title: "Complete the woodwork project in my garage", category: "productivity", text: "I started a small woodwork project in my garage and left it half done. Help me complete it in [number] weekends. Tell me what is left to build, what tools and wood I need, and how to work safely in short sessions till it is finished." },
  { id: "productivity-925", title: "Finish what I start instead of switching tasks", category: "productivity", text: "I keep starting new tasks before finishing old ones, so nothing gets done. Help me finish what I start instead of switching tasks. Give me a simple rule for choosing one task from [my task list], sticking to it, and only starting something new after I finish." },
  { id: "productivity-926", title: "Track my progress on a savings goal", category: "productivity", text: "I want to save ₹[amount] by [month] for [the purpose]. Help me track my progress simply. Tell me how much to save each week, how to record what I save, and how to check each month whether I am on track or need to save more." },
  { id: "productivity-927", title: "Track how much of my course I finished", category: "productivity", text: "I am doing a course on [subject] but I have lost track of how much I finished. Help me track my course progress. Tell me how to list the lessons, mark what is done, and check each week how much is left before the course ends." },
  { id: "productivity-928", title: "Track my progress on learning Tamil", category: "productivity", text: "I am learning Tamil and I want to track my progress. Help me build a simple tracker. Tell me what to measure each week for [my Tamil lessons], like new words and sentences I can speak, and how to review my progress every Sunday in ten minutes." },
  { id: "productivity-929", title: "Track my reading progress this month", category: "productivity", text: "I want to read [number] books this month but I never track my reading. Help me track my reading progress simply. Tell me how to record pages read each day, how to check my progress weekly, and what to do if I fall behind." },
  { id: "productivity-930", title: "Check how far I am on my project", category: "productivity", text: "I have been working on [the project] for weeks but I do not know how far I am. Help me check my progress honestly. Tell me how to list what is done, what is left, and how to work out whether I will finish by [the date]." },
  { id: "productivity-931", title: "Track my daily work hours this week", category: "productivity", text: "I want to know how many hours I actually work each day. Help me track my daily work hours this week. Give me a simple way to record start and finish times for [my job], count real work hours, and see where my time goes each day." },
  { id: "productivity-932", title: "Measure progress on my shop sales target", category: "productivity", text: "My shop sales target for this month is ₹[amount]. Help me measure my progress simply. Tell me how to record daily sales, how to check weekly whether I am on track, and what to do if sales are slow in the middle of the month." },
  { id: "productivity-933", title: "Track my progress on a writing goal", category: "productivity", text: "I want to write [number] words every week for [the project]. Help me track my writing progress. Tell me how to record my words each day, how to check my weekly total, and what to do when I miss a day so I can catch up." },
  { id: "productivity-934", title: "Check my progress halfway through a course", category: "productivity", text: "I am halfway through my course on [subject] and I feel lost. Help me check my progress honestly. Tell me how to list what I have learnt, what is still left, and how to plan the second half so I finish on time." },
  { id: "productivity-935", title: "Track small steps towards a big goal", category: "productivity", text: "My big goal is [the goal] and it feels too far away. Help me track the small steps towards it. Tell me how to break the goal into small steps, how to record each step I finish, and how to review my progress every month." },
  { id: "productivity-936", title: "Look back at my finished work this week", category: "productivity", text: "This week is ending and I want to look back at my finished work. Help me review what I completed, what is still pending, and what slowed me down. Give me a simple list of questions I can answer in ten minutes every Friday evening about [my work]." },
  { id: "productivity-937", title: "Count what I completed this week", category: "productivity", text: "I want to count what I actually completed this week instead of guessing. Help me make a simple list of finished tasks for [this week]. Tell me how to count small and big tasks fairly, and how to use the count to plan next week better." },
  { id: "productivity-938", title: "Review my work week in ten minutes", category: "productivity", text: "Help me review my work week in just ten minutes every [Friday / Sunday]. Give me five simple questions to answer about what I finished, what is pending, and what I learnt, so I can plan next week quickly without spending an hour on it." },
  { id: "productivity-939", title: "List my wins and pending work this week", category: "productivity", text: "Help me list my wins and my pending work for this week. I finished [the tasks] and I still need to do [the tasks]. Give me a simple two column format, and tell me how to use it to plan next week without feeling stressed." },
  { id: "productivity-940", title: "Check what slowed me down this week", category: "productivity", text: "This week felt slow and I did not finish much work. Help me check what slowed me down. Ask me simple questions about my days at [work], help me find the main reasons, and suggest one small change I can try next week to work better." },
  { id: "productivity-941", title: "Review my week before planning the next", category: "productivity", text: "Before I plan next week, I want to review this week properly. Help me review what I finished, what is still pending, and what I should carry forward. Give me a simple step by step review I can do in 15 minutes every Sunday evening for [my work]." },
  { id: "productivity-942", title: "Compare this week with last week fairly", category: "productivity", text: "I want to compare this week with last week to see if I improved. Help me compare them fairly. Tell me what to measure, like tasks finished and hours worked on [my project], and how to judge progress without being too hard on myself when a week was busy." },
  { id: "productivity-943", title: "Note what worked well in my week", category: "productivity", text: "This week some things went well and I want to remember them. Help me note what worked well in my week. Ask me simple questions about my best days at [work], help me find what helped me work well, and tell me how to repeat it next week." },
  { id: "productivity-944", title: "Review my unfinished tasks every Sunday", category: "productivity", text: "Every Sunday I want to review my unfinished tasks for the week. Help me build a simple Sunday review. Tell me how to list unfinished tasks for [my work], decide which ones to carry forward, which to drop, and how to start Monday with a clear plan." },
  { id: "productivity-945", title: "Write a short weekly work summary", category: "productivity", text: "Help me write a short weekly work summary for [this week] that I can keep in my notebook. Tell me what to include, like tasks finished, pending work, and lessons learnt, and give me a simple format I can fill in ten minutes every week." },
  { id: "productivity-946", title: "Celebrate finishing my first chapter today", category: "productivity", text: "I finished the first chapter of [the book or course] today and I want to celebrate. Help me plan a small celebration that costs nothing. Suggest simple ideas and tell me how to use this small win to keep going tomorrow." },
  { id: "productivity-947", title: "Mark a small win at the end of work", category: "productivity", text: "At the end of each workday I want to mark one small win. Help me do it in two minutes. Tell me what counts as a small win in [my work], how to write it down, and how to look back at my wins at the end of the week." },
  { id: "productivity-948", title: "Share a small win with my family", category: "productivity", text: "I finished [the task] today and I want to share this small win with my family. Help me tell them about it in a simple way. Suggest what to say at dinner, and how to enjoy the moment together without making it a big event." },
  { id: "productivity-949", title: "Celebrate a week of steady study", category: "productivity", text: "I studied steadily all week for my exams and I want to celebrate. Help me plan a small celebration this weekend that fits my budget of ₹[amount]. Suggest simple ideas and tell me how to enjoy it before starting a fresh week of study." },
  { id: "productivity-950", title: "Note three small wins from today", category: "productivity", text: "Help me note three small wins from today before I sleep. I finished [the tasks] and I want to remember them. Tell me how to write them down simply, and how to read them on a bad day to remind myself that I do make progress." },
  { id: "productivity-951", title: "Celebrate finishing a tough task alone", category: "productivity", text: "I finished a tough task on [topic] all by myself and no one noticed. Help me celebrate it in a small way. Suggest simple ideas that cost nothing, and tell me how to feel proud of my own work without waiting for praise from others." },
  { id: "productivity-952", title: "Celebrate reaching halfway on a project", category: "productivity", text: "I reached halfway on [the project] today and I want to celebrate. Help me plan a small celebration that fits my budget. Suggest simple ideas, and tell me how to use this moment to plan the second half with fresh energy." },
  { id: "productivity-953", title: "Celebrate my first sale in my shop", category: "productivity", text: "I made my first sale of ₹[amount] in my new shop today and I want to celebrate. Help me plan a small celebration with my family. Suggest simple ideas that cost little, and tell me how to use this win to keep working hard tomorrow." },
  { id: "productivity-954", title: "Mark progress on a long project today", category: "productivity", text: "My project on [topic] is very long and I feel like I am getting nowhere. Help me mark the progress I made today. Tell me how to list what I finished, however small, and how to see that small steps add up over weeks." },
  { id: "productivity-955", title: "Celebrate a small win without spending money", category: "productivity", text: "I finished [the task] and I want to celebrate without spending money. Help me find free ways to celebrate a small win. Suggest ideas like a walk, a favourite meal at home, or time with family, and tell me how to enjoy the moment fully." },
  { id: "productivity-956", title: "Salvage a day when nothing gets done", category: "productivity", text: "Today nothing got done and I feel like the day is wasted. Help me salvage the rest of the day. Tell me one small useful thing from [my task list] I can still do before dinner, and how to end the day calmly so tomorrow starts fresh." },
  { id: "productivity-957", title: "Do one small thing on a wasted day", category: "productivity", text: "Today feels completely wasted and I have done nothing useful. Help me do just one small thing before the day ends. Suggest three easy options from my pending tasks for [this week], and tell me how to pick the simplest one and finish it in 15 minutes." },
  { id: "productivity-958", title: "End a slow day without feeling guilty", category: "productivity", text: "Today was very slow and I finished almost nothing. Help me end the day without feeling guilty. Explain why slow days happen, tell me what to do in the evening after [a slow day], and how to plan a fresh start for tomorrow morning." },
  { id: "productivity-959", title: "Recover after a day of zero progress", category: "productivity", text: "Yesterday I made zero progress on [the task] and I feel bad about it. Help me recover today. Tell me how to start with one small step, how to avoid thinking about yesterday, and how to plan today so I finish something useful." },
  { id: "productivity-960", title: "Plan a fresh start after a lazy day", category: "productivity", text: "Yesterday was a lazy day and I did no work at all. Help me plan a fresh start today. Tell me what to do in the first hour, which task from [my task list] to pick first, and how to keep the day simple so I do not feel overwhelmed again." },
  { id: "productivity-961", title: "Use a bad day to plan tomorrow well", category: "productivity", text: "Today was a bad day and nothing went as planned. Help me use the evening to plan tomorrow well. Tell me how to list tomorrow tasks for [my work], pick the most important one, and prepare everything tonight so tomorrow starts smoothly." },
  { id: "productivity-962", title: "Handle a day ruined by power cuts", category: "productivity", text: "Today power cuts ruined my work plans and I finished nothing. Help me handle a day ruined by power cuts. Tell me what work I can do without power in [my home], how to use the time well, and how to catch up tomorrow without stress." },
  { id: "productivity-963", title: "Do light work on a low energy day", category: "productivity", text: "Today I have very low energy and cannot do hard work. Help me do light work instead of doing nothing. Suggest easy tasks from my list for [today], like sorting papers or planning, and tell me how to use the day well without pushing myself too hard." },
  { id: "productivity-964", title: "Stop a bad day from becoming a bad week", category: "productivity", text: "Yesterday was a bad day and I am worried it will spoil my whole week. Help me stop one bad day from becoming a bad week. Tell me what to do today to save [my week], how to reset my plan, and how to keep the rest of the week on track." },
  { id: "productivity-965", title: "Accept a slow day and move on", category: "productivity", text: "I had a slow day with almost no work done and I keep thinking about it. Help me accept the slow day and move on. Explain why slow days are normal, and give me a simple plan to start tomorrow fresh without carrying the guilt about [today]." },
  { id: "productivity-966", title: "Restart my studies after missing a week", category: "productivity", text: "I missed a whole week of studies for [the exam] because of [the reason]. Help me restart today. Tell me how to revise what I missed quickly, what to study first, and how to catch up without studying for very long hours." },
  { id: "productivity-967", title: "Get back to work after a festival break", category: "productivity", text: "After the [festival] break I find it hard to get back to work. Help me return to work smoothly tomorrow. Tell me what to do on the first day back, which tasks to start with, and how to get my energy and focus back in a few days." },
  { id: "productivity-968", title: "Restart my project after a week away", category: "productivity", text: "I was away for a week and my project on [topic] has stopped completely. Help me restart it today. Tell me how to check where I stopped, what to do first, and how to rebuild my daily work rhythm in the next three days." },
  { id: "productivity-969", title: "Restart a course after missing ten days", category: "productivity", text: "I missed ten days of my course on [subject] and I feel behind. Help me restart the course today. Tell me how to catch up on missed lessons quickly, what to study first, and how to keep up with the class from now on." },
  { id: "productivity-970", title: "Get back to my shop work after a holiday", category: "productivity", text: "My shop was closed for a holiday and now I feel lazy about reopening. Help me get back to my shop work tomorrow. Tell me what to check first in [my shop], how to arrange stock and bills, and how to serve customers well on the first day back." },
  { id: "productivity-971", title: "Restart my writing after a long break", category: "productivity", text: "I stopped writing [my diary / my book / my notes] for a month and I want to restart. Help me restart my writing this week. Tell me how to read what I wrote before, how to write a little each day, and how to keep going without pressure." },
  { id: "productivity-972", title: "Pick up my savings plan after a missed month", category: "productivity", text: "I missed a whole month of my savings plan for [the purpose] and I feel like giving up. Help me pick it up again. Tell me how to check how much I have saved, how to adjust my monthly amount, and how to catch up slowly without stress." },
  { id: "productivity-973", title: "Restart my reading after a busy month", category: "productivity", text: "I did not read anything last month because I was very busy. Help me restart my reading this week. Suggest a short and easy book to begin with from [my shelf], tell me when to read each day, and how to finish one book before starting another." },
  { id: "productivity-974", title: "Get back on track after a family function", category: "productivity", text: "A big family function kept me busy for a week and my work is pending. Help me get back on track today. Tell me how to list pending tasks for [my work], which ones to finish first, and how to catch up in the next three days without working late nights." },
  { id: "productivity-975", title: "Restart work gently after being unwell", category: "productivity", text: "I was unwell for a week and now I need to restart work gently. Help me return to work slowly. Tell me how many hours to work on the first days back at [work], which tasks to do first, and how to rest enough so I do not fall ill again." },
  { id: "productivity-976", title: "Get through boring data entry work", category: "productivity", text: "I have boring data entry work for [the shop / the office] that I keep avoiding. Help me get through it today. Tell me how to divide the work into short bursts, what to do during breaks, and how to check my work so I do not make mistakes." },
  { id: "productivity-977", title: "Finish filing old bills and papers", category: "productivity", text: "I have a pile of old bills and papers that need filing. Help me finish filing them this weekend. Tell me how to sort them by month, what to keep and what to throw away, and how to file them so I can find any bill quickly later in [my files]." },
  { id: "productivity-978", title: "Do boring cleaning work without delay", category: "productivity", text: "The [bathroom / store room / balcony] needs cleaning and I keep delaying it. Help me do this boring cleaning work today. Tell me what order to clean in, what cleaning items I need, and how to finish it in less than one hour." },
  { id: "productivity-979", title: "Finish copying notes I keep avoiding", category: "productivity", text: "I need to copy my class notes for [subject] but I keep avoiding it because it is boring. Help me finish copying them this week. Tell me how many pages to copy each day, how to make the notes neat, and how to check that I copied everything correctly." },
  { id: "productivity-980", title: "Get through a dull report I must read", category: "productivity", text: "I must read a dull report on [topic] for work, but I cannot focus on it. Help me get through it today. Tell me how to read it in short parts, what to note down, and how to write a short summary at the end so I remember the main points." },
  { id: "productivity-981", title: "Do boring bank work without putting it off", category: "productivity", text: "I need to visit the bank for [the work] and I keep putting it off because it is boring. Help me do it this week. Tell me what documents to carry, the best time to visit to avoid a long queue, and how to finish the work in one visit." },
  { id: "productivity-982", title: "Finish sorting old clothes for donation", category: "productivity", text: "I have a cupboard full of old clothes to sort for donation. Help me finish sorting them this weekend. Tell me how to decide what to keep, what to donate, and what to throw away, and how to pack the donation clothes neatly for giving away to [a charity]." },
  { id: "productivity-983", title: "Get through repetitive typing work faster", category: "productivity", text: "I have repetitive typing work for [the office / my course] and it takes forever. Help me get through it faster. Tell me how to divide the work into parts, how to type more quickly without mistakes, and how to take breaks so my hands and eyes do not get tired." },
  { id: "productivity-984", title: "Do a boring task with music and breaks", category: "productivity", text: "I have a boring task, [the task], that I must finish today. Help me do it with music and breaks. Tell me how to divide the task into short parts, what kind of music to play, and how long the breaks should be so I stay cheerful till the end." },
  { id: "productivity-985", title: "Finish boring homework before playing", category: "productivity", text: "My child keeps delaying boring homework to play first. Help me plan a simple routine where homework finishes before play. Tell me how to divide the homework into short parts for [my child], what breaks to give, and how to make playtime the reward after homework is done." },
  { id: "productivity-986", title: "Work steadily towards a Friday deadline", category: "productivity", text: "I have a deadline this Friday for [the task] and I want to work steadily. Help me plan my work from today till Friday. Tell me what to finish each day, how many hours to work, and how to check each evening that I am on track." },
  { id: "productivity-987", title: "Plan daily work before a college deadline", category: "productivity", text: "My college deadline for [the assignment] is in [number] days. Help me plan my daily work till the deadline. Tell me what to do each day, how much time to spend, and how to leave one full day at the end for checking and corrections." },
  { id: "productivity-988", title: "Keep a steady pace before an exam", category: "productivity", text: "My exams start in [number] weeks and I study in bursts, then stop for days. Help me keep a steady pace till the exams. Tell me how much to study each day, how to revise weekly, and how to keep going on days when I feel tired." },
  { id: "productivity-989", title: "Work a little daily before a big deadline", category: "productivity", text: "I have a big deadline in [number] weeks for [the project]. Help me work a little every day instead of rushing at the end. Tell me how much to do daily, how to track my progress, and how to stay steady even on busy days." },
  { id: "productivity-990", title: "Plan my last ten days before a deadline", category: "productivity", text: "My deadline for [the task] is ten days away and I still have a lot left. Help me plan my last ten days carefully. Tell me what to finish each day, which parts need the most time, and how to keep the last day free for checking." },
  { id: "productivity-991", title: "Stay steady when a deadline feels far away", category: "productivity", text: "My deadline for [the task] is two months away, so I keep delaying the work. Help me stay steady even though the deadline feels far away. Tell me how to set small weekly targets and how to keep working a little each week." },
  { id: "productivity-992", title: "Work daily on a project due next month", category: "productivity", text: "My project on [topic] is due next month and I have barely started. Help me work on it daily from today. Tell me how much time to give it each day, what to finish each week, and how to track my progress so I finish on time." },
  { id: "productivity-993", title: "Break deadline work into daily targets", category: "productivity", text: "I have a lot of work to finish before [the date] and it feels too much. Help me break the deadline work into small daily targets. Tell me what to finish each day, how long each target takes, and how to adjust the plan if I miss a day." },
  { id: "productivity-994", title: "Keep working when a deadline moves closer", category: "productivity", text: "My deadline for [the task] is getting closer and I feel stressed. Help me keep working steadily instead of panicking. Tell me what to focus on first, how to plan my remaining days, and how to stay calm while I finish the work." },
  { id: "productivity-995", title: "Finish early instead of working till midnight", category: "productivity", text: "I always finish my work at midnight before a deadline. Help me finish early this time for [the task]. Tell me how to plan backwards from the deadline, what to finish each day, and how to stop working at [time] every evening." },
  { id: "productivity-996", title: "Avoid a last minute rush before exams", category: "productivity", text: "My exams start in [number] weeks and I always rush in the last days. Help me avoid a last minute rush this time. Tell me what to study each week, when to start revision, and how to keep the last two days free for rest and light revision." },
  { id: "productivity-997", title: "Stop leaving festival shopping till the last day", category: "productivity", text: "Every festival I leave my shopping till the last day and the shops are crowded. Help me finish my festival shopping early this time. Tell me what to buy each week for [Diwali], how to make a list, and how to avoid the last day rush." },
  { id: "productivity-998", title: "Avoid rushing my tax filing every year", category: "productivity", text: "Every year I rush my tax filing in the last week and feel stressed. Help me avoid rushing it this year. Tell me when to start in [the new financial year], what papers to collect each month, and how to finish the filing at least two weeks before the last date." },
  { id: "productivity-999", title: "Prepare early for a school admission deadline", category: "productivity", text: "My child school admission deadline is [date] and I do not want to rush. Help me prepare early. Tell me which documents to collect first, when to fill the form, and how to check everything a week before the deadline so nothing is missed." },
  { id: "productivity-1000", title: "Avoid last minute packing before a train", category: "productivity", text: "I always pack at the last minute before a train journey and forget things. Help me avoid last minute packing for my trip to [place] on [date]. Tell me what to pack each day before the trip, and how to check my bag the night before." },
  { id: "productivity-1001", title: "Stop rushing project work at the last hour", category: "productivity", text: "I always rush my project work in the last hour before submitting it. Help me stop rushing this time for [the project]. Tell me how to plan the work backwards, what to finish each day, and how to leave time for checking before I submit." },
  { id: "productivity-1002", title: "Plan early for a family wedding next month", category: "productivity", text: "My family wedding is next month and I have many tasks to do. Help me plan early so I avoid a last minute rush. Tell me what to do each week before [the wedding], what to book first, and how to keep a simple list so nothing important is missed." },
  { id: "productivity-1003", title: "Avoid the last day rush for bill payments", category: "productivity", text: "I always pay my bills on the last day and sometimes miss the date. Help me avoid the last day rush for bill payments. Tell me how to list my bills for [this month], when to pay each one, and how to set simple reminders so I never pay late again." },
  { id: "productivity-1004", title: "Start early to avoid a last minute panic", category: "productivity", text: "I have [the task] due on [date] and I know I will panic at the last minute. Help me start early this time. Tell me the first small step to take today, how to plan the work week by week, and how to stay calm as the date comes closer." },
  { id: "productivity-1005", title: "Prepare my presentation days before the date", category: "productivity", text: "I have to give a presentation on [topic] on [date] and I usually prepare at the last minute. Help me prepare days before the date. Tell me what to prepare each day, how to practise, and how to check my slides the day before." },
  { id: "productivity-1006", title: "Keep momentum on a six month project", category: "productivity", text: "My project on [topic] will take six months and I lose interest after a few weeks. Help me keep momentum going. Tell me how to set monthly targets, how to celebrate small progress, and what to do when I feel bored or stuck." },
  { id: "productivity-1007", title: "Stay interested in a long course", category: "productivity", text: "I joined a long course on [subject] and I am losing interest after one month. Help me stay interested till the end. Tell me how to set small weekly goals, how to make study fun, and what to do when a topic feels boring." },
  { id: "productivity-1008", title: "Keep going on a slow home renovation", category: "productivity", text: "My home renovation is going very slowly and I feel like giving up. Help me keep going. Tell me how to list what is done, what is left, and how to plan the remaining work in small steps so the house is finished by [month]." },
  { id: "productivity-1009", title: "Stay motivated through a long job search", category: "productivity", text: "I have been searching for a job for [number] months and I feel tired. Help me stay motivated through this long job search. Tell me how to plan my applications each week, how to handle rejections, and how to keep improving my skills while I wait." },
  { id: "productivity-1010", title: "Keep momentum after the first excitement fades", category: "productivity", text: "I start new projects with great excitement, but after two weeks I lose interest. Help me keep momentum after the first excitement fades. Tell me how to set small weekly targets and how to remind myself why I started [the project]." },
  { id: "productivity-1011", title: "Work weekly on a year long goal", category: "productivity", text: "My goal for this year is [the goal] and it feels very far away. Help me work on it weekly. Tell me how to break it into monthly steps, what to do each week, and how to check my progress at the end of every month." },
  { id: "productivity-1012", title: "Keep a long project moving during festivals", category: "productivity", text: "Festivals keep interrupting my long project on [topic] and I lose momentum. Help me keep the project moving during festival season. Tell me how to plan light work for festival days and how to restart quickly after each festival ends." },
  { id: "productivity-1013", title: "Stay on track with a long writing project", category: "productivity", text: "I am writing [a book / a thesis / a long report] and it will take months. Help me stay on track. Tell me how many words to write each week, how to handle weeks when I write nothing, and how to keep the project moving till I finish." },
  { id: "productivity-1014", title: "Keep momentum when progress feels slow", category: "productivity", text: "My work on [the project] feels very slow and I cannot see progress. Help me keep momentum going. Tell me how to measure small progress, how to set tiny weekly targets, and how to keep working even when results are not visible yet." },
  { id: "productivity-1015", title: "Restart momentum on a stalled project", category: "productivity", text: "My project on [topic] has stalled for a month and I have lost all momentum. Help me restart momentum this week. Tell me how to check where I stopped, what small step to take first, and how to build a simple daily work plan again." },
  { id: "productivity-1016", title: "Review a full month of my work", category: "productivity", text: "This month is ending and I want to review a full month of my work. Help me do a simple monthly review. Tell me what to look at, like tasks finished, money spent, and time used in [my work], and how to use the review to plan next month better." },
  { id: "productivity-1017", title: "Compare my work across two months", category: "productivity", text: "I want to compare my work across this month and last month. Help me compare them fairly. Tell me what to measure, like tasks finished and hours worked in [my work], and how to find what improved and what needs more attention next month." },
  { id: "productivity-1018", title: "List what I finished this month", category: "productivity", text: "Help me list everything I finished this month, big and small. I worked on [the tasks] and I want a clear record. Tell me how to list them simply, how to count them fairly, and how to use the list to feel good about my progress." },
  { id: "productivity-1019", title: "Find my busiest week this month", category: "productivity", text: "I want to find my busiest week this month and learn from it. Help me look back at my four weeks. Tell me how to compare the weeks by tasks finished and hours worked in [my job], and what to change next month so no week feels too heavy." },
  { id: "productivity-1020", title: "Review my month before planning the next", category: "productivity", text: "Before I plan next month, I want to review this month properly. Help me review what I finished, what is pending, and what I learnt. Give me a simple monthly review I can do in 30 minutes on the last Sunday of the month for [my work]." },
  { id: "productivity-1021", title: "Set a finish date for my pending project", category: "productivity", text: "My project on [topic] has no finish date, so it never gets done. Help me set a realistic finish date. Tell me how to work out how much time I need, how to pick a date I can keep, and how to tell others about the date so I stay committed." },
  { id: "productivity-1022", title: "Stick to a finish date I promised", category: "productivity", text: "I promised to finish [the task] by [date] but I keep slipping. Help me stick to the finish date I promised. Tell me how to plan backwards from the date, what to do each week, and how to handle delays without moving the date again." },
  { id: "productivity-1023", title: "Move a finish date without giving up", category: "productivity", text: "I cannot finish [the task] by [the date] and I feel like giving up. Help me move the finish date without giving up. Tell me how to pick a new realistic date, how to plan the remaining work, and how to stay honest about the delay." },
  { id: "productivity-1024", title: "Set a realistic finish date for a big task", category: "productivity", text: "[The task] is big and I never know how long it will take. Help me set a realistic finish date. Tell me how to break the task into parts, how to estimate the time for each part, and how to add extra days for delays and busy days." },
  { id: "productivity-1025", title: "Celebrate meeting a finish date on time", category: "productivity", text: "I finished [the task] on time by [the date] and I want to celebrate. Help me plan a small celebration. Suggest simple ideas that fit my budget, and tell me how to share the news with my family and thank everyone who helped me." },
];
